// temporal prior.
const MEDIAPIPE_REFRESH_INTERVAL: Duration = Duration::from_secs(5);
const MEDIAPIPE_PERIODIC_RETRY: Duration = Duration::from_millis(100);
// A fine slice can retain a geometrically plausible context patch after the
// subject has left the ROI. Give acquired local reckoning a short wall-clock
// lease across a blink/gate flicker, but revoke it in less than one second of
// continuous invalid geometry. Missed frames never renew this lease; only a
// newly verified anatomy observation does. Keeping this time-based makes the
// decision invariant to exposure, camera FPS, and asynchronous worker cadence.
const INVALID_EYE_GEOMETRY_PRESENCE_LEASE: Duration = Duration::from_millis(800);
const NO_ANATOMY_REACQUIRE_AFTER: Duration = INVALID_EYE_GEOMETRY_PRESENCE_LEASE;
// The temporal matcher publishes after the context packet which precedes its
// eye frame. Carry a strong, iris-anchored result just far enough forward for
// that next context packet to consult it before the legacy border miss counter
// can request a sensor-mode switch. This is deliberately much shorter than the
// invalid-geometry lease: it smooths one or two weak Canny presentations but
// yields promptly when persistent same-scene tracks actually disappear.
const TEMPORAL_FEATURE_PRESENCE_HANDOFF_GRACE: Duration = Duration::from_millis(650);
// A successful coarse relocation must be followed by fine frames before
// another camera-mode switch, but a bad semantic landing must not suppress
// reacquisition for the older five-second pupil-health diagnostic window.
// Use the same subsecond invalid-geometry lease so a continuously wrong crop
// can be rejected promptly at every camera FPS.
const MEDIAPIPE_FINE_SETTLE_AFTER_RELOCATION: Duration = INVALID_EYE_GEOMETRY_PRESENCE_LEASE;
// A coarse scan currently consumes almost the entire 450 ms semantic-freshness
// interval.  Never let its deadline immediately preempt the restored fine
// stream: prove a useful burst of complete paired 1x1 eye exposures first.
// Twelve sets at the measured ~42 Hz fine rate leave the combined coarse/fine
// cycle comfortably above the required ten RAW ROI sets per second.
const MEDIAPIPE_MIN_FINE_SETS: u32 = 12;
const FINE_SENSOR_REFRAME: &str = "FINE_SENSOR_REFRAME:";
const FATAL_RAW_CADENCE: &str = "FATAL_RAW_CADENCE:";
// At the normal live viewer's measured ~10 Hz floor, a quarter-second interval
// means at least one complete exposure was visibly missed. This is the short-
// exposure floor; long manual integrations derive a larger bounded deadline
// from their already exposure-dependent required set rate.
const MAX_RAW_SET_GAP: Duration = Duration::from_millis(250);
const MAX_LONG_EXPOSURE_RAW_SET_GAP: Duration = Duration::from_millis(750);
const MAX_TRACKING_QUEUE_AGE: Duration = Duration::from_millis(200);
// Never present a packet older than MAX_TRACKING_QUEUE_AGE.  The independent
// socket reader applies MAX_RAW_SET_GAP to actual sensor arrivals, so consumer
// queue age must not reuse that sensor-cadence deadline: a bounded camera-control
// or scheduler excursion can make an otherwise current sensor packet 250-350 ms
// old. Shed those packets until the consumer reaches the live edge. A queue
// older than 350 ms remains a hard failure, well before the bounded packet queue
// could conceal a persistently slow tracker.
const MAX_RECOVERABLE_TRACKING_QUEUE_AGE: Duration = Duration::from_millis(350);
// VCM status/probe transactions are bounded individually, but one analysis
// exposure can legitimately issue a GET, SET, and STATUS transaction while
// also scoring the native eye. The independent socket reader proves that RAW
// sensor arrivals continued during that interval. Permit the consumer to shed
// (never present) that bounded control backlog without weakening the ordinary
// 350 ms tracker-overrun guard. The packet queue remains the final hard bound.
const MAX_CAMERA_CONTROL_QUEUE_AGE: Duration = Duration::from_millis(1_000);
// First-frame Canny seeding, layer allocation, auto-exposure writes, and
// Wayland buffer allocation coincide on a fresh stream. Discard stale startup
// packets until the consumer reaches the live edge; do not process a delayed
// frame or weaken the steady-state queue deadline.
const TRACKING_QUEUE_WARMUP: Duration = Duration::from_secs(4);

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TrackingQueueAction {
    Consume,
    DropWarmup,
    DropBacklog,
    Fatal,
}

fn tracking_queue_action(
    stream_age: Duration,
    queue_age: Duration,
    bounded_camera_control_active: bool,
) -> TrackingQueueAction {
    if queue_age <= MAX_TRACKING_QUEUE_AGE {
        TrackingQueueAction::Consume
    } else if stream_age < TRACKING_QUEUE_WARMUP {
        TrackingQueueAction::DropWarmup
    } else if queue_age <= MAX_RECOVERABLE_TRACKING_QUEUE_AGE {
        TrackingQueueAction::DropBacklog
    } else if bounded_camera_control_active && queue_age <= MAX_CAMERA_CONTROL_QUEUE_AGE {
        TrackingQueueAction::DropBacklog
    } else {
        TrackingQueueAction::Fatal
    }
}
// Key repeat may arrive much faster than a bounded camera-control round trip.
// Coalesce those events and issue at most one physical VCM/exposure write per
// interval so manual tuning cannot starve the lossless RAW packet consumer.
const MANUAL_CAMERA_STEP_MIN_INTERVAL: Duration = Duration::from_millis(100);
const PUPIL_CENTER_HEALTH: &str = "PUPIL_CENTER_HEALTH:";
const FATAL_ROUGH_FOCUS: &str = "FATAL_ROUGH_FOCUS:";
const MAX_REJECTION_CAPTURES: usize = 64;
const ROTATION_CENTER_HISTORY: Duration = Duration::from_secs(3);
const ROTATION_CENTER_MIN_OBSERVATIONS: usize = 12;
const ROTATION_POSE_STILL_MOTION_MAX: f64 = 35.0;
const ROTATION_POSE_FIRM_START_FRAMES: u32 = 4;
const ROTATION_POSE_FIRM_FULL_FRAMES: u32 = 24;
const OUTER_IRIS_MAX_CONTRACTION_PER_SECOND: f64 = 0.20;
const OUTER_IRIS_MAX_EXPANSION_PER_SECOND: f64 = 0.20;
const SAM31_RAW_SUPPORT_DECISIVE: f64 = 3.50;
const SAM31_RESULT_MAX_AGE_NS: u64 = 900_000_000;
// The pupil is physiologically dynamic, but it cannot change projected
// anatomical area discontinuously between consecutive RAW frames. These
// ratio-space rates cap radius below one percent per publication (below two
// percent reconstructed circular area) while still allowing sustained
// light-response motion. A
// genuine faster transition remains visible as repeated current-RAW edge
// pressure and catches up over several frames instead of selecting a remote
// iris/lid arc in one frame.
const INNER_IRIS_MAX_CONTRACTION_PER_SECOND: f64 = 0.095;
const INNER_IRIS_MAX_EXPANSION_PER_SECOND: f64 = 0.095;
const RADIUS_RATE_LIMITER_MAX_PUBLICATION_STEP: Duration = Duration::from_millis(100);
// A selected radial edge only supports the published pupil diameter when its
// current-frame RAW transition is strong and its independently selected
// area-equivalent radius agrees with the robust ring radius.  These gates are
// deliberately separate from the soft mass/temporal rewards used to rank an
// ambiguous ray.
const PUPIL_DIAMETER_MIN_RAW_TRANSITION: f64 = 0.22;
const PUPIL_DIAMETER_MIN_RADIUS_TOLERANCE_PX: f64 = 1.25;
const PUPIL_DIAMETER_MAX_RADIUS_TOLERANCE_PX: f64 = 2.50;
const PUPIL_DIAMETER_RADIUS_TOLERANCE_FRACTION: f64 = 0.07;
const PUPIL_DIAMETER_MIN_COHERENT_POINTS: usize = 10;
const PUPIL_DIAMETER_MIN_OPPOSED_POINTS: usize = 6;
const PUPIL_DIAMETER_MIN_CONTIGUOUS_ARC_POINTS: usize = 3;
const DEFAULT_PUPIL_RADIUS_LOWER_FRACTION: f64 = 0.08;
const DEFAULT_PUPIL_RADIUS_UPPER_FRACTION: f64 = 0.72;
const PUPIL_RADIUS_OPERATOR_STEP_FRACTION: f64 = 0.01;
const PUPIL_RADIUS_OPERATOR_MINIMUM_FRACTION: f64 = 0.02;
const PUPIL_RADIUS_OPERATOR_MAXIMUM_FRACTION: f64 = 0.92;
const PUPIL_RADIUS_OPERATOR_MINIMUM_GAP_FRACTION: f64 = 0.02;
const IRIS_RADIUS_OPERATOR_STEP_PX: f64 = 1.0;
const IRIS_RADIUS_OPERATOR_MINIMUM_PX: f64 = 4.0;
const IRIS_RADIUS_OPERATOR_MAXIMUM_PX: f64 = 4_000.0;
const IRIS_RADIUS_OPERATOR_MINIMUM_GAP_PX: f64 = 2.0;
const IRIS_RADIUS_COLD_START_HALF_WIDTH: f64 = 0.20;
// A static guide must exist before an eye is aligned well enough to produce a
// fitted limbus. This nominal radius is presentation-only and intentionally
// never enters the detector or temporal radius tracker.
const STATIC_IRIS_NOMINAL_ROI_SHORT_SIDE_FRACTION: f64 = 0.375;
const STATIC_IRIS_NOMINAL_HALF_WIDTH: f64 = 0.20;
const PUPIL_SIZE_RATIO_WINDOW: usize = 9;
const PUPIL_SIZE_TEMPORAL_MIN_OBSERVATIONS: usize = 3;
const PUPIL_SIZE_MIN_TEMPORAL_HALF_WIDTH: f64 = 0.05;
const PUPIL_SIZE_MAX_TEMPORAL_HALF_WIDTH: f64 = 0.35;
const PUPIL_SIZE_STALE_EXPANSION_PER_SECOND: f64 = 0.035;
// A complete provisional road may bridge the continuous search across a
// stale outer-pose reacquisition, but it must remain close to the robust
// published pupil/limbus ratio. Farther innovations are commonly an iris
// texture band or glint ring and restart continuity at the published center.
const DRIVING_PROVISIONAL_PUPIL_RATIO_MAX_FRACTIONAL_INNOVATION: f64 = 0.12;
const DRIVING_PUPIL_CENTER_REFINEMENT_MAX_RADIUS_FRACTION: f64 = 0.30;
const DRIVING_PUPIL_CENTER_REFINEMENT_MAX_PX: f64 = 10.0;
// The pupil and limbus are circles in the same iris plane.  Even with corneal
// refraction and fit uncertainty, an 8%-of-limbus-radius annulus is a generous
// minimum; thinner rings in reviewed RAW frames were iris texture, lids, or a
// reflection moat rather than a physically positioned pupil.
const DRIVING_PUPIL_MAX_AFFINE_CONTAINMENT_RADIUS: f64 = 0.92;
const DRIVING_PUPIL_ORBITAL_MIN_SCORE: f64 = 0.30;
const DRIVING_PUPIL_ORBITAL_MIN_RING_COVERAGE: f64 = 0.25;
const DRIVING_PUPIL_ORBITAL_MIN_OPPOSING_SUPPORT: f64 = 0.25;
// Apparent fronto-parallel limbus scale is quantized at quarter octaves. This
// is fine enough to keep fixed-pixel pupil cues in one spatial regime while
// avoiding bucket churn from subpixel ellipse jitter.
const PUPIL_EVIDENCE_SCALE_BUCKETS: usize = 16;
const PUPIL_EVIDENCE_SCALE_BASE_RADIUS_PX: f64 = 24.0;
const PUPIL_EVIDENCE_SCALE_BUCKETS_PER_OCTAVE: f64 = 4.0;
const PUPIL_EVIDENCE_MIN_FOCUS_SUPPORT: usize = 6;
const PUPIL_EVIDENCE_MIN_TRAINING_FOCUS_RATIO: f64 = 0.55;
// A relative reference cannot prove that its first observation was sharp.
// Keep a deliberately low absolute floor so a cold start on obvious defocus
// may guide/display a pupil but cannot teach the physical size posterior.
const PUPIL_EVIDENCE_MIN_TRAINING_ABSOLUTE_SHARPNESS: f64 = 0.055;
// The native log/color plane has four-sensor-pixel spacing. A projected pupil
// radius below ten pixels supplies fewer than five samples across its diameter
// and must not teach a size posterior even when an ellipse can be displayed.
const PUPIL_EVIDENCE_MIN_TRAINING_PROJECTED_RADIUS_PX: f64 = 10.0;
// A pupil center outside this normalized affine-limbus radius is not eligible
// for publication or physiological size state. The bound is deliberately
// wider than ordinary pupil/limbus decentration so a rough acquisition center
// still has room to establish a real nested boundary.
const PUPIL_CENTER_MAX_NORMALIZED_LIMBUS_OFFSET: f64 = 0.62;
// A projected pupil is a nested conic, not merely a center point inside the
// limbus. Preserve a six-percent anatomical margin so fit uncertainty cannot
// turn an apparent near-tangent pupil into an iris-overlapping publication.
const PUPIL_BOUNDARY_MAX_NORMALIZED_LIMBUS_EXTENT: f64 = 0.94;
const MIN_RAW_ROI_SETS_PER_SECOND: usize = 10;
const NOMINAL_FINE_FRAME_LENGTH_LINES: u16 = 700;
const MIN_LONG_EXPOSURE_SETS_PER_SECOND: usize = 2;
const MANUAL_EXPOSURE_MAX_LINES: u16 = 8_192;

// Camera ROI ids are ordered in the image: id 1/index 0 is image-left, which
// is the subject's anatomical right eye; id 2/index 1 is subject-left.
fn subject_eye_label(index: usize) -> &'static str {
    if index == 0 {
        "subject-right"
    } else {
        "subject-left"
    }
}

fn subject_eye_analysis_enabled(index: usize) -> bool {
    index == 0
}

fn has_eye_border_structure(score: f64, point_count: usize) -> bool {
    score.is_finite() && score > 0.0 && point_count >= MIN_EYE_BORDER_POINTS
}

/// Weak texture is not anatomical proof, but several independently coherent
/// native-RAW motion layers are sufficient evidence that the fine crop is
/// still tracking the same local scene.  This gate may postpone an expensive
/// full-sensor reacquisition; it must never publish an eye or train pupil/
/// limbus geometry.
fn temporal_feature_roi_hold(
    segmentation: SegmentationMode,
    overlay: &raw_motion_octrees::MotionOctreeOverlay,
) -> bool {
    if segmentation != SegmentationMode::Clusters {
        return false;
    }
    let iris_anchored_two_layer = overlay.semantic_iris.is_some()
        && raw_motion_octrees::coherent_temporal_feature_hold(overlay);
    let acquisition_anchored_single_layer = overlay.matched_features >= 24
        && overlay
            .layers
            .iter()
            .map(|layer| layer.persistent_tracks)
            .sum::<usize>()
            >= 8
        && overlay
            .motions
            .iter()
            .zip(overlay.layers.iter())
            .any(|(motion, layer)| {
                motion.support >= 3
                    && motion.residual.is_finite()
                    && motion.residual <= 3.5
                    && layer.persistent_tracks >= 3
                    && layer.stable_frames >= 6
                    && layer.signature_samples >= 6
                    && layer.coherence.is_finite()
                    && layer.coherence >= 0.18
                    && layer.trajectory_error.is_finite()
                    && layer.trajectory_error <= 3.5
            });
    iris_anchored_two_layer || acquisition_anchored_single_layer
}

/// Retention-only authority carried from a completed eye frame to the context
/// packet which precedes the next one. It cannot cold-acquire identity, move a
/// sensor ROI, publish a conic, or train physical size. The fixed grace is
/// renewed only by a current coherent Canny observation belonging to the
/// already-acquired local scene.
#[derive(Clone, Copy, Debug, Default)]
struct TemporalFeaturePresenceHandoff {
    last_strong_at: Option<Instant>,
}

impl TemporalFeaturePresenceHandoff {
    fn observe(
        &mut self,
        now: Instant,
        segmentation: SegmentationMode,
        previously_acquired_eye: bool,
        overlay: &raw_motion_octrees::MotionOctreeOverlay,
    ) -> bool {
        if segmentation != SegmentationMode::Clusters || !previously_acquired_eye {
            self.clear();
            return false;
        }
        if temporal_feature_roi_hold(segmentation, overlay) {
            self.last_strong_at = Some(now);
        }
        self.active(now, segmentation, previously_acquired_eye)
    }

    fn active(
        self,
        now: Instant,
        segmentation: SegmentationMode,
        previously_acquired_eye: bool,
    ) -> bool {
        segmentation == SegmentationMode::Clusters
            && previously_acquired_eye
            && self.last_strong_at.is_some_and(|strong| {
                now.saturating_duration_since(strong) <= TEMPORAL_FEATURE_PRESENCE_HANDOFF_GRACE
            })
    }

    fn clear(&mut self) {
        self.last_strong_at = None;
    }
}

/// Whether the independent native fit is strong enough to spend one
/// bounded Driving worker lap. This is deliberately not an anatomy verdict;
/// the worker's full rectified eye-road gate owns cold-start identity, while
/// the Bayer material map remains observable diagnostic evidence.
fn driving_full_topology_probe_ready(
    native_boundary_ready: bool,
    native_fit_accepted: bool,
) -> bool {
    native_boundary_ready && native_fit_accepted
}

fn autofocus_roi_ready(manual_roi_hold: bool, focus_bootstrap: bool, tracker_ready: bool) -> bool {
    manual_roi_hold || focus_bootstrap || tracker_ready
}

fn provisional_autofocus_allowed(focus_bootstrap: bool, now: Instant, retry_at: Instant) -> bool {
    focus_bootstrap && now >= retry_at
}

fn session_autofocus_armed(policy_enabled: bool, manual_focus: bool) -> bool {
    policy_enabled && !manual_focus
}

fn high_confidence_in_focus_pupil_center(
    selected_eye: bool,
    focus_settled: bool,
    identity_present: bool,
    eye_basin_valid: bool,
    focus_score: f64,
    focus_points: usize,
    focus_center: Option<(f64, f64)>,
) -> bool {
    selected_eye
        && focus_settled
        && identity_present
        && eye_basin_valid
        && focus_center.is_some()
        && has_eye_border_structure(focus_score, focus_points)
}

fn pupil_health_identity_present(
    published_identity_present: bool,
    display_only_reacquisition: bool,
    fine_eye_identity_present: bool,
) -> bool {
    published_identity_present || (display_only_reacquisition && fine_eye_identity_present)
}

fn session_focus_health_ready(
    initial_focus_completed: bool,
    manual_roi_hold: bool,
    now: Instant,
    grace_until: Instant,
) -> bool {
    initial_focus_completed && !manual_roi_hold && now >= grace_until
}

#[derive(Debug, Default)]
struct PupilCenterHealth {
    armed_at: Option<Instant>,
    last_confirmed: Option<Instant>,
}

impl PupilCenterHealth {
    fn observe(
        &mut self,
        now: Instant,
        one_time_calibrations_complete: bool,
        high_confidence_center: bool,
    ) -> Result<(), Duration> {
        if !one_time_calibrations_complete && self.armed_at.is_none() {
            return Ok(());
        }
        let armed_at = *self.armed_at.get_or_insert(now);
        if high_confidence_center {
            self.last_confirmed = Some(now);
            return Ok(());
        }
        let last_healthy = self.last_confirmed.unwrap_or(armed_at);
        let elapsed = now.saturating_duration_since(last_healthy);
        if elapsed > PUPIL_CENTER_HEALTH_TIMEOUT {
            Err(elapsed)
        } else {
            Ok(())
        }
    }

    fn armed(&self) -> bool {
        self.armed_at.is_some()
    }

    fn defer_until_tracking(&mut self, now: Instant) {
        if self.armed_at.is_some() {
            // Full-sensor semantic reacquisition and VCM motion temporarily
            // make a fine-ROI pupil center unobservable. Start a fresh bounded
            // tracking deadline instead of letting that intentional camera
            // ownership transition consume the existing one. Do not preserve
            // `last_confirmed`: recovery must still earn new pupil evidence.
            self.armed_at = Some(now);
            self.last_confirmed = None;
        }
    }

    fn confirmed_within(&self, now: Instant, maximum_age: Duration) -> bool {
        self.last_confirmed
            .is_some_and(|confirmed| now.saturating_duration_since(confirmed) <= maximum_age)
    }
}

fn use_local_autofocus_probe(initial_focus_completed: bool, manual_roi_hold: bool) -> bool {
    initial_focus_completed || manual_roi_hold
}

fn current_focus_satisfies_session_acquisition(
    initial_focus_completed: bool,
    focus_eye_auto: bool,
    candidate_eye: usize,
    selected_eye: usize,
    high_confidence_center: bool,
) -> bool {
    !initial_focus_completed
        && high_confidence_center
        && (candidate_eye == selected_eye || focus_eye_auto)
}

fn context_failure_limit(focus_blur_tolerance: bool, fine_eye_lost: bool) -> u32 {
    if fine_eye_lost {
        CONTEXT_FINE_EYE_LOST_FRAMES
    } else if focus_blur_tolerance {
        CONTEXT_FOCUS_FAILURE_FRAMES
    } else {
        CONTEXT_FAILURE_FRAMES
    }
}

fn context_geometry_failure_limit(focus_blur_tolerance: bool) -> u32 {
    if focus_blur_tolerance {
        CONTEXT_FOCUS_GEOMETRY_FAILURE_FRAMES
    } else {
        CONTEXT_GEOMETRY_FAILURE_FRAMES
    }
}

fn mediapipe_retry_delay(failures: u32) -> Duration {
    match failures {
        0 | 1 => Duration::from_millis(100),
        2 => Duration::from_millis(250),
        3 => Duration::from_millis(500),
        4 => Duration::from_secs(1),
        5 => Duration::from_secs(2),
        6 => Duration::from_secs(4),
        _ => Duration::from_secs(8),
    }
}

fn mediapipe_lost_anatomy_retry_delay(failures: u32) -> Duration {
    let sustained_absence_backoff = match failures {
        0 | 1 => Duration::from_secs(2),
        2 => Duration::from_secs(4),
        3 => Duration::from_secs(8),
        4 => Duration::from_secs(16),
        _ => Duration::from_secs(30),
    };
    sustained_absence_backoff.max(mediapipe_retry_delay(failures))
}

#[allow(clippy::too_many_arguments)]
fn sustained_no_anatomy_reacquire_due(
    mediapipe_enabled: bool,
    manual_roi_hold: bool,
    checkerboard_active: bool,
    automation_allowed: bool,
    mediapipe_task_active: bool,
    autofocus_active: bool,
    autofocus_bootstrap_pending: bool,
    recent_healthy_pupil: bool,
    missing_since: Option<Instant>,
    now: Instant,
    retry_at: Instant,
) -> bool {
    mediapipe_enabled
        && !manual_roi_hold
        && !checkerboard_active
        && automation_allowed
        && !mediapipe_task_active
        && !autofocus_active
        && !autofocus_bootstrap_pending
        && !recent_healthy_pupil
        && now >= retry_at
        && missing_since
            .is_some_and(|since| now.saturating_duration_since(since) >= NO_ANATOMY_REACQUIRE_AFTER)
}

/// A lower-authority local tracker may defer coarse reacquisition only while
/// the continuously missing primary geometry remains inside its wall-clock
/// lease. `None` deliberately means there is no active loss interval to hand
/// off; acquisition and verified anatomy reset that interval themselves.
fn local_eye_presence_lease_active(
    handoff_active: bool,
    primary_geometry_missing_since: Option<Instant>,
    now: Instant,
) -> bool {
    handoff_active
        && primary_geometry_missing_since.is_some_and(|since| {
            now.saturating_duration_since(since) < INVALID_EYE_GEOMETRY_PRESENCE_LEASE
        })
}

fn mediapipe_success_retry_delay(task_kind: MediaPipeTaskKind) -> Duration {
    match task_kind {
        MediaPipeTaskKind::Periodic => Duration::ZERO,
        MediaPipeTaskKind::LostLock => MEDIAPIPE_FINE_SETTLE_AFTER_RELOCATION,
        MediaPipeTaskKind::LinearSnapshot => Duration::ZERO,
    }
}

fn camera_automation_self_interrupt(
    mediapipe_failures: u32,
    now: Instant,
    retry_at: Instant,
) -> bool {
    mediapipe_failures == 0 && now < retry_at
}

#[derive(Debug)]
struct CameraAutomationWait {
    started_at: Instant,
    release_at: Instant,
    requests: u32,
    last_reason: String,
}

#[derive(Debug, PartialEq, Eq)]
enum CameraAutomationWaitPoll {
    Idle,
    Waiting,
    Reacquire(String),
}

fn queue_camera_automation_wait(
    wait: &mut Option<CameraAutomationWait>,
    now: Instant,
    release_at: Instant,
    reason: &str,
) -> bool {
    let active = wait.get_or_insert_with(|| CameraAutomationWait {
        started_at: now,
        release_at,
        requests: 0,
        last_reason: reason.to_string(),
    });
    let first_request = active.requests == 0;
    active.requests = active.requests.saturating_add(1);
    active.last_reason.clear();
    active.last_reason.push_str(reason);
    first_request
}

fn poll_camera_automation_wait(
    wait: &mut Option<CameraAutomationWait>,
    now: Instant,
) -> CameraAutomationWaitPoll {
    let Some(active) = wait.as_ref() else {
        return CameraAutomationWaitPoll::Idle;
    };
    if now >= active.release_at {
        let active = wait.take().expect("camera automation wait disappeared");
        eprintln!(
            "camera automation handoff after {}ms and {} waiting request(s): post-relocation fine validation reached its deadline",
            now.saturating_duration_since(active.started_at).as_millis(),
            active.requests,
        );
        return CameraAutomationWaitPoll::Reacquire(active.last_reason);
    }
    CameraAutomationWaitPoll::Waiting
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum SegmentationMode {
    #[default]
    Native,
    Sam31,
    Clusters,
    Driving,
    /// Track red-opponent line structure on bright sclera without fitting or
    /// publishing an iris, pupil, globe, or gaze ray.
    ScleraRedCanny,
}

/// How much full-sensor MediaPipe activity an iris segmenter can tolerate
/// while it owns the fine RAW sensor ROI.  The ordering is intentional: a
/// rough-center mechanism is compatible when its requirement is no greater
/// than the selected segmenter's allowance.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord)]
enum MediaPipeCadence {
    /// Reserved for segmenters which cannot surrender their fine ROI at all.
    None,
    /// One global semantic acquisition is allowed; periodic refreshes are not.
    #[default]
    GlobalAcquireOnly,
    /// Periodic full-sensor semantic refreshes are safe.
    Continuous,
}

impl MediaPipeCadence {
    fn allowance_label(self) -> &'static str {
        match self {
            Self::None => "prohibited",
            Self::GlobalAcquireOnly => "global-acquire-only",
            Self::Continuous => "continuous",
        }
    }

    fn requirement_label(self) -> &'static str {
        match self {
            Self::None => "not-required",
            Self::GlobalAcquireOnly => "global-acquire-only",
            Self::Continuous => "continuous",
        }
    }
}

/// The rough pupil-center source is deliberately independent of outer-iris
/// segmentation.  A selected source may still declare an explicit dependency
/// on MediaPipe cadence or on one particular outer segmenter.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum RoughPupilCenterMode {
    /// Preserve the former default: bound the native dark-void search with the
    /// selected outer ellipse and begin at that ellipse's center.
    #[default]
    IrisGuided,
    /// Seed the native dark-void search from the full-resolution RAW focus
    /// anatomy estimate, independently of the selected outer ellipse center.
    RawFocus,
    /// Use the fixed-prompt SAM pupil-void result as a rough center. Only its
    /// independently inferred center seeds the common native RAW
    /// pupil-margin solver; SAM's downsampled ellipse is never the published
    /// pupil boundary.
    Sam31,
    /// Use the center of the globally acquired MediaPipe eye ROI, then refine
    /// it against untouched full-resolution RAW pixels.  No periodic scan is
    /// requested after that acquisition.
    MediaPipeAcquire,
    /// Refresh the MediaPipe eye ROI periodically and RAW-refine its center.
    MediaPipeContinuous,
    /// Use the pupil recovered by the complete Driving topology as the seed
    /// for the native full-resolution inner-boundary refinement.
    DrivingTopology,
}

impl RoughPupilCenterMode {
    const COUNT: usize = 6;

    fn parse(value: &str) -> Option<Self> {
        match value.to_ascii_lowercase().replace(['_', '-'], "").as_str() {
            "iris" | "irisguided" | "outer" | "outercenter" | "default" => Some(Self::IrisGuided),
            "raw" | "rawfocus" | "native" | "nativefocus" => Some(Self::RawFocus),
            "sam" | "sam31" | "sam31center" | "samcenter" | "sam31pupil" | "pupilvoid" => {
                Some(Self::Sam31)
            }
            "mediapipe" | "mediapipeonce" | "mediapipeacquire" | "mp" | "mponce" => {
                Some(Self::MediaPipeAcquire)
            }
            "mediapipecontinuous" | "mediapipelive" | "mpcontinuous" | "mplive" => {
                Some(Self::MediaPipeContinuous)
            }
            "driving" | "drivingtopology" | "drive" => Some(Self::DrivingTopology),
            _ => None,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::IrisGuided => "iris-guided",
            Self::RawFocus => "raw-focus",
            Self::Sam31 => "sam31-center",
            Self::MediaPipeAcquire => "mediapipe-acquire",
            Self::MediaPipeContinuous => "mediapipe-continuous",
            Self::DrivingTopology => "driving-topology",
        }
    }

    fn short_label(self) -> &'static str {
        match self {
            Self::IrisGuided => "IRIS",
            Self::RawFocus => "RAW",
            Self::Sam31 => "SAM-CENTER",
            Self::MediaPipeAcquire => "MP-ONCE",
            Self::MediaPipeContinuous => "MP-LIVE",
            Self::DrivingTopology => "DRIVE-PUPIL",
        }
    }

    fn cycled(self) -> Self {
        match self {
            Self::IrisGuided => Self::RawFocus,
            Self::RawFocus => Self::Sam31,
            Self::Sam31 => Self::MediaPipeAcquire,
            Self::MediaPipeAcquire => Self::MediaPipeContinuous,
            Self::MediaPipeContinuous => Self::DrivingTopology,
            Self::DrivingTopology => Self::IrisGuided,
        }
    }

    fn mediapipe_requirement(self) -> MediaPipeCadence {
        match self {
            Self::MediaPipeAcquire => MediaPipeCadence::GlobalAcquireOnly,
            Self::MediaPipeContinuous => MediaPipeCadence::Continuous,
            Self::IrisGuided | Self::RawFocus | Self::Sam31 | Self::DrivingTopology => {
                MediaPipeCadence::None
            }
        }
    }

    fn requires_segmentation(self) -> Option<SegmentationMode> {
        match self {
            Self::DrivingTopology => Some(SegmentationMode::Driving),
            _ => None,
        }
    }

    fn compatibility(self, segmentation: SegmentationMode) -> Result<(), &'static str> {
        // Sclera Red-Canny does not consume a rough pupil center. Preserve the
        // selected Y mode for a later iris mode, but never let that dormant
        // dependency make the scleral tracker unreachable from G.
        if segmentation == SegmentationMode::ScleraRedCanny {
            return Ok(());
        }
        if self
            .requires_segmentation()
            .is_some_and(|required| required != segmentation)
        {
            return Err("driving-topology rough center requires Driving iris segmentation");
        }
        if self.mediapipe_requirement() > segmentation.mediapipe_allowance() {
            return Err(
                "rough-center MediaPipe cadence exceeds the iris segmenter's ROI allowance",
            );
        }
        Ok(())
    }

    fn cycled_compatible(self, segmentation: SegmentationMode) -> Self {
        let mut candidate = self;
        for _ in 0..Self::COUNT {
            candidate = candidate.cycled();
            if candidate.compatibility(segmentation).is_ok() {
                return candidate;
            }
        }
        self
    }
}

/// Alternative evidence policies within the full-resolution Driving search.
/// Both policies run the same pupil-headed affine perimeter drive; they differ
/// only in how the directly measured double-sclera rows rank and admit roads.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum DrivingSubmode {
    #[default]
    Normal,
    DoubleSclera10Deg,
}

impl DrivingSubmode {
    fn parse(value: &str) -> Option<Self> {
        match value
            .to_ascii_lowercase()
            .replace(['_', '-', '\u{b0}'], "")
            .as_str()
        {
            "normal" | "default" | "full" => Some(Self::Normal),
            "doublesclera10" | "doublesclera10deg" | "best10" | "best10deg" | "ds10" => {
                Some(Self::DoubleSclera10Deg)
            }
            _ => None,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Normal => "normal",
            Self::DoubleSclera10Deg => "double-sclera-10deg",
        }
    }

    fn short_label(self) -> &'static str {
        match self {
            Self::Normal => "NORMAL",
            Self::DoubleSclera10Deg => "DS10",
        }
    }

    fn cycled(self) -> Self {
        match self {
            Self::Normal => Self::DoubleSclera10Deg,
            Self::DoubleSclera10Deg => Self::Normal,
        }
    }

    fn select_through_eye_score(self, broad: f64, double_sclera_10_deg: f64) -> f64 {
        match self {
            Self::Normal => broad,
            Self::DoubleSclera10Deg => double_sclera_10_deg,
        }
    }

    fn select_total_score(self, normal: f64, double_sclera_10_deg: f64) -> f64 {
        match self {
            Self::Normal => normal,
            // Give the selected ten-degree road enough authority to reorder
            // close candidates without allowing it to replace the remaining
            // sclera, limbus, pupil, and illumination anatomy gates.
            Self::DoubleSclera10Deg => 0.82 * normal + 0.18 * double_sclera_10_deg,
        }
    }
}

thread_local! {
    /// A Driving worker handles one work item synchronously on one dedicated
    /// thread. Carrying the item's immutable submode in thread-local scoring
    /// context keeps every nested rescue/fly-by on the same policy without a
    /// process-global switch or a copy of the full-resolution RAW allocation.
    static DRIVING_SCORING_SUBMODE: std::cell::Cell<DrivingSubmode> =
        const { std::cell::Cell::new(DrivingSubmode::Normal) };
}

fn driving_scoring_submode() -> DrivingSubmode {
    DRIVING_SCORING_SUBMODE.with(std::cell::Cell::get)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SegmentationMotionWork {
    None,
    TemporalClusters,
    BoundedIris,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SegmentationEyelidOverlay {
    None,
    NativeMargins,
    DrivingScene,
}

/// The selected segmentation submode is the authority for both expensive
/// mode-specific work and the diagnostic layers painted over the lossless
/// ROI. Acquisition, identity, and autofocus remain common. A mode may
/// explicitly withhold pupil/limbus publication, as Sclera Red-Canny does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SegmentationModeProfile {
    motion_work: SegmentationMotionWork,
    show_native_diagnostics: bool,
    show_censored_limbus: bool,
    show_driving_diagnostics: bool,
    show_sclera_red_canny: bool,
    show_rotation_meridians: bool,
    eyelid_overlay: SegmentationEyelidOverlay,
}

impl SegmentationModeProfile {
    fn show_motion_overlay(self) -> bool {
        self.motion_work != SegmentationMotionWork::None
    }
}

impl SegmentationMode {
    const COUNT: usize = 5;

    fn parse(value: &str) -> Option<Self> {
        match value.to_ascii_lowercase().replace(['_', '-'], "").as_str() {
            "native" => Some(Self::Native),
            "sam31" | "sam3.1" | "sam" => Some(Self::Sam31),
            // Legacy spelling remains an outer-SAM alias. Config/control
            // parsing also selects the independent SAM pupil-center mode.
            "sam31pupil" | "sam3.1pupil" | "sampupil" | "pupilvoid" => Some(Self::Sam31),
            "clusters" | "cluster" | "features" | "grain" | "irisgrain" => Some(Self::Clusters),
            "driving" | "drive" | "steering" | "affine3d" => Some(Self::Driving),
            "sclera" | "sclerared" | "scleraredcanny" | "redcanny" | "vessels"
            | "scleravessels" => Some(Self::ScleraRedCanny),
            _ => None,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Native => "native",
            Self::Sam31 => "sam31",
            Self::Clusters => "clusters",
            Self::Driving => "driving",
            Self::ScleraRedCanny => "sclera-red-canny",
        }
    }

    fn mediapipe_allowance(self) -> MediaPipeCadence {
        match self {
            // Native has no temporal model state to invalidate and can accept
            // recurrent semantic refreshes.
            Self::Native => MediaPipeCadence::Continuous,
            // These modes own multi-frame RAW evidence or fine sensor-ROI
            // steering. They may consume one global acquisition, then retain
            // uninterrupted fine control until the lock is explicitly lost.
            Self::Sam31 | Self::Clusters | Self::Driving | Self::ScleraRedCanny => {
                MediaPipeCadence::GlobalAcquireOnly
            }
        }
    }

    fn cycled(self) -> Self {
        match self {
            Self::Native => Self::Sam31,
            Self::Sam31 => Self::Clusters,
            Self::Clusters => Self::Driving,
            Self::Driving => Self::ScleraRedCanny,
            Self::ScleraRedCanny => Self::Native,
        }
    }

    fn cycled_compatible(self, rough_center: RoughPupilCenterMode) -> Self {
        let mut candidate = self;
        for _ in 0..Self::COUNT {
            candidate = candidate.cycled();
            if rough_center.compatibility(candidate).is_ok() {
                return candidate;
            }
        }
        self
    }

    fn profile(self) -> SegmentationModeProfile {
        match self {
            Self::Native => SegmentationModeProfile {
                motion_work: SegmentationMotionWork::None,
                show_native_diagnostics: true,
                show_censored_limbus: true,
                show_driving_diagnostics: false,
                show_sclera_red_canny: false,
                show_rotation_meridians: true,
                eyelid_overlay: SegmentationEyelidOverlay::NativeMargins,
            },
            Self::Sam31 => SegmentationModeProfile {
                motion_work: SegmentationMotionWork::None,
                show_native_diagnostics: false,
                show_censored_limbus: false,
                show_driving_diagnostics: false,
                show_sclera_red_canny: false,
                show_rotation_meridians: false,
                eyelid_overlay: SegmentationEyelidOverlay::None,
            },
            Self::Clusters => SegmentationModeProfile {
                motion_work: SegmentationMotionWork::TemporalClusters,
                show_native_diagnostics: false,
                show_censored_limbus: false,
                show_driving_diagnostics: false,
                show_sclera_red_canny: false,
                // Clusters owns the temporal pivot estimate. Keep its
                // presentation-only virtual contact visible while the
                // current anatomy gate is temporarily weak.
                show_rotation_meridians: true,
                eyelid_overlay: SegmentationEyelidOverlay::None,
            },
            Self::Driving => SegmentationModeProfile {
                motion_work: SegmentationMotionWork::BoundedIris,
                show_native_diagnostics: false,
                show_censored_limbus: true,
                show_driving_diagnostics: true,
                show_sclera_red_canny: false,
                // The projected meridian/longitude globe is presentation-only:
                // it consumes Driving's admitted sphere geometry without
                // enabling Native segmentation work or deforming the RAW ROI.
                show_rotation_meridians: true,
                eyelid_overlay: SegmentationEyelidOverlay::DrivingScene,
            },
            Self::ScleraRedCanny => SegmentationModeProfile {
                motion_work: SegmentationMotionWork::None,
                show_native_diagnostics: false,
                show_censored_limbus: false,
                show_driving_diagnostics: false,
                show_sclera_red_canny: true,
                show_rotation_meridians: false,
                eyelid_overlay: SegmentationEyelidOverlay::None,
            },
        }
    }
}

fn sam31_target_for_modes(
    segmentation: SegmentationMode,
    rough_center: RoughPupilCenterMode,
) -> Option<sam31_outer::Target> {
    // This mode intentionally owns no iris or pupil product. The Y selection
    // is retained for whichever G mode the operator selects next, but it must
    // not wake the SAM worker while red scleral vessels are being tracked.
    if segmentation == SegmentationMode::ScleraRedCanny {
        return None;
    }
    match (
        segmentation == SegmentationMode::Sam31,
        rough_center == RoughPupilCenterMode::Sam31,
    ) {
        // One fixed-graph pass produces the outer fit and then attempts the
        // independent pupil-center post-process. A failed center must never
        // suppress or replace the outer detector selected by G.
        (true, true) => Some(sam31_outer::Target::OuterLimbusAndInnerPupilVoid),
        (true, false) => Some(sam31_outer::Target::OuterLimbus),
        (false, true) => Some(sam31_outer::Target::InnerPupilVoid),
        (false, false) => None,
    }
}

