enum MediaPipeTaskKind {
    Periodic,
    LostLock,
    LinearSnapshot,
}

/// Immutable authorization captured when a semantic camera task starts. The
/// generation is intentionally absent for an explicit lossless linear
/// snapshot, which is not governed by the eye-reacquisition `R` switch.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct MediaPipeTaskAuthorization {
    reacquisition_generation: Option<u64>,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum CameraAutomationOwner {
    #[default]
    Tracking,
    AutofocusBootstrap,
    AutofocusSweep,
    SemanticReacquisition,
}

impl CameraAutomationOwner {
    fn label(self) -> &'static str {
        match self {
            Self::Tracking => "steady-tracking",
            Self::AutofocusBootstrap => "autofocus-bootstrap",
            Self::AutofocusSweep => "autofocus-sweep",
            Self::SemanticReacquisition => "semantic-reacquisition",
        }
    }
}

fn autofocus_bootstrap_pending(
    coarse_focus_authorized: bool,
    now: Instant,
    coarse_focus_deadline: Instant,
) -> bool {
    coarse_focus_authorized && now <= coarse_focus_deadline
}

fn fast_local_focus_bootstrap_pending(
    initial_focus_completed: bool,
    manual_focus: bool,
    autofocus_armed: bool,
    autofocus_active: bool,
    recent_healthy_pupil: bool,
    now: Instant,
    autofocus_retry: Instant,
) -> bool {
    initial_focus_completed
        && !manual_focus
        && autofocus_armed
        && !autofocus_active
        && recent_healthy_pupil
        && autofocus_retry.saturating_duration_since(now) <= FAST_LOCAL_FOCUS_BOOTSTRAP_LEAD
}

fn select_camera_automation_owner(
    semantic_reacquisition_active: bool,
    autofocus_active: bool,
    autofocus_bootstrap_pending: bool,
) -> CameraAutomationOwner {
    if semantic_reacquisition_active {
        CameraAutomationOwner::SemanticReacquisition
    } else if autofocus_active {
        CameraAutomationOwner::AutofocusSweep
    } else if autofocus_bootstrap_pending {
        CameraAutomationOwner::AutofocusBootstrap
    } else {
        CameraAutomationOwner::Tracking
    }
}

fn mediapipe_requires_relocation(current: &Config, observed: &Config) -> bool {
    current.eyes.iter().zip(observed.eyes.iter()).any(
        |(&(current_x, current_y), &(observed_x, observed_y))| {
            let predicted_center = (
                observed_x as i64 + observed.eye_size.0 as i64 / 2,
                observed_y as i64 + observed.eye_size.1 as i64 / 2,
            );
            predicted_center.0 < current_x as i64 + CONTEXT_ROI_CONTAINMENT_MARGIN.0 as i64
                || predicted_center.0
                    >= current_x as i64 + current.eye_size.0 as i64
                        - CONTEXT_ROI_CONTAINMENT_MARGIN.0 as i64
                || predicted_center.1 < current_y as i64 + CONTEXT_ROI_CONTAINMENT_MARGIN.1 as i64
                || predicted_center.1
                    >= current_y as i64 + current.eye_size.1 as i64
                        - CONTEXT_ROI_CONTAINMENT_MARGIN.1 as i64
        },
    )
}

fn mediapipe_should_apply_fine_rois(
    task_kind: MediaPipeTaskKind,
    current: &Config,
    observed: &Config,
) -> bool {
    task_kind == MediaPipeTaskKind::LostLock || mediapipe_requires_relocation(current, observed)
}

fn coarse_semantic_limbus_scale_prediction(
    previous_eyes: [(u32, u32); 2],
    observed_eyes: [(u32, u32); 2],
) -> Option<raw_iris_focus::FrontoParallelLimbusScalePrediction> {
    let span = |eyes: [(u32, u32); 2]| {
        (f64::from(eyes[0].0) - f64::from(eyes[1].0))
            .hypot(f64::from(eyes[0].1) - f64::from(eyes[1].1))
    };
    let previous_span = span(previous_eyes);
    let observed_span = span(observed_eyes);
    if !previous_span.is_finite()
        || !observed_span.is_finite()
        || previous_span < 32.0
        || observed_span < 32.0
    {
        return None;
    }
    let scale_ratio = observed_span / previous_span;
    if !(0.40..=2.50).contains(&scale_ratio) {
        return None;
    }
    // Interocular image span is a useful distance-scale cue, but head yaw can
    // foreshorten it. Keep a deliberately broad support until native limbus
    // anatomy verifies the transported radius in the fine ROI.
    let uncertainty = (0.10 + 0.15 * scale_ratio.ln().abs()).clamp(0.10, 0.22);
    Some(
        raw_iris_focus::FrontoParallelLimbusScalePrediction::coarse_semantic_pose(
            scale_ratio,
            uncertainty,
        ),
    )
}

