#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ProvisionalFocusVerification {
    anchor_position: u16,
    candidate_position: u16,
    semantic_verified: bool,
}

fn provisional_focus_from_uncropped_receipt(
    text: &str,
    now_unix_ms: u128,
    current_position: u16,
) -> Result<Option<ProvisionalFocusVerification>, String> {
    let document = serde_json::from_str::<serde_json::Value>(text)
        .map_err(|error| format!("parse uncropped rough-focus receipt: {error}"))?;
    if document.get("schema").and_then(serde_json::Value::as_str)
        != Some("buttercup-uncropped-rough-focus-v1")
    {
        return Err("uncropped rough-focus receipt has an unknown schema".to_string());
    }
    let number = |field: &str| {
        document
            .get(field)
            .and_then(serde_json::Value::as_u64)
            .ok_or_else(|| format!("uncropped rough-focus receipt omitted {field}"))
    };
    let completed_unix_ms = number("completed_unix_ms")? as u128;
    let age_ms = now_unix_ms.saturating_sub(completed_unix_ms);
    let future_ms = completed_unix_ms.saturating_sub(now_unix_ms);
    if age_ms > UNCROPPED_ROUGH_FOCUS_RECEIPT_MAX_AGE.as_millis() || future_ms > 2_000 {
        return Ok(None);
    }
    let anchor_position = u16::try_from(number("initial_position")?)
        .map_err(|_| "uncropped rough-focus anchor does not fit the physical VCM".to_string())?;
    let candidate_position = u16::try_from(number("selected_position")?)
        .map_err(|_| "uncropped rough-focus candidate does not fit the physical VCM".to_string())?;
    if !(VCM_MIN_POSITION..=VCM_MAX_POSITION).contains(&anchor_position)
        || !(VCM_MIN_POSITION..=VCM_MAX_POSITION).contains(&candidate_position)
    {
        return Err("uncropped rough-focus receipt contains an unsafe VCM position".to_string());
    }
    if candidate_position != current_position || candidate_position == anchor_position {
        return Ok(None);
    }
    let bracketed = document
        .get("bracketed")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let gain = document
        .get("gain_over_initial")
        .and_then(serde_json::Value::as_f64)
        .unwrap_or(0.0);
    if !bracketed || !gain.is_finite() || gain < COARSE_FOCUS_MIN_FALLOFF {
        return Ok(None);
    }
    Ok(Some(ProvisionalFocusVerification {
        anchor_position,
        candidate_position,
        // The uncropped focus transaction verified the selected DAC on a
        // second full-sensor exposure. Native fine-eye anatomy is still
        // required before the rollback anchor is released.
        semantic_verified: true,
    }))
}

fn load_uncropped_focus_verification(
    address: &str,
) -> Result<Option<ProvisionalFocusVerification>, String> {
    let text = match fs::read_to_string(UNCROPPED_ROUGH_FOCUS_RECEIPT) {
        Ok(text) => text,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("read uncropped rough-focus receipt: {error}")),
    };
    let response = vcm_command(address, "FOCUS GET")?;
    let current_position = response
        .split_whitespace()
        .nth(1)
        .ok_or_else(|| format!("invalid VCM response while loading rough focus: {response}"))?
        .parse::<u16>()
        .map_err(|error| format!("invalid VCM position in {response}: {error}"))?;
    let now_unix_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis();
    provisional_focus_from_uncropped_receipt(&text, now_unix_ms, current_position)
}

fn rollback_unverified_provisional_focus(
    address: &str,
    verification: &mut Option<ProvisionalFocusVerification>,
    shared: &Arc<Mutex<SharedState>>,
) -> Result<Option<ProvisionalFocusVerification>, String> {
    let Some(verification) = verification.take() else {
        return Ok(None);
    };
    let response = vcm_command(
        address,
        &format!("FOCUS SET {}", verification.anchor_position),
    )?;
    if let Ok(mut state) = shared.lock() {
        state.focus_target = Some(verification.anchor_position);
        state.focus_position = Some(verification.anchor_position);
        state.focus_settled = Some(false);
        state.eye_identity_present = [false; 2];
    }
    let _ = fs::remove_file(UNCROPPED_ROUGH_FOCUS_RECEIPT);
    eprintln!(
        "RAW provisional focus candidate={} {}; restored proven anchor={}: {response}",
        verification.candidate_position,
        if verification.semantic_verified {
            "lost semantic/fine-eye validation before strict acceptance"
        } else {
            "failed its first fresh semantic eye-pair verification"
        },
        verification.anchor_position,
    );
    Ok(Some(verification))
}

#[derive(Debug, Default)]
struct FocusMotionGate {
    history: VecDeque<f64>,
    consecutive_still: u32,
}

#[derive(Debug, Clone, Copy)]
struct FocusMotionObservation {
    ready: bool,
    threshold: f64,
}

#[derive(Debug, Default)]
struct FocusTargetDebounce {
    roi_origin: Option<(u32, u32)>,
    pending: VecDeque<(f64, f64)>,
    accepted: Option<(f64, f64)>,
}

impl FocusTargetDebounce {
    fn observe(
        &mut self,
        roi_origin: (u32, u32),
        candidate: Option<(f64, f64)>,
    ) -> Option<(f64, f64)> {
        if self.roi_origin != Some(roi_origin) {
            self.roi_origin = Some(roi_origin);
            self.pending.clear();
            self.accepted = None;
        }
        let Some(candidate) = candidate else {
            self.pending.clear();
            return None;
        };
        if self.accepted.is_some_and(|accepted| {
            (accepted.0 - candidate.0).hypot(accepted.1 - candidate.1)
                <= FOCUS_TARGET_DEBOUNCE_RADIUS
        }) {
            self.pending.clear();
            return self.accepted;
        }
        self.pending.push_back(candidate);
        while self.pending.len() > FOCUS_TARGET_DEBOUNCE_FRAMES {
            self.pending.pop_front();
        }
        if self.pending.len() == FOCUS_TARGET_DEBOUNCE_FRAMES {
            let mut xs = self.pending.iter().map(|point| point.0).collect::<Vec<_>>();
            let mut ys = self.pending.iter().map(|point| point.1).collect::<Vec<_>>();
            xs.sort_by(f64::total_cmp);
            ys.sort_by(f64::total_cmp);
            let median = (xs[xs.len() / 2], ys[ys.len() / 2]);
            let coherent = self.pending.iter().all(|point| {
                (point.0 - median.0).hypot(point.1 - median.1) <= FOCUS_TARGET_DEBOUNCE_RADIUS
            });
            if coherent {
                self.accepted = Some(median);
                self.pending.clear();
            }
        }
        self.accepted
    }
}

impl FocusMotionGate {
    fn reset(&mut self) {
        self.history.clear();
        self.consecutive_still = 0;
    }

    fn threshold(&self) -> f64 {
        if self.history.len() < AUTOFOCUS_STILL_FRAMES as usize {
            return AUTOFOCUS_MOTION_ABSOLUTE_CAP;
        }
        let mut sorted = self.history.iter().copied().collect::<Vec<_>>();
        sorted.sort_by(f64::total_cmp);
        let lower_quartile = sorted[sorted.len() / 4];
        (lower_quartile * 1.35 + 2.0).clamp(12.0, AUTOFOCUS_MOTION_ABSOLUTE_CAP)
    }

    fn observe(
        &mut self,
        motion_score: f64,
        comparable_to_previous: bool,
    ) -> FocusMotionObservation {
        if !comparable_to_previous || !motion_score.is_finite() {
            self.consecutive_still = 0;
            return FocusMotionObservation {
                ready: false,
                threshold: self.threshold(),
            };
        }

        let threshold = self.threshold();
        let still = motion_score <= threshold;
        self.history.push_back(motion_score);
        while self.history.len() > AUTOFOCUS_MOTION_HISTORY {
            self.history.pop_front();
        }
        self.consecutive_still = if still {
            self.consecutive_still.saturating_add(1)
        } else {
            0
        };
        FocusMotionObservation {
            ready: self.consecutive_still >= AUTOFOCUS_STILL_FRAMES,
            threshold,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FocusStatus {
    target: u16,
    readback: u16,
    settled: bool,
    remaining_ms: u64,
    generation: u64,
}

fn vcm_command(address: &str, command: &str) -> Result<String, String> {
    let socket: SocketAddr = address
        .parse()
        .map_err(|error| format!("invalid VCM address {address}: {error}"))?;
    let mut stream = TcpStream::connect_timeout(&socket, Duration::from_millis(100))
        .map_err(|error| format!("connect VCM {address}: {error}"))?;
    stream
        .set_read_timeout(Some(Duration::from_millis(100)))
        .ok();
    stream
        .set_write_timeout(Some(Duration::from_millis(100)))
        .ok();
    writeln!(stream, "{command}").map_err(|error| format!("write VCM command: {error}"))?;
    let mut response = String::new();
    BufReader::new(stream)
        .read_line(&mut response)
        .map_err(|error| format!("read VCM response: {error}"))?;
    let response = response.trim().to_string();
    if response.starts_with("ERR") || response.is_empty() {
        Err(format!("VCM {command}: {response}"))
    } else {
        Ok(response)
    }
}

fn parse_focus_status(response: &str) -> Result<FocusStatus, String> {
    let fields = response.split_whitespace().collect::<Vec<_>>();
    if fields.len() < 13 || fields[0..2] != ["FOCUS", "STATUS"] {
        return Err(format!("invalid focus status: {response}"));
    }
    let value = |name: &str| {
        fields
            .windows(2)
            .find(|pair| pair[0] == name)
            .map(|pair| pair[1])
            .ok_or_else(|| format!("focus status missing {name}: {response}"))
    };
    Ok(FocusStatus {
        target: value("TARGET")?
            .parse()
            .map_err(|error| format!("target: {error}"))?,
        readback: value("READBACK")?
            .parse()
            .map_err(|error| format!("readback: {error}"))?,
        settled: match value("SETTLED")? {
            "0" => false,
            "1" => true,
            other => return Err(format!("invalid SETTLED {other}")),
        },
        remaining_ms: value("REMAINING_MS")?
            .parse()
            .map_err(|error| format!("remaining: {error}"))?,
        generation: value("GENERATION")?
            .parse()
            .map_err(|error| format!("generation: {error}"))?,
    })
}

fn focus_positions(center: u16, radius: i32, step: i32) -> Vec<u16> {
    let mut positions = (-radius..=radius)
        .step_by(step as usize)
        .map(|offset| {
            (center as i32 + offset).clamp(VCM_MIN_POSITION as i32, VCM_MAX_POSITION as i32) as u16
        })
        .collect::<Vec<_>>();
    positions.sort_unstable();
    positions.dedup();
    positions
}

fn focus_positions_center_out(center: u16, radius: i32, step: i32) -> Vec<u16> {
    let mut positions = vec![center.clamp(VCM_MIN_POSITION, VCM_MAX_POSITION)];
    for distance in (step..=radius).step_by(step as usize) {
        for offset in [-distance, distance] {
            let position = (center as i32 + offset)
                .clamp(VCM_MIN_POSITION as i32, VCM_MAX_POSITION as i32)
                as u16;
            if !positions.contains(&position) {
                positions.push(position);
            }
        }
    }
    positions
}

fn median_focus(values: &mut [f64]) -> f64 {
    values.sort_by(f64::total_cmp);
    values.get(values.len() / 2).copied().unwrap_or(0.0)
}

fn low_confidence_focus_fallback(
    fine_best: (u16, f64),
    coarse_result: Option<(u16, f64)>,
    local_probe: bool,
    initial_position: u16,
    reference_score: Option<f64>,
) -> (u16, f64) {
    if local_probe {
        return (initial_position, reference_score.unwrap_or(fine_best.1));
    }
    coarse_result
        .filter(|result| result.1 >= MIN_AUTOFOCUS_BORDER_SCORE)
        .unwrap_or((VCM_CALIBRATED_EYE_FOCUS, fine_best.1))
}

fn focus_curve_bracketed(results: &[(u16, f64)], best: (u16, f64)) -> bool {
    if results.len() < 3 || best.1 < MIN_AUTOFOCUS_BORDER_SCORE {
        return false;
    }
    let mut curve = results.to_vec();
    curve.sort_by_key(|result| result.0);
    let Some(best_index) = curve.iter().position(|result| result.0 == best.0) else {
        return false;
    };
    if best_index == 0 || best_index + 1 == curve.len() {
        return false;
    }
    let required_falloff = best.1 * (1.0 - COARSE_FOCUS_MIN_FALLOFF);
    curve[0].1 <= required_falloff && curve[curve.len() - 1].1 <= required_falloff
}

fn next_unbracketed_focus_position(
    results: &[(u16, f64)],
    best: (u16, f64),
    step: u16,
) -> Option<u16> {
    if results.len() < 2 || step == 0 {
        return None;
    }
    let mut curve = results.to_vec();
    curve.sort_by_key(|result| result.0);
    let first = curve[0];
    let last = curve[curve.len() - 1];
    let required_falloff = best.1 * (1.0 - COARSE_FOCUS_MIN_FALLOFF);
    let extend_lower = best.0 == first.0 || first.1 > required_falloff;
    let extend_higher = best.0 == last.0 || last.1 > required_falloff;

    let lower = extend_lower
        .then(|| first.0.saturating_sub(step).max(VCM_MIN_POSITION))
        .filter(|position| *position < first.0);
    let higher = extend_higher
        .then(|| last.0.saturating_add(step).min(VCM_MAX_POSITION))
        .filter(|position| *position > last.0);
    match (lower, higher) {
        (Some(lower), Some(higher)) => {
            if first.1 > last.1 {
                Some(lower)
            } else {
                Some(higher)
            }
        }
        (Some(lower), None) => Some(lower),
        (None, Some(higher)) => Some(higher),
        (None, None) => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct FastLocalFocusChoice {
    position: u16,
    score: f64,
    direction: &'static str,
    gain: f64,
    baseline_spread: f64,
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct VerifiedFocusReference {
    eye: usize,
    position: u16,
    score: f64,
}

fn current_focus_reference(
    eye: usize,
    position: Option<u16>,
    score: f64,
) -> Option<VerifiedFocusReference> {
    (score.is_finite() && score >= MIN_AUTOFOCUS_BORDER_SCORE)
        .then_some(position)
        .flatten()
        .map(|position| VerifiedFocusReference {
            eye,
            position,
            score,
        })
}

fn stable_focus_baseline(samples: &[f64]) -> Result<(f64, f64), String> {
    if samples.len() < FAST_LOCAL_FOCUS_BASELINE_SAMPLES
        || samples.iter().any(|score| !score.is_finite())
    {
        return Err(format!(
            "fast local focus requires {} finite settled baseline samples, got {samples:?}",
            FAST_LOCAL_FOCUS_BASELINE_SAMPLES,
        ));
    }
    let mut sorted = samples.to_vec();
    sorted.sort_by(f64::total_cmp);
    let score = sorted[sorted.len() / 2].max(0.0);
    let spread = (sorted[sorted.len() - 1] - sorted[0]).abs() / score.max(1.0);
    if score < MIN_AUTOFOCUS_BORDER_SCORE {
        return Err(format!(
            "fast local focus baseline {score:.3} is below {MIN_AUTOFOCUS_BORDER_SCORE:.3}"
        ));
    }
    if spread > FAST_LOCAL_FOCUS_MAX_BASELINE_SPREAD {
        return Err(format!(
            "fast local focus baseline moved by {:.2}% across {samples:?}; maximum is {:.2}%",
            spread * 100.0,
            FAST_LOCAL_FOCUS_MAX_BASELINE_SPREAD * 100.0,
        ));
    }
    Ok((score, spread))
}

fn verified_focus_remains_sharp(
    reference: VerifiedFocusReference,
    eye: usize,
    position: Option<u16>,
    baseline_score: f64,
) -> bool {
    reference.eye == eye
        && position == Some(reference.position)
        && baseline_score >= reference.score * (1.0 - FAST_LOCAL_FOCUS_RECHECK_DROP)
}

fn choose_fast_local_focus(
    initial_position: u16,
    baseline_score: f64,
    baseline_spread: f64,
    results: &[(u16, f64)],
) -> Result<FastLocalFocusChoice, String> {
    let lower = results
        .iter()
        .copied()
        .find(|result| result.0 < initial_position);
    let higher = results
        .iter()
        .copied()
        .find(|result| result.0 > initial_position);
    if results.len() != 2 || lower.is_none() || higher.is_none() {
        return Err(format!(
            "invalid two-neighbor focus probe around {initial_position}: {results:?}"
        ));
    }
    let lower = lower.unwrap_or_default();
    let higher = higher.unwrap_or_default();
    let baseline_score = baseline_score.max(0.0);
    let hold = |gain| FastLocalFocusChoice {
        position: initial_position,
        score: baseline_score,
        direction: "hold",
        gain,
        baseline_spread,
    };
    if baseline_score < MIN_AUTOFOCUS_BORDER_SCORE
        || baseline_spread > FAST_LOCAL_FOCUS_MAX_BASELINE_SPREAD
    {
        return Ok(hold(0.0));
    }

    let lower_gain = lower.1.max(0.0) / baseline_score.max(1.0) - 1.0;
    let higher_gain = higher.1.max(0.0) / baseline_score.max(1.0) - 1.0;
    let noise_floor = SYMMETRIC_FOCUS_MIN_GAIN.max(baseline_spread * 1.5);
    let (position, score, direction, gain, other_gain) = if lower_gain > higher_gain {
        (lower.0, lower.1, "lower-dac", lower_gain, higher_gain)
    } else {
        (higher.0, higher.1, "higher-dac", higher_gain, lower_gain)
    };
    if gain < noise_floor || gain - other_gain < noise_floor * 0.5 {
        Ok(hold(gain))
    } else {
        Ok(FastLocalFocusChoice {
            position,
            score,
            direction,
            gain,
            baseline_spread,
        })
    }
}

impl RawBorderAutofocus {
    fn focus_depth_probe(&self, eye_index: usize) -> Option<raw_motion_octrees::FocusDepthProbe> {
        (eye_index == self.focus_eye
            && !self.waiting_for_settle
            && matches!(self.phase, FocusSweepPhase::Coarse | FocusSweepPhase::Fine))
        .then(|| raw_motion_octrees::FocusDepthProbe {
            position: self.positions[self.position_index],
            sweeping: true,
        })
    }

    fn is_provisional(&self) -> bool {
        self.evidence_mode == AutofocusEvidenceMode::ProvisionalCfaNeutral
    }

    fn metric_label(&self) -> &'static str {
        if self.is_provisional() {
            "provisional-cfa-neutral"
        } else {
            "verified-eye-arc"
        }
    }

    fn accepts_sample(&self, score: f64, point_count: usize) -> bool {
        match self.evidence_mode {
            AutofocusEvidenceMode::VerifiedEyeArc => has_eye_border_structure(score, point_count),
            AutofocusEvidenceMode::ProvisionalCfaNeutral => {
                score.is_finite() && score >= MIN_AUTOFOCUS_BORDER_SCORE
            }
        }
    }

    fn restore_initial_position(&mut self) -> Result<(), String> {
        let response = vcm_command(
            &self.address,
            &format!("FOCUS SET {}", self.initial_position),
        )?;
        self.final_result = None;
        eprintln!(
            "RAW autofocus discarded an identity-unverified result and restored pre-sweep focus: {response}"
        );
        Ok(())
    }

    fn start(address: &str, focus_eye: usize) -> Result<Self, String> {
        let response = vcm_command(address, "FOCUS GET")?;
        let current = response
            .split_whitespace()
            .nth(1)
            .ok_or_else(|| format!("invalid VCM response: {response}"))?
            .parse::<u16>()
            .map_err(|error| format!("invalid VCM position in {response}: {error}"))?
            .clamp(VCM_MIN_POSITION, VCM_MAX_POSITION);
        // Acquisition leaves the lens near a usable subject focus. Probe a
        // bounded physical-DAC neighborhood instead of traversing the actuator
        // or touching either mechanical end stop.
        // This protocol addresses the physical 10-bit DAC. The old vendor
        // application's documented 0..100 manual-focus value is not the same
        // scale (a live direct-DAC calibration is sharp near 512, not 32).
        // Begin at the acquired focus and probe center-out over a deliberately
        // small range. Large 128-DAC jumps changed the eye patches enough to
        // look like subject loss and produced needless actuator clicks.
        let positions = focus_positions_center_out(current, COARSE_FOCUS_RADIUS, COARSE_FOCUS_STEP);
        vcm_command(address, &format!("FOCUS SET {}", positions[0]))?;
        let label = subject_eye_label(focus_eye);
        eprintln!(
            "RAW eye-arc autofocus eye={label} coarse center={current} positions={positions:?}"
        );
        Ok(Self {
            address: address.to_string(),
            focus_eye,
            evidence_mode: AutofocusEvidenceMode::VerifiedEyeArc,
            started_at: Instant::now(),
            initial_position: current,
            phase: FocusSweepPhase::Coarse,
            positions,
            position_index: 0,
            settle_frames: 0,
            frames_seen: 0,
            samples: Vec::new(),
            results: Vec::new(),
            waiting_for_settle: true,
            post_settle_frames: 1,
            local_probe: false,
            reference_score: None,
            reference_spread: 0.0,
            coarse_result: None,
            final_result: None,
            motion_gate: FocusMotionGate::default(),
            motion_wait_frames: 0,
            two_neighbor_probe: false,
        })
    }

    fn start_provisional(address: &str, focus_eye: usize) -> Result<Self, String> {
        let mut controller = Self::start(address, focus_eye)?;
        controller.evidence_mode = AutofocusEvidenceMode::ProvisionalCfaNeutral;
        controller.positions = focus_positions_center_out(
            controller.initial_position,
            ROUGH_FOCUS_RADIUS,
            ROUGH_FOCUS_STEP,
        );
        eprintln!(
            "RAW one-time rough focus eye={} metric={} deadline_ms={} positions={:?}; model admission remains anatomy-gated",
            subject_eye_label(focus_eye),
            controller.metric_label(),
            ROUGH_FOCUS_SESSION_TIMEOUT.as_millis(),
            controller.positions,
        );
        Ok(controller)
    }

    fn start_local(
        address: &str,
        focus_eye: usize,
        baseline_samples: &[f64],
        reverse_probe_order: bool,
    ) -> Result<Self, String> {
        let (reference_score, reference_spread) = stable_focus_baseline(baseline_samples)?;
        let response = vcm_command(address, "FOCUS GET")?;
        let current = response
            .split_whitespace()
            .nth(1)
            .ok_or_else(|| format!("invalid VCM response: {response}"))?
            .parse::<u16>()
            .map_err(|error| format!("invalid VCM position in {response}: {error}"))?
            .clamp(VCM_MIN_POSITION, VCM_MAX_POSITION);
        let lower = current
            .saturating_sub(SYMMETRIC_FOCUS_PROBE_STEP)
            .max(VCM_MIN_POSITION);
        let higher = current
            .saturating_add(SYMMETRIC_FOCUS_PROBE_STEP)
            .min(VCM_MAX_POSITION);
        if lower == current || higher == current {
            return Err(format!(
                "cannot symmetrically probe focus position {current} within VCM range"
            ));
        }
        let positions = if reverse_probe_order {
            vec![higher, lower]
        } else {
            vec![lower, higher]
        };
        vcm_command(address, &format!("FOCUS SET {}", positions[0]))?;
        let label = subject_eye_label(focus_eye);
        eprintln!(
            "RAW fast local eye-arc probe eye={label} center={current} baseline={reference_score:.3} spread={:.2}% positions={positions:?}",
            reference_spread * 100.0,
        );
        Ok(Self {
            address: address.to_string(),
            focus_eye,
            evidence_mode: AutofocusEvidenceMode::VerifiedEyeArc,
            started_at: Instant::now(),
            initial_position: current,
            // The settled score stream supplied the center baseline. Only the
            // two neighboring DAC positions remain to be sampled.
            phase: FocusSweepPhase::Fine,
            positions,
            position_index: 0,
            settle_frames: 0,
            frames_seen: 0,
            samples: Vec::new(),
            results: Vec::new(),
            waiting_for_settle: true,
            post_settle_frames: 0,
            local_probe: true,
            reference_score: Some(reference_score),
            reference_spread,
            coarse_result: None,
            final_result: None,
            motion_gate: FocusMotionGate::default(),
            motion_wait_frames: 0,
            two_neighbor_probe: true,
        })
    }

    fn finish_fast_local_probe(&mut self) -> Result<(), String> {
        let reference_score = self
            .reference_score
            .ok_or("fast local focus lost its settled baseline")?;
        let choice = choose_fast_local_focus(
            self.initial_position,
            reference_score,
            self.reference_spread,
            &self.results,
        )?;
        eprintln!(
            "RAW fast local eye-arc decision={} position={} gain={:.2}% baseline_spread={:.2}% scores={:?}",
            choice.direction,
            choice.position,
            choice.gain * 100.0,
            choice.baseline_spread * 100.0,
            self.results,
        );
        let result = (choice.position, choice.score);
        if self
            .results
            .last()
            .is_some_and(|sample| sample.0 == choice.position)
        {
            self.finish_at_current_position(result);
            Ok(())
        } else {
            self.begin_final_move(result)
        }
    }

    fn finish_at_current_position(&mut self, result: (u16, f64)) {
        self.phase = FocusSweepPhase::Complete;
        self.positions = vec![result.0];
        self.position_index = 0;
        self.final_result = Some(result);
        self.waiting_for_settle = false;
        eprintln!(
            "RAW autofocus candidate eye={} metric={} position={} score={:.3} elapsed_ms={}; selected probe is already settled, awaiting identity acceptance",
            subject_eye_label(self.focus_eye),
            self.metric_label(),
            result.0,
            result.1,
            self.started_at.elapsed().as_millis(),
        );
    }

    fn begin_final_move(&mut self, result: (u16, f64)) -> Result<(), String> {
        vcm_command(&self.address, &format!("FOCUS SET {}", result.0))?;
        self.phase = FocusSweepPhase::Finalizing;
        self.positions = vec![result.0];
        self.position_index = 0;
        self.final_result = Some(result);
        self.waiting_for_settle = true;
        self.post_settle_frames = if self.local_probe { 0 } else { 2 };
        self.motion_gate.reset();
        self.motion_wait_frames = 0;
        Ok(())
    }

    fn current_position_settled(&self) -> bool {
        !self.waiting_for_settle
    }

    fn observe(
        &mut self,
        eye_index: usize,
        score: f64,
        point_count: usize,
        motion_score: f64,
        comparable_to_previous: bool,
    ) -> Result<(), String> {
        if self.phase == FocusSweepPhase::Complete || eye_index != self.focus_eye {
            return Ok(());
        }
        if self.is_provisional() && self.started_at.elapsed() > ROUGH_FOCUS_SESSION_TIMEOUT {
            return Err(format!(
                "{FATAL_ROUGH_FOCUS}one-time rough focus exceeded {}ms",
                ROUGH_FOCUS_SESSION_TIMEOUT.as_millis(),
            ));
        }
        if self.waiting_for_settle {
            let status = parse_focus_status(&vcm_command(&self.address, "FOCUS STATUS")?)?;
            let expected = self.positions[self.position_index];
            if status.target != expected {
                return Err(format!(
                    "focus move generation {} expected target {} but target/readback are {}/{}",
                    status.generation, expected, status.target, status.readback
                ));
            }
            if !status.settled {
                return Ok(());
            }
            if status.readback != expected {
                return Err(format!(
                    "settled focus move generation {} expected readback {} but target/readback are {}/{}",
                    status.generation, expected, status.target, status.readback
                ));
            }
            if self.post_settle_frames > 0 {
                self.post_settle_frames -= 1;
                return Ok(());
            }
            self.waiting_for_settle = false;
            self.motion_gate.reset();
            self.motion_wait_frames = 0;
            eprintln!(
                "RAW host observed settled VCM generation={} target={}",
                status.generation, status.target
            );
            if self.phase == FocusSweepPhase::Finalizing {
                let best = self
                    .final_result
                    .ok_or("final autofocus result was not retained")?;
                self.phase = FocusSweepPhase::Complete;
                let label = subject_eye_label(self.focus_eye);
                eprintln!(
                    "RAW autofocus candidate eye={label} metric={} position={} score={:.3} elapsed_ms={}; final VCM target settled, awaiting identity acceptance",
                    self.metric_label(),
                    best.0,
                    best.1,
                    self.started_at.elapsed().as_millis(),
                );
                return Ok(());
            }
        }
        if self.settle_frames > 0 {
            self.settle_frames -= 1;
            return Ok(());
        }
        let motion = self
            .motion_gate
            .observe(motion_score, comparable_to_previous);
        if !motion.ready {
            self.motion_wait_frames = self.motion_wait_frames.saturating_add(1);
            if self.motion_wait_frames % 10 == 0 {
                eprintln!(
                    "RAW autofocus waiting for selected eye ROI to become still: motion={motion_score:.2} threshold={:.2}",
                    motion.threshold,
                );
            }
            if self.motion_wait_frames >= AUTOFOCUS_MOTION_WAIT_FRAMES {
                return Err(format!(
                    "selected eye ROI stayed in motion for {} RAW exposures at focus position {}",
                    self.motion_wait_frames, self.positions[self.position_index],
                ));
            }
            return Ok(());
        }
        self.frames_seen += 1;
        if self.accepts_sample(score, point_count) {
            self.samples.push(score);
        }
        let sample_target = if self.local_probe {
            FAST_LOCAL_FOCUS_PROBE_SAMPLES
        } else {
            3
        };
        let frame_limit = 15;
        if self.samples.len() < sample_target && self.frames_seen < frame_limit {
            return Ok(());
        }
        let position = self.positions[self.position_index];
        let score = if self.samples.len() >= sample_target {
            if self.samples.len() == 2 {
                (self.samples[0] + self.samples[1]) * 0.5
            } else {
                median_focus(&mut self.samples)
            }
        } else {
            0.0
        };
        self.samples.clear();
        self.frames_seen = 0;
        self.results.push((position, score));
        eprintln!(
            "RAW autofocus metric={} position={position} median={score:.3}",
            self.metric_label()
        );
        self.position_index += 1;
        if self.two_neighbor_probe && self.phase == FocusSweepPhase::Fine {
            if self.position_index >= self.positions.len() {
                return self.finish_fast_local_probe();
            }
            vcm_command(
                &self.address,
                &format!("FOCUS SET {}", self.positions[self.position_index]),
            )?;
            self.waiting_for_settle = true;
            self.post_settle_frames = if self.local_probe { 0 } else { 1 };
            self.settle_frames = 0;
            self.motion_gate.reset();
            self.motion_wait_frames = 0;
            return Ok(());
        }
        if self.position_index < self.positions.len() {
            vcm_command(
                &self.address,
                &format!("FOCUS SET {}", self.positions[self.position_index]),
            )?;
            self.waiting_for_settle = true;
            self.post_settle_frames = 1;
            self.settle_frames = 0;
            self.motion_gate.reset();
            self.motion_wait_frames = 0;
            return Ok(());
        }
        let best = self
            .results
            .iter()
            .max_by(|a, b| a.1.total_cmp(&b.1))
            .copied()
            .ok_or("no valid eye-arc focus result")?;
        if self.phase == FocusSweepPhase::Coarse {
            if best.1 < MIN_AUTOFOCUS_BORDER_SCORE {
                eprintln!(
                    "RAW eye-arc curve confidence {:.3} is below {:.3}; restoring pre-sweep focus {}",
                    best.1, MIN_AUTOFOCUS_BORDER_SCORE, self.initial_position
                );
                self.begin_final_move((self.initial_position, best.1))?;
                return Ok(());
            }
            if !focus_curve_bracketed(&self.results, best) {
                if self.is_provisional() {
                    if let Some(next) = next_unbracketed_focus_position(
                        &self.results,
                        best,
                        ROUGH_FOCUS_STEP as u16,
                    ) {
                        self.positions.push(next);
                        vcm_command(&self.address, &format!("FOCUS SET {next}"))?;
                        self.waiting_for_settle = true;
                        self.post_settle_frames = 1;
                        self.settle_frames = 0;
                        self.motion_gate.reset();
                        self.motion_wait_frames = 0;
                        eprintln!(
                            "RAW one-time rough focus extended its unbracketed curve toward position={next} best={best:?} elapsed_ms={}",
                            self.started_at.elapsed().as_millis(),
                        );
                        return Ok(());
                    }
                }
                return Err(format!(
                    "coarse focus curve is unbracketed across {:?}; best was position {} score {:.3}",
                    self.results, best.0, best.1
                ));
            }
            self.coarse_result = Some(best);
            if self.local_probe {
                self.reference_score = self
                    .results
                    .iter()
                    .find(|result| result.0 == self.initial_position)
                    .map(|result| result.1);
            }
            self.phase = FocusSweepPhase::Fine;
            self.positions = if self.is_provisional() {
                focus_positions_center_out(best.0, ROUGH_FOCUS_FINE_RADIUS, ROUGH_FOCUS_FINE_STEP)
            } else if self.local_probe {
                focus_positions(best.0, 4, 2)
            } else {
                focus_positions_center_out(best.0, 8, 4)
            };
            self.position_index = 0;
            self.results.clear();
            self.frames_seen = 0;
            vcm_command(&self.address, &format!("FOCUS SET {}", self.positions[0]))?;
            self.waiting_for_settle = true;
            self.post_settle_frames = 1;
            self.settle_frames = 0;
            self.motion_gate.reset();
            self.motion_wait_frames = 0;
            eprintln!(
                "RAW eye-arc autofocus fine center={} positions={:?}",
                best.0, self.positions
            );
        } else {
            let reference_score = self.reference_score.or_else(|| {
                self.results
                    .iter()
                    .find(|result| result.0 == self.initial_position)
                    .map(|result| result.1)
            });
            let best = if best.1 < MIN_AUTOFOCUS_BORDER_SCORE {
                let fallback = low_confidence_focus_fallback(
                    best,
                    self.coarse_result,
                    self.local_probe,
                    self.initial_position,
                    reference_score,
                );
                eprintln!(
                    "RAW fine eye-arc confidence {:.3} is below {:.3}; retaining validated focus position {}",
                    best.1, MIN_AUTOFOCUS_BORDER_SCORE, fallback.0
                );
                fallback
            } else if self.local_probe
                && reference_score.is_some_and(|reference| best.1 < reference * 1.02)
            {
                let reference = reference_score.unwrap_or(best.1);
                eprintln!(
                    "RAW continuous autofocus held position {} because the best probe improved sharpness by less than 2%",
                    self.initial_position
                );
                (self.initial_position, reference)
            } else {
                best
            };
            self.begin_final_move(best)?;
        }
        Ok(())
    }
}

impl Drop for RawBorderAutofocus {
    fn drop(&mut self) {
        if self.phase != FocusSweepPhase::Complete {
            match vcm_command(
                &self.address,
                &format!("FOCUS SET {}", self.initial_position),
            ) {
                Ok(response) => eprintln!(
                    "RAW host cancelled autofocus and restored pre-sweep position: {response}"
                ),
                Err(error) => eprintln!(
                    "RAW host cancelled autofocus but could not restore position {}: {error}",
                    self.initial_position
                ),
            }
        }
    }
}

#[derive(Clone)]
struct Backdrop {
    width: usize,
    height: usize,
    pixels: Arc<Vec<u32>>,
}

#[derive(Clone, Copy, Debug)]
struct RingPoseObservation {
    captured_at: Instant,
    center: (f64, f64),
    major_radius: f64,
    minor_radius: f64,
    angle: f64,
}

#[derive(Clone, Copy, Debug)]
struct ProjectedVisionPose {
    center: (f64, f64),
    // Projected vector from the anatomical rotation center toward the
    // camera-visible iris pole. Retaining the vector, rather than only its
    // endpoint, lets temporal scoring distinguish translation from rotation.
    pole: (f64, f64),
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct LockedRayOrigin {
    eye: usize,
    // X/Y are absolute sensor coordinates so moving the displayed ROI cannot
    // make a locked origin drift. Z is model-space depth behind the iris-slice
    // center; the slice center defines Z=0 because metric camera depth is not
    // calibrated yet.
    sensor_xyz: (f64, f64, f64),
    sphere_radius: f64,
    samples: u64,
    last_timestamp_ns: u64,
}

/// Presentation-only copy of an independently published anatomical globe
/// pivot for the current frame. Weak frames deliberately clear this copy: a
/// stale or merely latent pivot is not useful enough to put on screen and can
/// never re-enter segmentation, gaze publication, mouse control, or the
/// temporal anatomy estimator.
#[derive(Clone, Copy, Debug, PartialEq)]
struct PresentationPivotContact {
    eye: usize,
    directly_published: bool,
    sensor_xyz: (f64, f64, f64),
    boundary_sensor_center: (f64, f64),
    boundary_radius: f64,
    projected_gaze_pole: (f64, f64),
    sphere_radius: f64,
    source_timestamp_ns: u64,
    last_frame_timestamp_ns: u64,
    held_frames: u64,
}

#[derive(Default)]
struct RotationCenterHistory {
    observations: VecDeque<RingPoseObservation>,
    estimate: Option<ProjectedVisionPose>,
    previous_ring: Option<RingPoseObservation>,
    stable_frames: u32,
}

impl RotationCenterHistory {
    fn observe(
        &mut self,
        now: Instant,
        center: (f64, f64),
        major_radius: f64,
        minor_radius: f64,
        angle: f64,
        motion_score: f64,
        comparable_to_previous: bool,
    ) -> Option<ProjectedVisionPose> {
        let mut accepted_observation = None;
        if center.0.is_finite()
            && center.1.is_finite()
            && major_radius.is_finite()
            && minor_radius.is_finite()
            && angle.is_finite()
            && major_radius >= 8.0
            && minor_radius <= major_radius
            && raw_iris_focus::projected_circular_limbus_axes_plausible(major_radius, minor_radius)
        {
            let observation = RingPoseObservation {
                captured_at: now,
                center,
                major_radius,
                minor_radius,
                angle,
            };
            let geometrically_still = self.previous_ring.is_some_and(|previous| {
                let center_limit = (major_radius * 0.10).clamp(1.5, 3.0);
                let center_shift =
                    (previous.center.0 - center.0).hypot(previous.center.1 - center.1);
                let radius_shift = (previous.major_radius - major_radius).abs()
                    / previous.major_radius.max(major_radius).max(1.0);
                let previous_ratio = previous.minor_radius / previous.major_radius.max(1.0);
                let ratio = minor_radius / major_radius.max(1.0);
                let ellipse_is_directional = previous_ratio.min(ratio) < 0.96;
                let angle_shift = wrapped_angle_distance(previous.angle, angle);
                center_shift <= center_limit
                    && radius_shift <= 0.08
                    && (previous_ratio - ratio).abs() <= 0.06
                    && (!ellipse_is_directional || angle_shift <= 0.16)
            });
            let image_still = comparable_to_previous
                && motion_score.is_finite()
                && motion_score <= ROTATION_POSE_STILL_MOTION_MAX;
            self.stable_frames = if geometrically_still && image_still {
                self.stable_frames.saturating_add(1)
            } else {
                0
            };
            self.previous_ring = Some(observation);
            self.observations.push_back(observation);
            accepted_observation = Some(observation);
        } else {
            self.stable_frames = 0;
            self.previous_ring = None;
        }
        while self.observations.front().is_some_and(|observation| {
            now.saturating_duration_since(observation.captured_at) > ROTATION_CENTER_HISTORY
        }) {
            self.observations.pop_front();
        }
        if self.observations.is_empty() {
            self.estimate = None;
            return None;
        }
        let firmness = rotation_pose_firmness(self.stable_frames);
        let next = infer_projected_vision_pose(&self.observations, self.estimate, firmness);
        let Some(next) = next else {
            if firmness > 0.0 {
                if let (Some(mut held), Some(observation)) = (self.estimate, accepted_observation) {
                    // A static ring cannot triangulate a new globe center, but
                    // it is excellent evidence that an already-established
                    // center and pole should stay put. Permit only a very slow
                    // pole correction for detector quantization.
                    let observed_pole = (
                        observation.center.0 - held.center.0,
                        observation.center.1 - held.center.1,
                    );
                    let pole_alpha = 0.02 * (1.0 - firmness);
                    held.pole = blend_point(held.pole, observed_pole, pole_alpha);
                    self.estimate = Some(held);
                    return self.estimate;
                }
            }
            self.estimate = None;
            return None;
        };
        self.estimate = Some(match self.estimate {
            Some(previous) => {
                // React promptly to genuine motion, then progressively harden
                // the solution as image and ring geometry remain still.
                let alpha = 0.45 - firmness * 0.40;
                ProjectedVisionPose {
                    center: blend_point(previous.center, next.center, alpha),
                    pole: blend_point(previous.pole, next.pole, alpha),
                }
            }
            None => next,
        });
        self.estimate
    }
}

fn blend_point(previous: (f64, f64), next: (f64, f64), alpha: f64) -> (f64, f64) {
    let alpha = alpha.clamp(0.0, 1.0);
    (
        previous.0 * (1.0 - alpha) + next.0 * alpha,
        previous.1 * (1.0 - alpha) + next.1 * alpha,
    )
}

fn wrapped_angle_distance(left: f64, right: f64) -> f64 {
    let mut delta = (left - right).abs() % std::f64::consts::PI;
    if delta > std::f64::consts::FRAC_PI_2 {
        delta = std::f64::consts::PI - delta;
    }
    delta
}

fn rotation_pose_firmness(stable_frames: u32) -> f64 {
    if stable_frames <= ROTATION_POSE_FIRM_START_FRAMES {
        return 0.0;
    }
    ((stable_frames - ROTATION_POSE_FIRM_START_FRAMES) as f64
        / (ROTATION_POSE_FIRM_FULL_FRAMES - ROTATION_POSE_FIRM_START_FRAMES) as f64)
        .clamp(0.0, 1.0)
}

fn infer_projected_rotation_center(
    observations: &VecDeque<RingPoseObservation>,
) -> Option<(f64, f64)> {
    infer_projected_vision_pose(observations, None, 0.0).map(|pose| pose.center)
}

fn infer_projected_vision_pose(
    observations: &VecDeque<RingPoseObservation>,
    prior: Option<ProjectedVisionPose>,
    firmness: f64,
) -> Option<ProjectedVisionPose> {
    let informative = observations
        .iter()
        .filter_map(|observation| {
            let ratio = (observation.minor_radius / observation.major_radius).clamp(0.0, 1.0);
            let tilt = (1.0 - ratio * ratio).sqrt();
            (tilt >= 0.08).then(|| {
                let normal = (-observation.angle.sin(), observation.angle.cos());
                (*observation, tilt, normal)
            })
        })
        .collect::<Vec<_>>();
    if informative.len() < ROTATION_CENTER_MIN_OBSERVATIONS {
        return None;
    }
    let mut angular_diversity = 0.0f64;
    let mut center_span = 0.0f64;
    for left in &informative {
        for right in &informative {
            angular_diversity =
                angular_diversity.max((left.2 .0 * right.2 .1 - left.2 .1 * right.2 .0).abs());
            center_span = center_span.max(
                (left.0.center.0 - right.0.center.0).hypot(left.0.center.1 - right.0.center.1),
            );
        }
    }
    if angular_diversity < 0.10 || center_span < 1.5 {
        return None;
    }

    let mut best: Option<(f64, f64, ProjectedVisionPose)> = None;
    for scale_step in 0..=20 {
        let depth_to_ring_radius = 1.15 + scale_step as f64 * 0.085;
        let latest = informative.last()?;
        for initial_sign in [-1.0, 1.0] {
            let latest_offset = depth_to_ring_radius * latest.0.major_radius * latest.1;
            let mut center = (
                latest.0.center.0 + initial_sign * latest_offset * latest.2 .0,
                latest.0.center.1 + initial_sign * latest_offset * latest.2 .1,
            );
            let mut selected = Vec::with_capacity(informative.len());
            for _ in 0..4 {
                selected.clear();
                for (observation, tilt, normal) in &informative {
                    let offset = depth_to_ring_radius * observation.major_radius * tilt;
                    let plus = (
                        observation.center.0 + offset * normal.0,
                        observation.center.1 + offset * normal.1,
                    );
                    let minus = (
                        observation.center.0 - offset * normal.0,
                        observation.center.1 - offset * normal.1,
                    );
                    selected.push(
                        if (plus.0 - center.0).hypot(plus.1 - center.1)
                            <= (minus.0 - center.0).hypot(minus.1 - center.1)
                        {
                            plus
                        } else {
                            minus
                        },
                    );
                }
                let mut xs = selected.iter().map(|point| point.0).collect::<Vec<_>>();
                let mut ys = selected.iter().map(|point| point.1).collect::<Vec<_>>();
                center = (median_focus(&mut xs), median_focus(&mut ys));
            }
            let mut residuals = selected
                .iter()
                .map(|point| (point.0 - center.0).hypot(point.1 - center.1))
                .collect::<Vec<_>>();
            let residual = median_focus(&mut residuals);
            let pole = (latest.0.center.0 - center.0, latest.0.center.1 - center.1);
            let pose = ProjectedVisionPose { center, pole };
            let temporal_penalty = prior
                .map(|prior| projected_pose_temporal_penalty(prior, pose, latest.0.major_radius))
                .unwrap_or(0.0)
                * firmness.clamp(0.0, 1.0);
            let score = residual + temporal_penalty;
            if best.as_ref().is_none_or(|candidate| score < candidate.0) {
                best = Some((score, residual, pose));
            }
        }
    }
    best.filter(|(_, residual, _)| *residual <= 5.0)
        .map(|(_, _, pose)| pose)
}

fn projected_pose_temporal_penalty(
    prior: ProjectedVisionPose,
    candidate: ProjectedVisionPose,
    ring_radius: f64,
) -> f64 {
    let center_translation =
        (candidate.center.0 - prior.center.0).hypot(candidate.center.1 - prior.center.1);
    let pole_translation = (candidate.pole.0 - prior.pole.0).hypot(candidate.pole.1 - prior.pole.1);
    let prior_length = prior.pole.0.hypot(prior.pole.1);
    let candidate_length = candidate.pole.0.hypot(candidate.pole.1);
    let rotation = if prior_length > 1.0e-6 && candidate_length > 1.0e-6 {
        ((prior.pole.0 * candidate.pole.0 + prior.pole.1 * candidate.pole.1)
            / (prior_length * candidate_length))
            .clamp(-1.0, 1.0)
            .acos()
    } else {
        0.0
    };
    center_translation * 0.55 + pole_translation * 0.30 + rotation * ring_radius.max(1.0) * 0.75
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct RadiusKinematicSupport {
    estimate: f64,
    minimum: f64,
    maximum: f64,
}

#[derive(Debug, Default)]
struct RadiusRateLimiter {
    state: Option<(Instant, f64)>,
}

impl RadiusRateLimiter {
    /// Freeze the same continuous-time physiological support used by the
    /// publication limiter so a native-coordinate search can look for an
    /// admissible edge instead of first choosing an impossible edge and then
    /// merely resizing or discarding it. After a one-second evidence gap the
    /// continuous trajectory deliberately expires; robust size history owns
    /// longer reacquisition intervals.
    fn kinematic_support(
        &self,
        now: Instant,
        max_contraction_per_second: f64,
        max_expansion_per_second: f64,
    ) -> Option<RadiusKinematicSupport> {
        let (previous_at, previous_radius) = self.state?;
        if !previous_radius.is_finite() || previous_radius <= 0.0 {
            return None;
        }
        let elapsed_since_observation = now.saturating_duration_since(previous_at);
        if elapsed_since_observation > Duration::from_secs(1) {
            return None;
        }
        // A delayed worker result or one missing segmentation frame is not
        // evidence that an anatomical boundary changed discontinuously.
        // Bound each publication by one ordinary 10 Hz interval; repeated
        // current-RAW edge pressure can still advance the trajectory on
        // subsequent frames. This keeps the pupil's reconstructed circular
        // area below a two-percent change between consecutive publications.
        let elapsed = elapsed_since_observation
            .min(RADIUS_RATE_LIMITER_MAX_PUBLICATION_STEP)
            .as_secs_f64();
        let minimum =
            previous_radius * (1.0 - max_contraction_per_second.max(0.0) * elapsed).max(0.0);
        let maximum = if max_expansion_per_second.is_finite() {
            previous_radius * (1.0 + max_expansion_per_second.max(0.0) * elapsed)
        } else {
            f64::INFINITY
        };
        Some(RadiusKinematicSupport {
            estimate: previous_radius,
            minimum,
            maximum,
        })
    }

    fn constrain(
        &self,
        now: Instant,
        measured_radius: f64,
        max_contraction_per_second: f64,
        max_expansion_per_second: f64,
    ) -> f64 {
        if !measured_radius.is_finite() || measured_radius <= 0.0 {
            return measured_radius;
        }
        let Some(support) =
            self.kinematic_support(now, max_contraction_per_second, max_expansion_per_second)
        else {
            return measured_radius;
        };
        measured_radius.clamp(support.minimum, support.maximum)
    }

    fn observe(
        &mut self,
        now: Instant,
        measured_radius: f64,
        max_contraction_per_second: f64,
        max_expansion_per_second: f64,
    ) -> f64 {
        if !measured_radius.is_finite() || measured_radius <= 0.0 {
            return measured_radius;
        }
        let Some((previous_at, _)) = self.state else {
            self.state = Some((now, measured_radius));
            return measured_radius;
        };
        let elapsed_since_observation = now.saturating_duration_since(previous_at);
        if elapsed_since_observation > Duration::from_secs(1) {
            // This limiter bounds a continuous physiological trajectory. An
            // extended missing-boundary interval is not continuous evidence;
            // the robust hard/soft size supports must validate a fresh fit
            // instead of dragging it toward an indefinitely old ratio.
            self.state = Some((now, measured_radius));
            return measured_radius;
        }
        let stabilized = self.constrain(
            now,
            measured_radius,
            max_contraction_per_second,
            max_expansion_per_second,
        );
        self.state = Some((now, stabilized));
        stabilized
    }

    fn constrain_with_hard_bounds(
        &self,
        now: Instant,
        measured_radius: f64,
        max_contraction_per_second: f64,
        max_expansion_per_second: f64,
        hard_lower: f64,
        hard_upper: f64,
    ) -> (f64, bool) {
        let stabilized = self.constrain(
            now,
            measured_radius,
            max_contraction_per_second,
            max_expansion_per_second,
        );
        let tolerance = 1.0e-9 * measured_radius.abs().max(stabilized.abs()).max(1.0);
        let trajectory_limited = (stabilized - measured_radius).abs() > tolerance;
        let bounded = if hard_lower.is_finite()
            && hard_upper.is_finite()
            && hard_lower > 0.0
            && hard_upper >= hard_lower
        {
            stabilized.clamp(hard_lower, hard_upper)
        } else {
            stabilized
        };
        (bounded, trajectory_limited)
    }

    fn enforce_state_hard_bounds(
        &mut self,
        now: Instant,
        hard_lower: f64,
        hard_upper: f64,
    ) -> bool {
        if !hard_lower.is_finite()
            || !hard_upper.is_finite()
            || hard_lower <= 0.0
            || hard_upper < hard_lower
        {
            return false;
        }
        let Some((_, previous)) = self.state else {
            return false;
        };
        let bounded = previous.clamp(hard_lower, hard_upper);
        let tolerance = 1.0e-9 * previous.abs().max(bounded.abs()).max(1.0);
        if (bounded - previous).abs() <= tolerance {
            return false;
        }
        // This mutation is authorized by an explicit operator guide, not by
        // the current image candidate. It remains valid while R is frozen and
        // cannot let a blurry measurement choose the new trajectory value.
        self.state = Some((now, bounded));
        true
    }

    fn observe_with_hard_bounds(
        &mut self,
        now: Instant,
        measured_radius: f64,
        max_contraction_per_second: f64,
        max_expansion_per_second: f64,
        hard_lower: f64,
        hard_upper: f64,
    ) -> (f64, bool) {
        let (bounded, trajectory_limited) = self.constrain_with_hard_bounds(
            now,
            measured_radius,
            max_contraction_per_second,
            max_expansion_per_second,
            hard_lower,
            hard_upper,
        );
        if bounded.is_finite() && bounded > 0.0 {
            // This is the admitted/mutating path. Explicit operator hard
            // guides therefore restart the trajectory at the published
            // boundary, while the read-only path above never changes state.
            self.state = Some((now, bounded));
        }
        (bounded, trajectory_limited)
    }
}

/// Provenance of the limbus projection used to express pupil size in
/// fronto-parallel radius space.  The pupil-size posterior is independent of
/// the selected rough-center method; this enum records only the current scale
/// and affine projection reference.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum PupilProjectionSource {
    #[default]
    SelectedIris,
    CensoredLimbus,
    RawEyeAnatomy,
}

impl PupilProjectionSource {
    fn label(self) -> &'static str {
        match self {
            Self::SelectedIris => "selected-iris",
            Self::CensoredLimbus => "censored-limbus",
            Self::RawEyeAnatomy => "raw-eye-anatomy",
        }
    }
}

/// Unit-safe radius coordinates for the physical pupil-size posterior.
///
/// These constructors deliberately live behind a private module boundary:
/// image-plane ellipse radii cannot be passed to temporal physical-size state
/// as bare `f64`s. A fronto-parallel radius is produced either by the
/// projected-circle limbus model or by explicitly undoing the limbus affine
/// foreshortening from a projected equal-area pupil radius.
mod pupil_radius_units {
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub(super) struct ProjectedAreaEquivalentRadiusPx(f64);

    #[derive(Clone, Copy, Debug, PartialEq)]
    pub(super) struct AffineForeshortening(f64);

    #[derive(Clone, Copy, Debug, PartialEq)]
    pub(super) struct FrontoParallelCircleRadiusPx(f64);

    #[derive(Clone, Copy, Debug, PartialEq)]
    pub(super) struct PhysicalRadiusRatio(f64);

    impl ProjectedAreaEquivalentRadiusPx {
        pub(super) fn from_ellipse_axes(axis_a: f64, axis_b: f64) -> Option<Self> {
            if !axis_a.is_finite() || !axis_b.is_finite() || axis_a <= 0.0 || axis_b <= 0.0 {
                return None;
            }
            let radius = (axis_a * axis_b).sqrt();
            (radius.is_finite() && radius > 0.0).then_some(Self(radius))
        }
    }

    impl AffineForeshortening {
        pub(super) fn from_minor_to_major(minor_to_major: f64) -> Option<Self> {
            (minor_to_major.is_finite()
                && (super::raw_iris_focus::PROVISIONAL_CENTRAL_CAMERA_LIMBUS_ENVELOPE
                    .absolute_minimum_minor_to_major..=1.0)
                    .contains(&minor_to_major))
            .then_some(Self(minor_to_major))
        }
    }

    impl FrontoParallelCircleRadiusPx {
        /// Under weak perspective, a projected physical circle retains its
        /// true radius along the ellipse's unforeshortened major axis.
        pub(super) fn from_projected_circular_limbus_axes(
            axis_a: f64,
            axis_b: f64,
        ) -> Option<Self> {
            ProjectedAreaEquivalentRadiusPx::from_ellipse_axes(axis_a, axis_b)?;
            let major = axis_a.max(axis_b);
            let minor = axis_a.min(axis_b);
            AffineForeshortening::from_minor_to_major(minor / major)?;
            // This is the closed-form rectification for a projected circle:
            // sqrt(a*b) / sqrt(b/a) = a. Return the measured major axis
            // directly to avoid introducing roundoff into operator guides.
            Some(Self(major))
        }

        pub(super) fn from_projected_area(
            projected: ProjectedAreaEquivalentRadiusPx,
            foreshortening: AffineForeshortening,
        ) -> Option<Self> {
            let radius = projected.0 / foreshortening.0.sqrt();
            (radius.is_finite() && radius > 0.0).then_some(Self(radius))
        }

        pub(super) fn value(self) -> f64 {
            self.0
        }

        pub(super) fn ratio_to(self, reference: Self) -> Option<PhysicalRadiusRatio> {
            let ratio = self.0 / reference.0;
            (ratio.is_finite() && ratio > 0.0).then_some(PhysicalRadiusRatio(ratio))
        }
    }

    impl PhysicalRadiusRatio {
        pub(super) fn value(self) -> f64 {
            self.0
        }
    }
}

use pupil_radius_units::{
    AffineForeshortening, FrontoParallelCircleRadiusPx, ProjectedAreaEquivalentRadiusPx,
};

/// Weak-perspective projection of a physical circular limbus.  Its larger
/// semi-axis is the fronto-parallel radius; `minor_to_major` carries the
/// affine foreshortening needed to draw a meaningful pupil-size reticle back
/// in the untouched RAW ROI.
#[derive(Clone, Copy, Debug, PartialEq)]
struct PupilProjectionReference {
    center: (f64, f64),
    fronto_parallel_limbus_radius_px: FrontoParallelCircleRadiusPx,
    equivalent_limbus_radius_px: f64,
    minor_to_major: f64,
    angle: f64,
    source: PupilProjectionSource,
}

impl PupilProjectionReference {
    fn from_axes(
        center: (f64, f64),
        mut major_radius: f64,
        mut minor_radius: f64,
        mut angle: f64,
        source: PupilProjectionSource,
    ) -> Option<Self> {
        if !center.0.is_finite()
            || !center.1.is_finite()
            || !major_radius.is_finite()
            || !minor_radius.is_finite()
            || !angle.is_finite()
            || major_radius <= 4.0
            || minor_radius <= 2.0
        {
            return None;
        }
        if major_radius < minor_radius {
            std::mem::swap(&mut major_radius, &mut minor_radius);
            angle += std::f64::consts::FRAC_PI_2;
        }
        let assessment =
            raw_iris_focus::assess_projected_circular_limbus_axes(major_radius, minor_radius)?;
        if assessment.minor_to_major + 1.0e-12 < assessment.minimum_minor_to_major {
            return None;
        }
        let minor_to_major = assessment.minor_to_major;
        let fronto_parallel_limbus_radius_px =
            FrontoParallelCircleRadiusPx::from_projected_circular_limbus_axes(
                major_radius,
                minor_radius,
            )?;
        Some(Self {
            center,
            fronto_parallel_limbus_radius_px,
            equivalent_limbus_radius_px: (major_radius * minor_radius).sqrt(),
            minor_to_major,
            angle,
            source,
        })
    }

    fn from_outer(
        boundary: &raw_iris_focus::OuterIrisBoundary,
        source: PupilProjectionSource,
    ) -> Option<Self> {
        (!boundary.points.is_empty())
            .then(|| {
                Self::from_axes(
                    boundary.center,
                    boundary.major_radius,
                    boundary.minor_radius,
                    boundary.angle,
                    source,
                )
            })
            .flatten()
    }

    fn from_censored(observation: raw_iris_focus::RoiTruncatedLimbusObservation) -> Option<Self> {
        (observation.confidence >= 0.45)
            .then(|| {
                Self::from_axes(
                    observation.center,
                    observation.major_radius,
                    observation.minor_radius,
                    observation.angle,
                    PupilProjectionSource::CensoredLimbus,
                )
            })
            .flatten()
    }

    fn from_raw_focus(focus: &raw_iris_focus::BorderFocus) -> Option<Self> {
        if !focus.radius.is_finite() || focus.radius <= 4.0 || !focus.axis_angle.is_finite() {
            return None;
        }
        let mut ratio = focus.axis_ratio.abs();
        let mut angle = focus.axis_angle;
        if !ratio.is_finite() || ratio <= 0.0 {
            ratio = 1.0;
        }
        if ratio < 1.0 {
            ratio = 1.0 / ratio;
            angle += std::f64::consts::FRAC_PI_2;
        }
        let ratio_root = ratio.clamp(1.0, 2.5).sqrt();
        Self::from_axes(
            focus.center,
            focus.radius * ratio_root,
            focus.radius / ratio_root,
            angle,
            PupilProjectionSource::RawEyeAnatomy,
        )
    }
}

const PUPIL_CENTER_TRACK_STALE_AFTER: Duration = Duration::from_millis(1_250);
const PUPIL_CENTER_PENDING_RELOCATION_MAX_AGE: Duration = Duration::from_millis(450);
// A tracked fixation ball produces smooth pursuit rather than a sequence of
// stationary fixations.  At the native 10 Hz eye cadence, requiring the
// second remote pupil ring to remain at the first ring's sensor coordinate
// turns real pursuit into a repeated relocation-pending hold.  Two decisive
// RAW rings may instead establish a short-lived canonical velocity when both
// increments are aligned and remain a small fraction of the measured limbus.
// The prediction expires quickly, so a lid/glint edge cannot coast through an
// evidence gap or become a new acquisition mechanism.
const PUPIL_CENTER_PURSUIT_MAX_AGE: Duration = Duration::from_millis(350);
const PUPIL_CENTER_PURSUIT_MIN_CANONICAL_STEP: f64 = 0.004;
const PUPIL_CENTER_PURSUIT_MAX_CANONICAL_STEP: f64 = 0.105;
const PUPIL_CENTER_PURSUIT_MIN_DIRECTION_COSINE: f64 = 0.35;
const PUPIL_CENTER_PURSUIT_MIN_STEP_RATIO: f64 = 0.22;
const PUPIL_CENTER_PURSUIT_MAX_STEP_RATIO: f64 = 4.50;
const PUPIL_CENTER_PURSUIT_MAX_CANONICAL_SPEED_PER_SECOND: f64 = 1.10;
// Without independently classified saccade motion, rough-center/RAW flow may
// repair a lagging pursuit but may not teleport the pupil across half of the
// limbus.  Large genuine saccades retain the separate high-jerk path.
const PUPIL_CENTER_UNSUPPORTED_MAX_CANONICAL_RELOCATION: f64 = 0.24;

/// Motion regime for the shared pupil-center state.  This is deliberately not
/// a constant-velocity filter: a real saccade has large acceleration and jerk,
/// then stops abruptly.  Fixations are therefore transported in the limbus
/// coordinate frame, while a remote current-frame solution is either admitted
/// by independent pupil/iris motion or verified on a second frame.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum PupilCenterMotionRegime {
    #[default]
    Uninitialized,
    Fixation,
    RelocationPending,
    Saccade,
    SmoothPursuit,
}

impl PupilCenterMotionRegime {
    fn label(self) -> &'static str {
        match self {
            Self::Uninitialized => "uninitialized",
            Self::Fixation => "fixation",
            Self::RelocationPending => "relocation-pending",
            Self::Saccade => "saccade",
            Self::SmoothPursuit => "smooth-pursuit",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct PupilCenterPrediction {
    center: (f64, f64),
    transported_track: bool,
    transport_source: PupilCenterTransportSource,
    limbus_transport_disagreement_px: f64,
    pursuit_predicted: bool,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum PupilCenterTransportSource {
    #[default]
    Uninitialized,
    FrameProposal,
    SensorHold,
    GlobalSimilarity,
    LimbusConsensus,
    LimbusOnly,
}

impl PupilCenterTransportSource {
    fn label(self) -> &'static str {
        match self {
            Self::Uninitialized => "uninitialized",
            Self::FrameProposal => "frame-proposal",
            Self::SensorHold => "sensor-hold",
            Self::GlobalSimilarity => "global-similarity",
            Self::LimbusConsensus => "limbus-consensus",
            Self::LimbusOnly => "limbus-only",
        }
    }

    fn short_label(self) -> &'static str {
        match self {
            Self::Uninitialized => "WAIT",
            Self::FrameProposal => "PROPOSAL",
            Self::SensorHold => "SENSOR",
            Self::GlobalSimilarity => "GLOBAL",
            Self::LimbusConsensus => "GLOBAL+LIMBUS",
            Self::LimbusOnly => "LIMBUS",
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct PendingPupilCenterRelocation {
    canonical_center: Option<(f64, f64)>,
    reference_canonical_center: Option<(f64, f64)>,
    sensor_center: (f64, f64),
    agreeing_frames: u8,
    last_seen: Option<Instant>,
    decisive: bool,
    measurement_score: f64,
    proposal_agrees: bool,
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct PupilCenterTrackDiagnostics {
    regime: PupilCenterMotionRegime,
    transport_source: PupilCenterTransportSource,
    predicted_center: Option<(f64, f64)>,
    measured_center: Option<(f64, f64)>,
    published_center: Option<(f64, f64)>,
    limbus_transport_disagreement_px: f64,
    innovation_px: f64,
    fixation_gate_px: f64,
    measurement_score: f64,
    measurement_admissible: bool,
    transported_hold: bool,
    pending_relocation_frames: u8,
    saccade_likelihood: f32,
    relative_motion_confidence: f32,
    relative_speed_px_s: f32,
    relative_acceleration_px_s2: f32,
    relative_jerk_px_s3: f32,
    specular_layer_excluded: bool,
    pursuit_predicted: bool,
    pursuit_velocity_canonical_per_second: Option<(f64, f64)>,
}

#[derive(Default)]
struct PupilCenterStateTracker {
    /// Pupil location in the current physical limbus' fronto-parallel affine
    /// coordinates.  Holding this fixed transports ordinary head/ROI motion
    /// without pretending that the specular pupil interior is rigid.
    canonical_center: Option<(f64, f64)>,
    /// Absolute sensor coordinate is the fallback when the selected limbus is
    /// temporarily withheld.  ROI-buffer and client-crop offsets therefore do
    /// not silently become apparent pupil motion.
    sensor_center: Option<(f64, f64)>,
    last_supported: Option<Instant>,
    fixation_streak: u8,
    pending_relocation: Option<PendingPupilCenterRelocation>,
    pursuit_velocity_canonical_per_second: Option<(f64, f64)>,
    pursuit_supported_at: Option<Instant>,
    last_frame_at: Option<Instant>,
    diagnostics: PupilCenterTrackDiagnostics,
}

fn pupil_projection_canonical_point(
    projection: PupilProjectionReference,
    point: (f64, f64),
) -> Option<(f64, f64)> {
    let major = projection.fronto_parallel_limbus_radius_px.value();
    let minor = major * projection.minor_to_major;
    if !major.is_finite() || !minor.is_finite() || major <= 1.0 || minor <= 1.0 {
        return None;
    }
    let delta = (point.0 - projection.center.0, point.1 - projection.center.1);
    let (sine, cosine) = projection.angle.sin_cos();
    let canonical = (
        (cosine * delta.0 + sine * delta.1) / major,
        (-sine * delta.0 + cosine * delta.1) / minor,
    );
    (canonical.0.is_finite() && canonical.1.is_finite()).then_some(canonical)
}

fn pupil_projection_image_point(
    projection: PupilProjectionReference,
    canonical: (f64, f64),
) -> Option<(f64, f64)> {
    let major = projection.fronto_parallel_limbus_radius_px.value();
    let minor = major * projection.minor_to_major;
    if !major.is_finite()
        || !minor.is_finite()
        || major <= 1.0
        || minor <= 1.0
        || !canonical.0.is_finite()
        || !canonical.1.is_finite()
    {
        return None;
    }
    let local = (canonical.0 * major, canonical.1 * minor);
    let (sine, cosine) = projection.angle.sin_cos();
    Some((
        projection.center.0 + cosine * local.0 - sine * local.1,
        projection.center.1 + sine * local.0 + cosine * local.1,
    ))
}

fn pupil_center_orbital_measurement_admissible(
    measurement: raw_iris_focus::PupilCenterOrbitalFit,
) -> bool {
    measurement.score >= 0.54
        && measurement.ring_transition >= 0.16
        && measurement.ring_coverage >= 0.42
        && measurement.opposing_support >= 0.42
        && measurement.broad_dark_step >= 0.012
        && measurement.broad_dark_support >= 0.58
}

fn pupil_center_orbital_measurement_decisive(
    measurement: raw_iris_focus::PupilCenterOrbitalFit,
) -> bool {
    pupil_center_orbital_measurement_admissible(measurement)
        && measurement.score >= 0.62
        && measurement.ring_coverage >= 0.58
        && measurement.opposing_support >= 0.58
        && measurement.broad_dark_support >= 0.72
}

fn pupil_center_saccade_motion_supported(
    overlay: &raw_motion_octrees::MotionOctreeOverlay,
) -> bool {
    let coupled = overlay.coupled_motion;
    let relative = coupled.green_relative_to_cyan;
    let pupil_layer = overlay.layers[raw_motion_octrees::PUPIL_LAYER];
    let jerk = relative.jerk_px_s3[0].hypot(relative.jerk_px_s3[1]);
    let classified_saccade = coupled.saccade_likelihood >= 0.68;
    let high_jerk_transition = coupled.saccade_likelihood >= 0.34 && jerk >= 650.0;
    relative.samples >= 4
        && relative.confidence >= 0.12
        && pupil_layer.persistent_tracks >= 3
        && pupil_layer.stable_frames >= 2
        && pupil_layer.coherence >= 0.18
        && (classified_saccade || high_jerk_transition)
}

/// A short-history acceleration burst may be real before the cubic motion
/// fit has accumulated enough confidence to authorize an immediate state
/// transition. It may broaden the bounded RAW search, but publication remains
/// behind `pupil_center_saccade_motion_supported` or multi-frame ring
/// confirmation. The reflection layer is absent from every term here.
fn pupil_center_saccade_search_warranted(
    overlay: &raw_motion_octrees::MotionOctreeOverlay,
) -> bool {
    let relative = overlay.coupled_motion.green_relative_to_cyan;
    let pupil_layer = overlay.layers[raw_motion_octrees::PUPIL_LAYER];
    let acceleration = relative.acceleration_px_s2[0].hypot(relative.acceleration_px_s2[1]);
    let jerk = relative.jerk_px_s3[0].hypot(relative.jerk_px_s3[1]);
    relative.samples >= 4
        && relative.confidence >= 0.045
        && pupil_layer.persistent_tracks >= 3
        && pupil_layer.stable_frames >= 2
        && pupil_layer.coherence >= 0.18
        && (overlay.coupled_motion.saccade_likelihood >= 0.22
            || acceleration >= 420.0
            || jerk >= 1_100.0)
}

fn bounded_pupil_pursuit_velocity(
    previous: (f64, f64),
    current: (f64, f64),
    elapsed: Duration,
) -> Option<(f64, f64)> {
    let seconds = elapsed.as_secs_f64();
    if !(0.035..=0.30).contains(&seconds) {
        return None;
    }
    let velocity = (
        (current.0 - previous.0) / seconds,
        (current.1 - previous.1) / seconds,
    );
    let speed = velocity.0.hypot(velocity.1);
    (speed.is_finite()
        && speed > 0.0
        && speed <= PUPIL_CENTER_PURSUIT_MAX_CANONICAL_SPEED_PER_SECOND)
        .then_some(velocity)
}

fn pupil_center_progressive_pursuit_velocity(
    pending: PendingPupilCenterRelocation,
    current_canonical: Option<(f64, f64)>,
    now: Instant,
    current_decisive: bool,
    current_measurement_score: f64,
    current_proposal_agrees: bool,
) -> Option<(f64, f64)> {
    let trace = std::env::var_os("BUTTERCUP_PUPIL_PURSUIT_TRACE").is_some();
    let raw_pair_strong = (pending.decisive && current_measurement_score >= 0.58)
        || (current_decisive && pending.measurement_score >= 0.58)
        || (pending.measurement_score >= 0.62 && current_measurement_score >= 0.62);
    if !raw_pair_strong || !pending.proposal_agrees || !current_proposal_agrees {
        if trace {
            eprintln!(
                "pupil-pursuit reject=raw/proposal prior={:.3}/{} current={:.3}/{} proposal={}/{}",
                pending.measurement_score,
                pending.decisive,
                current_measurement_score,
                current_decisive,
                pending.proposal_agrees,
                current_proposal_agrees,
            );
        }
        return None;
    }
    let reference = pending.reference_canonical_center?;
    let previous = pending.canonical_center?;
    let current = current_canonical?;
    let previous_seen = pending.last_seen?;
    let elapsed = now.saturating_duration_since(previous_seen);
    if elapsed > PUPIL_CENTER_PURSUIT_MAX_AGE {
        return None;
    }
    let first_step = (previous.0 - reference.0, previous.1 - reference.1);
    let second_step = (current.0 - previous.0, current.1 - previous.1);
    let first_length = first_step.0.hypot(first_step.1);
    let second_length = second_step.0.hypot(second_step.1);
    if !(PUPIL_CENTER_PURSUIT_MIN_CANONICAL_STEP..=PUPIL_CENTER_PURSUIT_MAX_CANONICAL_STEP)
        .contains(&first_length)
        || !(PUPIL_CENTER_PURSUIT_MIN_CANONICAL_STEP..=PUPIL_CENTER_PURSUIT_MAX_CANONICAL_STEP)
            .contains(&second_length)
    {
        if trace {
            eprintln!(
                "pupil-pursuit reject=step first={first_length:.5} second={second_length:.5}"
            );
        }
        return None;
    }
    let direction_cosine = (first_step.0 * second_step.0 + first_step.1 * second_step.1)
        / (first_length * second_length);
    let step_ratio = second_length / first_length;
    if direction_cosine < PUPIL_CENTER_PURSUIT_MIN_DIRECTION_COSINE
        || !(PUPIL_CENTER_PURSUIT_MIN_STEP_RATIO..=PUPIL_CENTER_PURSUIT_MAX_STEP_RATIO)
            .contains(&step_ratio)
    {
        if trace {
            eprintln!(
                "pupil-pursuit reject=direction cosine={direction_cosine:.4} ratio={step_ratio:.4} first={first_length:.5} second={second_length:.5}"
            );
        }
        return None;
    }
    let velocity = bounded_pupil_pursuit_velocity(previous, current, elapsed);
    if trace {
        eprintln!(
            "pupil-pursuit {} cosine={direction_cosine:.4} ratio={step_ratio:.4} first={first_length:.5} second={second_length:.5} velocity={velocity:?}",
            if velocity.is_some() {
                "accept"
            } else {
                "reject=speed"
            }
        );
    }
    velocity
}

impl PupilCenterStateTracker {
    fn clear(&mut self) {
        *self = Self::default();
    }

    fn diagnostics(&self) -> PupilCenterTrackDiagnostics {
        self.diagnostics
    }

    fn begin_frame(
        &mut self,
        now: Instant,
        sensor_origin: (u32, u32),
        frame_extent: (usize, usize),
        projection: Option<PupilProjectionReference>,
        frame_proposal: Option<(f64, f64)>,
        motion: &raw_motion_octrees::MotionOctreeOverlay,
    ) -> Option<PupilCenterPrediction> {
        if self.last_supported.is_some_and(|last| {
            now.saturating_duration_since(last) > PUPIL_CENTER_TRACK_STALE_AFTER
        }) {
            self.clear();
        }
        let frame_dt = self
            .last_frame_at
            .map(|previous| now.saturating_duration_since(previous).as_secs_f64())
            .unwrap_or(0.0)
            .clamp(0.0, 0.20);
        self.last_frame_at = Some(now);
        let pursuit_velocity = self.pursuit_velocity_canonical_per_second.filter(|_| {
            self.pursuit_supported_at.is_some_and(|supported| {
                now.saturating_duration_since(supported) <= PUPIL_CENTER_PURSUIT_MAX_AGE
            })
        });
        if pursuit_velocity.is_none() {
            self.pursuit_velocity_canonical_per_second = None;
            self.pursuit_supported_at = None;
        }
        let limbus_hold =
            projection
                .zip(self.canonical_center)
                .and_then(|(projection, canonical)| {
                    pupil_projection_image_point(projection, canonical)
                });
        let limbus_transport = projection
            .zip(self.canonical_center)
            .zip(pursuit_velocity)
            .filter(|_| frame_dt > 0.0)
            .and_then(|((projection, canonical), velocity)| {
                pupil_projection_image_point(
                    projection,
                    (
                        canonical.0 + velocity.0 * frame_dt,
                        canonical.1 + velocity.1 * frame_dt,
                    ),
                )
            })
            .or(limbus_hold);
        let pursuit_delta = limbus_hold
            .zip(limbus_transport)
            .map(|(held, pursued)| (pursued.0 - held.0, pursued.1 - held.1))
            .filter(|delta| delta.0.hypot(delta.1) > 1.0e-6);
        let sensor_hold = self.sensor_center.map(|sensor| {
            (
                sensor.0 - f64::from(sensor_origin.0),
                sensor.1 - f64::from(sensor_origin.1),
            )
        });
        let global_motion = motion.motions[raw_motion_octrees::GENERAL_LAYER];
        let global_layer = motion.layers[raw_motion_octrees::GENERAL_LAYER];
        let global_reliable = global_motion.support >= 4
            && global_layer.persistent_tracks >= 3
            && global_layer.stable_frames >= 2
            && global_layer.coherence >= 0.10
            && global_motion.residual.is_finite()
            && global_motion.residual <= 4.0;
        let global_transport = self
            .sensor_center
            .filter(|_| global_reliable)
            .map(|sensor| {
                // `SimilarityMotion` is fitted in absolute sensor coordinates
                // about the current RAW slice center. Applying the same bounded
                // transform to the persistent pupil state transports head motion
                // without treating iris texture or a reflection as rigid.
                let analysis_center = (
                    f64::from(sensor_origin.0) + frame_extent.0 as f64 * 0.5,
                    f64::from(sensor_origin.1) + frame_extent.1 as f64 * 0.5,
                );
                let x = sensor.0 - analysis_center.0;
                let y = sensor.1 - analysis_center.1;
                (
                    sensor.0
                        + f64::from(global_motion.translation[0])
                        + f64::from(global_motion.scale_delta) * x
                        - f64::from(global_motion.rotation) * y
                        - f64::from(sensor_origin.0),
                    sensor.1
                        + f64::from(global_motion.translation[1])
                        + f64::from(global_motion.rotation) * x
                        + f64::from(global_motion.scale_delta) * y
                        - f64::from(sensor_origin.1),
                )
            });
        let (material_transport, material_source) = if let Some(center) = global_transport {
            (Some(center), PupilCenterTransportSource::GlobalSimilarity)
        } else if let Some(center) = sensor_hold {
            (Some(center), PupilCenterTransportSource::SensorHold)
        } else {
            (None, PupilCenterTransportSource::Uninitialized)
        };
        // Global/sensor transport owns head and ROI motion.  Add only the
        // short-lived limbus-canonical pursuit displacement, keeping those
        // coordinate systems separate instead of treating iris texture as a
        // rigid pupil feature.
        let material_transport = material_transport.map(|center| {
            pursuit_delta.map_or(center, |delta| (center.0 + delta.0, center.1 + delta.1))
        });
        let limbus_disagreement = material_transport
            .zip(limbus_transport)
            .map_or(0.0, |(material, limbus)| {
                (material.0 - limbus.0).hypot(material.1 - limbus.1)
            });
        let limbus_consensus_gate = projection.map_or(3.0, |projection| {
            (projection.fronto_parallel_limbus_radius_px.value() * 0.035).clamp(2.5, 5.0)
        });
        let (transported, transport_source) = match (material_transport, limbus_transport) {
            (Some(material), Some(limbus)) if limbus_disagreement <= limbus_consensus_gate => {
                // Material motion is authoritative. The independently fitted
                // limbus gets a small subpixel refinement only in consensus.
                (
                    Some((
                        0.78 * material.0 + 0.22 * limbus.0,
                        0.78 * material.1 + 0.22 * limbus.1,
                    )),
                    PupilCenterTransportSource::LimbusConsensus,
                )
            }
            (Some(material), _) => (Some(material), material_source),
            (None, Some(limbus)) => (Some(limbus), PupilCenterTransportSource::LimbusOnly),
            (None, None) => (None, PupilCenterTransportSource::Uninitialized),
        };
        let (center, transport_source) = transported
            .map(|center| (center, transport_source))
            .or_else(|| {
                frame_proposal.map(|center| (center, PupilCenterTransportSource::FrameProposal))
            })?;
        if !center.0.is_finite() || !center.1.is_finite() {
            return None;
        }
        let prediction = PupilCenterPrediction {
            center,
            transported_track: transported.is_some(),
            transport_source,
            limbus_transport_disagreement_px: limbus_disagreement,
            pursuit_predicted: pursuit_delta.is_some(),
        };
        self.diagnostics = PupilCenterTrackDiagnostics {
            regime: if prediction.transported_track {
                self.diagnostics.regime
            } else {
                PupilCenterMotionRegime::Uninitialized
            },
            transport_source,
            predicted_center: Some(center),
            limbus_transport_disagreement_px: limbus_disagreement,
            specular_layer_excluded: true,
            pursuit_predicted: prediction.pursuit_predicted,
            pursuit_velocity_canonical_per_second: pursuit_velocity,
            ..PupilCenterTrackDiagnostics::default()
        };
        Some(prediction)
    }

    #[allow(clippy::too_many_arguments)]
    fn assimilate(
        &mut self,
        now: Instant,
        sensor_origin: (u32, u32),
        projection: Option<PupilProjectionReference>,
        prediction: PupilCenterPrediction,
        frame_proposal: Option<(f64, f64)>,
        measurement: Option<raw_iris_focus::PupilCenterOrbitalFit>,
        overlay: &raw_motion_octrees::MotionOctreeOverlay,
    ) -> Option<(f64, f64)> {
        let previous_canonical_center = self.canonical_center;
        let previous_supported_at = self.last_supported;
        let measured = measurement
            .filter(|measurement| pupil_center_orbital_measurement_admissible(*measurement));
        let limbus_radius = projection.map_or(64.0, |projection| {
            projection.fronto_parallel_limbus_radius_px.value()
        });
        let fixation_gate = (limbus_radius * 0.014).clamp(1.25, 2.40);
        let micro_gate = if overlay.coupled_motion.micro_motion_likelihood >= 0.65 {
            fixation_gate * 1.35
        } else {
            fixation_gate
        };
        let relative = overlay.coupled_motion.green_relative_to_cyan;
        let relative_acceleration =
            relative.acceleration_px_s2[0].hypot(relative.acceleration_px_s2[1]);
        let relative_jerk = relative.jerk_px_s3[0].hypot(relative.jerk_px_s3[1]);
        let mut published = prediction.transported_track.then_some(prediction.center);
        let mut regime = if prediction.transported_track {
            if prediction.pursuit_predicted {
                PupilCenterMotionRegime::SmoothPursuit
            } else {
                PupilCenterMotionRegime::Fixation
            }
        } else {
            PupilCenterMotionRegime::Uninitialized
        };
        let mut innovation = 0.0;
        let mut transported_hold = prediction.transported_track;
        let mut confirmed_pursuit_velocity = None;

        if let Some(measurement) = measured {
            innovation = (measurement.center.0 - prediction.center.0)
                .hypot(measurement.center.1 - prediction.center.1);
            if !prediction.transported_track {
                published = Some(measurement.center);
                self.pending_relocation = None;
                self.fixation_streak = 1;
                regime = PupilCenterMotionRegime::Fixation;
                transported_hold = false;
            } else if innovation <= micro_gate {
                // A fixation measurement may converge below the integer pixel
                // grid, but one noisy meridian cannot move the state by more
                // than the physical fixation gate in a single frame.
                let gain = (0.42 + 0.38 * measurement.score).clamp(0.50, 0.78);
                let requested = (
                    (measurement.center.0 - prediction.center.0) * gain,
                    (measurement.center.1 - prediction.center.1) * gain,
                );
                let requested_length = requested.0.hypot(requested.1);
                let scale = if requested_length > fixation_gate {
                    fixation_gate / requested_length
                } else {
                    1.0
                };
                published = Some((
                    prediction.center.0 + requested.0 * scale,
                    prediction.center.1 + requested.1 * scale,
                ));
                self.pending_relocation = None;
                self.fixation_streak = self.fixation_streak.saturating_add(1);
                regime = if prediction.pursuit_predicted {
                    PupilCenterMotionRegime::SmoothPursuit
                } else if self.diagnostics.regime == PupilCenterMotionRegime::Saccade
                    && self.fixation_streak < 2
                {
                    PupilCenterMotionRegime::Saccade
                } else {
                    PupilCenterMotionRegime::Fixation
                };
                transported_hold = false;
            } else {
                let saccade_motion = pupil_center_saccade_motion_supported(overlay);
                // The independently produced rough center is usually close
                // even though it is not accurate enough to publish directly.
                // A remote ring beyond this anatomical acquisition corridor
                // is more likely an iris fibre/lid alias than a pupil.
                let proposal_agreement_gate = (limbus_radius * 0.11).clamp(6.0, 13.0);
                let proposal_agrees = frame_proposal.is_some_and(|proposal| {
                    (proposal.0 - measurement.center.0).hypot(proposal.1 - measurement.center.1)
                        <= proposal_agreement_gate
                });
                let immediate_saccade = saccade_motion
                    && proposal_agrees
                    && pupil_center_orbital_measurement_decisive(measurement);
                let measured_canonical = projection.and_then(|projection| {
                    pupil_projection_canonical_point(projection, measurement.center)
                });
                let progressive_pursuit_velocity = self.pending_relocation.and_then(|pending| {
                    pupil_center_progressive_pursuit_velocity(
                        pending,
                        measured_canonical,
                        now,
                        pupil_center_orbital_measurement_decisive(measurement),
                        measurement.score,
                        proposal_agrees,
                    )
                });
                if immediate_saccade {
                    published = Some(measurement.center);
                    self.pending_relocation = None;
                    self.pursuit_velocity_canonical_per_second = None;
                    self.pursuit_supported_at = None;
                    self.fixation_streak = 0;
                    regime = PupilCenterMotionRegime::Saccade;
                    transported_hold = false;
                } else if let Some(velocity) = progressive_pursuit_velocity {
                    published = Some(measurement.center);
                    self.pending_relocation = None;
                    self.fixation_streak = 0;
                    confirmed_pursuit_velocity = Some(velocity);
                    regime = PupilCenterMotionRegime::SmoothPursuit;
                    transported_hold = false;
                } else {
                    let measured_sensor = (
                        measurement.center.0 + f64::from(sensor_origin.0),
                        measurement.center.1 + f64::from(sensor_origin.1),
                    );
                    // Without already-supported saccade kinematics, temporal
                    // persistence means the same physical ring, not merely
                    // two vaguely nearby dark structures. A real continuing
                    // saccade takes the independent motion-authorized path.
                    let pending_agreement_gate = (limbus_radius * 0.042).clamp(3.0, 5.5);
                    let pending_same_ring = self.pending_relocation.is_some_and(|pending| {
                        if pending.last_seen.is_some_and(|last| {
                            now.saturating_duration_since(last)
                                > PUPIL_CENTER_PENDING_RELOCATION_MAX_AGE
                        }) {
                            return false;
                        }
                        match (pending.canonical_center, measured_canonical, projection) {
                            (Some(previous), Some(_), Some(projection)) => {
                                pupil_projection_image_point(projection, previous).is_some_and(
                                    |previous_image| {
                                        (previous_image.0 - measurement.center.0)
                                            .hypot(previous_image.1 - measurement.center.1)
                                            <= pending_agreement_gate
                                    },
                                )
                            }
                            _ => {
                                (pending.sensor_center.0 - measured_sensor.0)
                                    .hypot(pending.sensor_center.1 - measured_sensor.1)
                                    <= pending_agreement_gate
                            }
                        }
                    });
                    let bounded_canonical_relocation =
                        self.pending_relocation.is_some_and(|pending| {
                            pending
                                .reference_canonical_center
                                .zip(measured_canonical)
                                .is_some_and(|(reference, current)| {
                                    (current.0 - reference.0).hypot(current.1 - reference.1)
                                        <= PUPIL_CENTER_UNSUPPORTED_MAX_CANONICAL_RELOCATION
                                })
                        });
                    // The decoded fixation capture showed that agreement
                    // between two proposal-local paths is not independent:
                    // both can ride the same coherent iris texture.  Only
                    // persistence of the actual RAW ring may advance this
                    // no-saccade relocation counter.  Smooth pursuit retains
                    // its separate three-position, direction/step-ratio test
                    // above; classified high-jerk motion retains the immediate
                    // saccade path.
                    let pending_agrees = pending_same_ring;
                    let agreeing_frames = if pending_agrees {
                        self.pending_relocation
                            .map_or(1, |pending| pending.agreeing_frames.saturating_add(1))
                    } else {
                        1
                    };
                    self.pending_relocation = Some(PendingPupilCenterRelocation {
                        canonical_center: measured_canonical,
                        reference_canonical_center: self.canonical_center,
                        sensor_center: measured_sensor,
                        agreeing_frames,
                        last_seen: Some(now),
                        decisive: pupil_center_orbital_measurement_decisive(measurement),
                        measurement_score: measurement.score,
                        proposal_agrees,
                    });
                    let decisive_confirmation = agreeing_frames >= 2
                        && proposal_agrees
                        && bounded_canonical_relocation
                        && pupil_center_orbital_measurement_decisive(measurement);
                    if decisive_confirmation {
                        published = Some(measurement.center);
                        self.pending_relocation = None;
                        self.pursuit_velocity_canonical_per_second = None;
                        self.pursuit_supported_at = None;
                        self.fixation_streak = 0;
                        regime = PupilCenterMotionRegime::Saccade;
                        transported_hold = false;
                    } else {
                        regime = PupilCenterMotionRegime::RelocationPending;
                    }
                }
            }
        } else if !prediction.transported_track {
            // A proposal is an acquisition coordinate, not state. Do not let
            // an unverified dark basin become the temporal center merely
            // because no better measurement was available this frame.
            published = None;
        }

        if let Some(center) = published {
            self.sensor_center = Some((
                center.0 + f64::from(sensor_origin.0),
                center.1 + f64::from(sensor_origin.1),
            ));
            let next_canonical = projection
                .and_then(|projection| pupil_projection_canonical_point(projection, center));
            if regime == PupilCenterMotionRegime::SmoothPursuit {
                let observed_velocity = confirmed_pursuit_velocity.or_else(|| {
                    previous_canonical_center
                        .zip(next_canonical)
                        .zip(previous_supported_at)
                        .and_then(|((previous, current), previous_at)| {
                            bounded_pupil_pursuit_velocity(
                                previous,
                                current,
                                now.saturating_duration_since(previous_at),
                            )
                        })
                });
                if let Some(observed) = observed_velocity {
                    let filtered =
                        self.pursuit_velocity_canonical_per_second
                            .map_or(observed, |previous| {
                                (
                                    0.35 * previous.0 + 0.65 * observed.0,
                                    0.35 * previous.1 + 0.65 * observed.1,
                                )
                            });
                    self.pursuit_velocity_canonical_per_second = Some(filtered);
                    self.pursuit_supported_at = Some(now);
                }
            } else if matches!(
                regime,
                PupilCenterMotionRegime::Fixation
                    | PupilCenterMotionRegime::Saccade
                    | PupilCenterMotionRegime::Uninitialized
            ) {
                self.pursuit_velocity_canonical_per_second = None;
                self.pursuit_supported_at = None;
            }
            if let Some(projection) = projection {
                self.canonical_center = pupil_projection_canonical_point(projection, center);
            }
            if !transported_hold {
                self.last_supported = Some(now);
            }
        }
        self.diagnostics = PupilCenterTrackDiagnostics {
            regime,
            transport_source: prediction.transport_source,
            predicted_center: Some(prediction.center),
            measured_center: measured.map(|measurement| measurement.center),
            published_center: published,
            limbus_transport_disagreement_px: prediction.limbus_transport_disagreement_px,
            innovation_px: innovation,
            fixation_gate_px: fixation_gate,
            measurement_score: measurement.map_or(0.0, |measurement| measurement.score),
            measurement_admissible: measured.is_some(),
            transported_hold,
            pending_relocation_frames: self
                .pending_relocation
                .map_or(0, |pending| pending.agreeing_frames),
            saccade_likelihood: overlay.coupled_motion.saccade_likelihood,
            relative_motion_confidence: relative.confidence,
            relative_speed_px_s: relative.speed_px_s,
            relative_acceleration_px_s2: relative_acceleration,
            relative_jerk_px_s3: relative_jerk,
            specular_layer_excluded: true,
            pursuit_predicted: prediction.pursuit_predicted,
            pursuit_velocity_canonical_per_second: self.pursuit_velocity_canonical_per_second,
        };
        published
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum PupilSizeSupportSource {
    #[default]
    LimbusFractionThresholds,
    TemporalPupilRatio,
}

impl PupilSizeSupportSource {
    fn label(self) -> &'static str {
        match self {
            Self::LimbusFractionThresholds => "limbus-fraction",
            Self::TemporalPupilRatio => "temporal-pupil-ratio",
        }
    }
}

/// Quarter-octave bucket of the fronto-parallel limbus radius. This is an
/// image-resolution coordinate, not an anatomical pupil-size estimate.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct FrontoParallelScaleBucket(u8);

impl FrontoParallelScaleBucket {
    fn from_radius(radius_px: f64) -> Option<Self> {
        if !radius_px.is_finite() || radius_px <= 0.0 {
            return None;
        }
        let logarithmic = (radius_px / PUPIL_EVIDENCE_SCALE_BASE_RADIUS_PX).log2()
            * PUPIL_EVIDENCE_SCALE_BUCKETS_PER_OCTAVE;
        let index = logarithmic
            .floor()
            .clamp(0.0, (PUPIL_EVIDENCE_SCALE_BUCKETS - 1) as f64) as u8;
        Some(Self(index))
    }

    fn index(self) -> usize {
        self.0 as usize
    }

    fn lower_radius_px(self) -> f64 {
        PUPIL_EVIDENCE_SCALE_BASE_RADIUS_PX
            * 2.0f64.powf(self.0 as f64 / PUPIL_EVIDENCE_SCALE_BUCKETS_PER_OCTAVE)
    }

    fn upper_radius_px(self) -> f64 {
        PUPIL_EVIDENCE_SCALE_BASE_RADIUS_PX
            * 2.0f64.powf((self.0 as f64 + 1.0) / PUPIL_EVIDENCE_SCALE_BUCKETS_PER_OCTAVE)
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum OpticalFocusClass {
    #[default]
    Unknown,
    Soft,
    Usable,
    Sharp,
}

impl OpticalFocusClass {
    fn label(self) -> &'static str {
        match self {
            Self::Unknown => "unknown",
            Self::Soft => "soft",
            Self::Usable => "usable",
            Self::Sharp => "sharp",
        }
    }
}

/// Independent coordinates which determine how much authority current-frame
/// pupil cues receive. Apparent scale controls spatial resolvability; optical
/// focus controls edge/color reliability. Neither one changes the physical
/// pupil/limbus ratio being estimated.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct PupilEvidenceCondition {
    scale_bucket: Option<FrontoParallelScaleBucket>,
    limbus_fronto_parallel_radius_px: Option<f64>,
    expected_projected_pupil_radius_px: Option<f64>,
    limbus_optical_sharpness: Option<f64>,
    limbus_focus_reference: Option<f64>,
    relative_focus: Option<f64>,
    focus_measurement_confidence: f64,
    spatial_resolution: f64,
    cue_reliability: f64,
    focus_verified: bool,
    focus_class: OpticalFocusClass,
}

impl PupilEvidenceCondition {
    fn fully_reliable(scale_radius_px: f64) -> Self {
        let scale_bucket = FrontoParallelScaleBucket::from_radius(scale_radius_px);
        Self {
            scale_bucket,
            limbus_fronto_parallel_radius_px: Some(scale_radius_px),
            expected_projected_pupil_radius_px: Some(scale_radius_px * 0.40),
            limbus_optical_sharpness: Some(1.0),
            limbus_focus_reference: Some(1.0),
            relative_focus: Some(1.0),
            focus_measurement_confidence: 1.0,
            spatial_resolution: 1.0,
            cue_reliability: 1.0,
            focus_verified: true,
            focus_class: OpticalFocusClass::Sharp,
        }
    }

    fn raw_solver_condition(self) -> raw_iris_focus::InnerIrisEvidenceCondition {
        raw_iris_focus::InnerIrisEvidenceCondition::new(self.cue_reliability)
    }

    fn projected_boundary_radius_px(boundary: &raw_iris_focus::InnerIrisBoundary) -> Option<f64> {
        let major = boundary.major_radius;
        let minor = boundary.minor_radius;
        if major.is_finite() && minor.is_finite() && major > 0.0 && minor > 0.0 {
            Some((major * minor).sqrt())
        } else if boundary.radius.is_finite() && boundary.radius > 0.0 {
            Some(boundary.radius)
        } else {
            None
        }
    }

    fn permits_posterior_training(self, boundary: &raw_iris_focus::InnerIrisBoundary) -> bool {
        self.focus_verified
            && self.scale_bucket.is_some()
            && self.limbus_optical_sharpness.is_some_and(|sharpness| {
                sharpness.is_finite() && sharpness >= PUPIL_EVIDENCE_MIN_TRAINING_ABSOLUTE_SHARPNESS
            })
            && self.relative_focus.is_some_and(|ratio| {
                ratio.is_finite() && ratio >= PUPIL_EVIDENCE_MIN_TRAINING_FOCUS_RATIO
            })
            && self.focus_measurement_confidence >= 0.25
            && Self::projected_boundary_radius_px(boundary)
                .is_some_and(|radius| radius >= PUPIL_EVIDENCE_MIN_TRAINING_PROJECTED_RADIUS_PX)
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct ScaleConditionedFocusReference {
    smoothed_sharpness: f64,
    sharp_reference: f64,
    observations: u32,
    last_observation: Option<Instant>,
}

#[derive(Default)]
struct PupilEvidenceConditionTracker {
    focus_by_scale: [ScaleConditionedFocusReference; PUPIL_EVIDENCE_SCALE_BUCKETS],
}

fn smooth_unit_interval(value: f64, lower: f64, upper: f64) -> f64 {
    if !value.is_finite() || upper <= lower {
        return 0.0;
    }
    let unit = ((value - lower) / (upper - lower)).clamp(0.0, 1.0);
    unit * unit * (3.0 - 2.0 * unit)
}

impl PupilEvidenceConditionTracker {
    fn observe(
        &mut self,
        now: Instant,
        geometry: Option<PupilSizeGeometry>,
        optical_focus: raw_iris_focus::LimbusOpticalFocus,
        focus_verified: bool,
    ) -> PupilEvidenceCondition {
        let scale_radius =
            geometry.map(|value| value.reference_limbus_fronto_parallel_radius_px.value());
        let scale_bucket = scale_radius.and_then(FrontoParallelScaleBucket::from_radius);
        let expected_projected_pupil_radius = geometry.map(|value| {
            // Radius uncertainty is multiplicative, and the learned posterior
            // itself lives in log-ratio space. Before temporal evidence is
            // warm, use the geometric (log-space) center of the operator's
            // broad hard interval. An arithmetic midpoint would assume a
            // conspicuously large pupil and over-trust fixed-pixel detail on
            // a genuinely small pupil.
            let fronto_parallel = value
                .estimated_fronto_parallel_radius_px
                .unwrap_or_else(|| {
                    (value.lower_fronto_parallel_radius_px * value.upper_fronto_parallel_radius_px)
                        .sqrt()
                });
            fronto_parallel
                * value
                    .projection_minor_to_major
                    .clamp(
                        raw_iris_focus::PROVISIONAL_CENTRAL_CAMERA_LIMBUS_ENVELOPE
                            .absolute_minimum_minor_to_major,
                        1.0,
                    )
                    .sqrt()
        });
        let spatial_resolution = expected_projected_pupil_radius
            .map_or(0.0, |radius| smooth_unit_interval(radius, 8.0, 20.0));
        let measured_sharpness = (optical_focus.support >= PUPIL_EVIDENCE_MIN_FOCUS_SUPPORT
            && optical_focus.sharpness.is_finite()
            && optical_focus.sharpness > 0.0)
            .then_some(optical_focus.sharpness);
        let support_confidence = smooth_unit_interval(optical_focus.support as f64, 5.0, 20.0);
        let contrast_confidence = smooth_unit_interval(optical_focus.contrast_raw10, 4.0, 36.0);
        let focus_measurement_confidence = (support_confidence * contrast_confidence).sqrt();

        let mut reference = None;
        let mut relative_focus = None;
        if let (Some(bucket), Some(sharpness)) = (scale_bucket, measured_sharpness) {
            let state = &mut self.focus_by_scale[bucket.index()];
            if focus_verified && focus_measurement_confidence >= 0.20 {
                if state.observations == 0 {
                    state.smoothed_sharpness = sharpness;
                    state.sharp_reference = sharpness;
                } else {
                    state.smoothed_sharpness = 0.72 * state.smoothed_sharpness + 0.28 * sharpness;
                    if state.smoothed_sharpness > state.sharp_reference {
                        // A newly resolved edge raises the reference
                        // deliberately, but one anomalous frame cannot replace
                        // it outright.
                        state.sharp_reference =
                            0.75 * state.sharp_reference + 0.25 * state.smoothed_sharpness;
                    } else {
                        // Subject/lighting changes may lower the attainable
                        // concentration over minutes. Defocus over a few
                        // frames must not teach itself as the new "sharp".
                        let elapsed = state.last_observation.map_or(0.0, |last| {
                            now.saturating_duration_since(last).as_secs_f64()
                        });
                        let downward_alpha = (elapsed * 0.0005).clamp(0.0, 0.01);
                        state.sharp_reference = state.sharp_reference * (1.0 - downward_alpha)
                            + state.smoothed_sharpness * downward_alpha;
                    }
                }
                state.observations = state.observations.saturating_add(1);
                state.last_observation = Some(now);
            }
            if state.observations > 0 && state.sharp_reference > f64::EPSILON {
                reference = Some(state.sharp_reference);
                // Condition this frame from this frame's edge concentration.
                // The EMA exists only to evolve the long-lived sharp
                // reference; using it here would leave several blurry frames
                // at full detail authority after a sudden focus loss.
                relative_focus = Some((sharpness / state.sharp_reference).clamp(0.0, 1.25));
            }
        }

        let absolute_focus =
            measured_sharpness.map_or(0.0, |sharpness| smooth_unit_interval(sharpness, 0.04, 0.28));
        let focus_reliability = relative_focus.map_or(0.55 * absolute_focus, |relative| {
            (0.72 * relative.clamp(0.0, 1.0) + 0.28 * absolute_focus).clamp(0.0, 1.0)
        });
        let cue_reliability =
            (spatial_resolution * focus_measurement_confidence * focus_reliability)
                .sqrt()
                .clamp(0.0, 1.0);
        let focus_class = if measured_sharpness.is_none() || relative_focus.is_none() {
            OpticalFocusClass::Unknown
        } else if measured_sharpness.unwrap() < PUPIL_EVIDENCE_MIN_TRAINING_ABSOLUTE_SHARPNESS {
            OpticalFocusClass::Soft
        } else if relative_focus.unwrap() < PUPIL_EVIDENCE_MIN_TRAINING_FOCUS_RATIO {
            OpticalFocusClass::Soft
        } else if relative_focus.unwrap() < 0.82 {
            OpticalFocusClass::Usable
        } else {
            OpticalFocusClass::Sharp
        };

        PupilEvidenceCondition {
            scale_bucket,
            limbus_fronto_parallel_radius_px: scale_radius,
            expected_projected_pupil_radius_px: expected_projected_pupil_radius,
            limbus_optical_sharpness: measured_sharpness,
            limbus_focus_reference: reference,
            relative_focus,
            focus_measurement_confidence,
            spatial_resolution,
            cue_reliability,
            focus_verified,
            focus_class,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct PupilSizeReticle {
    center: (f64, f64),
    /// Center of the current affine limbus projection selected independently
    /// of Y. This remains distinct from the Y-owned rough/search center above.
    projection_center: (f64, f64),
    lower_fronto_parallel_radius_px: f64,
    upper_fronto_parallel_radius_px: f64,
    preferred_lower_fronto_parallel_radius_px: Option<f64>,
    preferred_upper_fronto_parallel_radius_px: Option<f64>,
    estimated_fronto_parallel_radius_px: Option<f64>,
    reference_limbus_fronto_parallel_radius_px: FrontoParallelCircleRadiusPx,
    projection_minor_to_major: f64,
    projection_angle: f64,
    projection_source: PupilProjectionSource,
    support_source: PupilSizeSupportSource,
    scale_bucket: FrontoParallelScaleBucket,
    temporal_scale_matched: bool,
    temporal_observations: usize,
    temporal_fractional_half_width: Option<f64>,
    recomputed_this_frame: bool,
    frozen: bool,
}

/// Presentation-only projection of the admissible fronto-parallel
/// iris/limbus radius support. The bounds live in de-affined circle space;
/// this reticle maps them back through the current limbus projection without
/// altering the untouched RAW ROI or feeding any rendered guide into a
/// detector.
#[derive(Clone, Copy, Debug, PartialEq)]
struct IrisRadiusReticle {
    center: (f64, f64),
    minimum_fronto_parallel_radius_px: f64,
    maximum_fronto_parallel_radius_px: f64,
    estimated_fronto_parallel_radius_px: f64,
    projection_minor_to_major: f64,
    projection_angle: f64,
    nominal_cold_start: bool,
}

/// Presentation-only pupil radius guides. Unlike `PupilSizeReticle`, this
/// contains no detector ownership or temporal-admission fields, so a static
/// manual-alignment guide can be derived from valid limbus scale support even
/// while the selected rough pupil-center mechanism has no current prediction.
#[derive(Clone, Copy, Debug, PartialEq)]
struct PupilRadiusReticle {
    center: (f64, f64),
    lower_fronto_parallel_radius_px: f64,
    upper_fronto_parallel_radius_px: f64,
    estimated_fronto_parallel_radius_px: Option<f64>,
    projection_minor_to_major: f64,
    projection_angle: f64,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum SizeReticleMode {
    #[default]
    Off,
    /// Hold the presentation center at the exact native RAW ROI center so the
    /// operator can physically align the eye. The current affine axis ratio
    /// and angle remain visible when available; neither guide feeds a solver.
    StaticCentered,
    /// Follow the selected current-frame pupil/limbus projection centers.
    ProjectedFollow,
}

impl SizeReticleMode {
    fn cycled(self) -> Self {
        match self {
            Self::Off => Self::StaticCentered,
            Self::StaticCentered => Self::ProjectedFollow,
            Self::ProjectedFollow => Self::Off,
        }
    }

    fn enabled(self) -> bool {
        self != Self::Off
    }

    fn label(self) -> &'static str {
        match self {
            Self::Off => "off",
            Self::StaticCentered => "static-centered",
            Self::ProjectedFollow => "projected-follow",
        }
    }

    fn screen_label(self) -> &'static str {
        match self {
            Self::Off => "OFF",
            Self::StaticCentered => "STATIC-CENTER",
            Self::ProjectedFollow => "PROJECTED-FOLLOW",
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct PupilSizeRuntimeStatus {
    rough_center_available: bool,
    inner_boundary_locked: bool,
    observed_fronto_parallel_radius_px: Option<f64>,
    observation_confidence: f64,
    observation_rate_limited: bool,
    observation_focus_size_qualified: bool,
    observation_limbus_geometry_qualified: bool,
    observation_raw_diameter_qualified: bool,
    observation_trajectory_updated: bool,
    observation_trained_posterior: bool,
    evidence_condition: PupilEvidenceCondition,
    support: Option<PupilSizeReticle>,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PupilSizeObservationAdmission {
    rate_limited: bool,
    focus_size_qualified: bool,
    limbus_geometry_qualified: bool,
    raw_diameter_qualified: bool,
    trajectory_updated: bool,
    trained_posterior: bool,
}

impl PupilSizeObservationAdmission {
    fn current_boundary_publishable(self) -> bool {
        self.focus_size_qualified && self.limbus_geometry_qualified && self.raw_diameter_qualified
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct PupilSizeGeometry {
    projection_center: (f64, f64),
    lower_fronto_parallel_radius_px: f64,
    upper_fronto_parallel_radius_px: f64,
    preferred_lower_fronto_parallel_radius_px: Option<f64>,
    preferred_upper_fronto_parallel_radius_px: Option<f64>,
    estimated_fronto_parallel_radius_px: Option<f64>,
    reference_limbus_fronto_parallel_radius_px: FrontoParallelCircleRadiusPx,
    projection_minor_to_major: f64,
    projection_angle: f64,
    projection_source: PupilProjectionSource,
    support_source: PupilSizeSupportSource,
    scale_bucket: FrontoParallelScaleBucket,
    temporal_scale_matched: bool,
    temporal_observations: usize,
    temporal_fractional_half_width: Option<f64>,
}

struct PupilSizeTracker {
    /// Robust history of the physical pupil/limbus radius ratio. Both radii
    /// are measured after fronto-parallel rectification, so gross image-scale
    /// changes cancel without coupling this state to MediaPipe or a specific
    /// outer-iris detector.
    strong_log_ratios: VecDeque<f64>,
    last_strong_observation: Option<Instant>,
    scale_log_ratios: [VecDeque<f64>; PUPIL_EVIDENCE_SCALE_BUCKETS],
    scale_last_strong_observation: [Option<Instant>; PUPIL_EVIDENCE_SCALE_BUCKETS],
    cached_geometry: Option<PupilSizeGeometry>,
}

impl Default for PupilSizeTracker {
    fn default() -> Self {
        Self {
            strong_log_ratios: VecDeque::new(),
            last_strong_observation: None,
            scale_log_ratios: std::array::from_fn(|_| VecDeque::new()),
            scale_last_strong_observation: [None; PUPIL_EVIDENCE_SCALE_BUCKETS],
            cached_geometry: None,
        }
    }
}

fn pupil_size_median(mut values: Vec<f64>) -> Option<f64> {
    values.retain(|value| value.is_finite());
    if values.is_empty() {
        return None;
    }
    values.sort_by(f64::total_cmp);
    let middle = values.len() / 2;
    Some(if values.len() % 2 == 0 {
        0.5 * (values[middle - 1] + values[middle])
    } else {
        values[middle]
    })
}

fn pupil_temporal_geometry(
    reference_radius: f64,
    hard_lower: f64,
    hard_upper: f64,
    temporal: Option<(f64, f64)>,
) -> (
    Option<f64>,
    Option<f64>,
    Option<f64>,
    PupilSizeSupportSource,
    Option<f64>,
) {
    let Some((ratio, half_width)) = temporal else {
        return (
            None,
            None,
            None,
            PupilSizeSupportSource::LimbusFractionThresholds,
            None,
        );
    };
    let estimate = reference_radius * ratio;
    if !estimate.is_finite() || !half_width.is_finite() {
        return (
            None,
            None,
            None,
            PupilSizeSupportSource::LimbusFractionThresholds,
            None,
        );
    }
    let preferred_lower = hard_lower.max(estimate * (1.0 - half_width));
    let preferred_upper = hard_upper.min(estimate * (1.0 + half_width));
    if preferred_lower.is_finite()
        && preferred_upper.is_finite()
        && preferred_upper > preferred_lower + 0.5
    {
        (
            Some(preferred_lower),
            Some(preferred_upper),
            Some(estimate),
            PupilSizeSupportSource::TemporalPupilRatio,
            Some(half_width),
        )
    } else {
        // Keep drawing/reporting the posterior estimate when the operator's
        // hard interval excludes it, but do not let it steer the search.
        (
            None,
            None,
            Some(estimate),
            PupilSizeSupportSource::LimbusFractionThresholds,
            Some(half_width),
        )
    }
}

impl PupilSizeTracker {
    fn active_geometry(&self) -> Option<PupilSizeGeometry> {
        self.cached_geometry
    }

    fn robust_temporal_ratio_support(
        samples: &VecDeque<f64>,
        last_observation: Option<Instant>,
        now: Instant,
    ) -> Option<(f64, f64)> {
        if samples.len() < PUPIL_SIZE_TEMPORAL_MIN_OBSERVATIONS {
            return None;
        }
        let center = pupil_size_median(samples.iter().copied().collect())?;
        let mad = pupil_size_median(
            samples
                .iter()
                .map(|sample| (sample - center).abs())
                .collect(),
        )?;
        let observations = samples.len() as f64;
        // Three agreeing native boundaries are enough to prune a grossly
        // different radial branch, but not enough to claim sub-pixel size.
        // Converge from about six percent at N=3 to the five-percent floor;
        // the previous 8-11% interval still admitted conspicuous alternate
        // lid/glasses solutions before the physiological limiter could act.
        let sampling_half_width = 0.035 + 0.045 / observations.sqrt();
        let residual_half_width = (2.8 * mad).exp() - 1.0;
        let stale_half_width = last_observation.map_or(0.0, |last| {
            now.saturating_duration_since(last).as_secs_f64()
                * PUPIL_SIZE_STALE_EXPANSION_PER_SECOND
        });
        let fractional_half_width = sampling_half_width
            .max(residual_half_width)
            .max(stale_half_width)
            .clamp(
                PUPIL_SIZE_MIN_TEMPORAL_HALF_WIDTH,
                PUPIL_SIZE_MAX_TEMPORAL_HALF_WIDTH,
            );
        Some((center.exp(), fractional_half_width))
    }

    fn temporal_ratio_support(
        &self,
        now: Instant,
        scale_bucket: FrontoParallelScaleBucket,
    ) -> (Option<(f64, f64)>, usize, bool) {
        let index = scale_bucket.index();
        let scale_samples = &self.scale_log_ratios[index];
        if let Some(support) = Self::robust_temporal_ratio_support(
            scale_samples,
            self.scale_last_strong_observation[index],
            now,
        ) {
            return (Some(support), scale_samples.len(), true);
        }
        (
            Self::robust_temporal_ratio_support(
                &self.strong_log_ratios,
                self.last_strong_observation,
                now,
            ),
            self.strong_log_ratios.len(),
            false,
        )
    }

    fn begin_frame(
        &mut self,
        now: Instant,
        center: Option<(f64, f64)>,
        projection: Option<PupilProjectionReference>,
        recompute: bool,
        lower_fraction: f64,
        upper_fraction: f64,
    ) -> Option<PupilSizeReticle> {
        // Affine limbus projection geometry remains current even while the
        // selected Y mechanism temporarily has no center. Center availability
        // controls only whether a reticle/search support can be emitted below.
        let center = center.filter(|value| value.0.is_finite() && value.1.is_finite());
        let mut recomputed_this_frame = false;
        if recompute {
            if let Some(projection) = projection {
                let reference = projection.fronto_parallel_limbus_radius_px;
                let reference_px = reference.value();
                if let Some(scale_bucket) = FrontoParallelScaleBucket::from_radius(reference_px) {
                    let hard_lower = reference_px * lower_fraction.clamp(0.01, 0.90);
                    let hard_upper = reference_px * upper_fraction.clamp(0.02, 0.95);
                    let (temporal_support, temporal_observations, temporal_scale_matched) =
                        self.temporal_ratio_support(now, scale_bucket);
                    let (
                        preferred_lower,
                        preferred_upper,
                        estimate,
                        support_source,
                        temporal_half_width,
                    ) = pupil_temporal_geometry(
                        reference_px,
                        hard_lower,
                        hard_upper,
                        temporal_support,
                    );
                    if hard_lower.is_finite() && hard_upper.is_finite() && hard_upper > hard_lower {
                        self.cached_geometry = Some(PupilSizeGeometry {
                            projection_center: projection.center,
                            lower_fronto_parallel_radius_px: hard_lower,
                            upper_fronto_parallel_radius_px: hard_upper,
                            preferred_lower_fronto_parallel_radius_px: preferred_lower,
                            preferred_upper_fronto_parallel_radius_px: preferred_upper,
                            estimated_fronto_parallel_radius_px: estimate,
                            reference_limbus_fronto_parallel_radius_px: reference,
                            projection_minor_to_major: projection.minor_to_major,
                            projection_angle: projection.angle,
                            projection_source: projection.source,
                            support_source,
                            scale_bucket,
                            temporal_scale_matched,
                            temporal_observations,
                            temporal_fractional_half_width: temporal_half_width,
                        });
                        recomputed_this_frame = true;
                    }
                }
            }
        } else if let Some(mut geometry) = self.cached_geometry {
            // R freezes automatic transport from new limbus fits, not an
            // explicit operator adjustment. Move the hard guides immediately
            // against the last frozen reference when a threshold key changes.
            let reference = geometry.reference_limbus_fronto_parallel_radius_px;
            let reference_px = reference.value();
            let hard_lower = reference_px * lower_fraction.clamp(0.01, 0.90);
            let hard_upper = reference_px * upper_fraction.clamp(0.02, 0.95);
            if hard_lower.is_finite()
                && hard_upper.is_finite()
                && hard_upper > hard_lower
                && ((hard_lower - geometry.lower_fronto_parallel_radius_px).abs() > f64::EPSILON
                    || (hard_upper - geometry.upper_fronto_parallel_radius_px).abs() > f64::EPSILON)
            {
                let frozen_temporal = geometry
                    .estimated_fronto_parallel_radius_px
                    .zip(geometry.temporal_fractional_half_width)
                    .map(|(estimate, half_width)| (estimate / reference_px, half_width));
                let (
                    preferred_lower,
                    preferred_upper,
                    estimate,
                    support_source,
                    temporal_half_width,
                ) = pupil_temporal_geometry(reference_px, hard_lower, hard_upper, frozen_temporal);
                geometry.lower_fronto_parallel_radius_px = hard_lower;
                geometry.upper_fronto_parallel_radius_px = hard_upper;
                geometry.preferred_lower_fronto_parallel_radius_px = preferred_lower;
                geometry.preferred_upper_fronto_parallel_radius_px = preferred_upper;
                geometry.estimated_fronto_parallel_radius_px = estimate;
                geometry.support_source = support_source;
                geometry.temporal_fractional_half_width = temporal_half_width;
                self.cached_geometry = Some(geometry);
            }
        }
        let geometry = self.cached_geometry?;
        let center = center?;
        Some(PupilSizeReticle {
            center,
            projection_center: geometry.projection_center,
            lower_fronto_parallel_radius_px: geometry.lower_fronto_parallel_radius_px,
            upper_fronto_parallel_radius_px: geometry.upper_fronto_parallel_radius_px,
            preferred_lower_fronto_parallel_radius_px: geometry
                .preferred_lower_fronto_parallel_radius_px,
            preferred_upper_fronto_parallel_radius_px: geometry
                .preferred_upper_fronto_parallel_radius_px,
            estimated_fronto_parallel_radius_px: geometry.estimated_fronto_parallel_radius_px,
            reference_limbus_fronto_parallel_radius_px: geometry
                .reference_limbus_fronto_parallel_radius_px,
            projection_minor_to_major: geometry.projection_minor_to_major,
            projection_angle: geometry.projection_angle,
            projection_source: geometry.projection_source,
            support_source: geometry.support_source,
            scale_bucket: geometry.scale_bucket,
            temporal_scale_matched: geometry.temporal_scale_matched,
            temporal_observations: geometry.temporal_observations,
            temporal_fractional_half_width: geometry.temporal_fractional_half_width,
            recomputed_this_frame,
            frozen: !recompute,
        })
    }

    fn observe_strong_boundary(
        &mut self,
        now: Instant,
        boundary: &raw_iris_focus::InnerIrisBoundary,
        support: Option<PupilSizeReticle>,
        confidence: f64,
        recompute: bool,
        persistent_state_qualified: bool,
    ) -> bool {
        if !recompute || confidence < 0.25 || !persistent_state_qualified {
            return false;
        }
        let Some(support) = support else {
            return false;
        };
        let Some(radius) = fronto_parallel_area_equivalent_pupil_radius_px(boundary, Some(support))
        else {
            return false;
        };
        if !pupil_radius_within_bounds(radius.value(), Some(support)) {
            return false;
        }
        let Some(ratio) = radius
            .ratio_to(support.reference_limbus_fronto_parallel_radius_px)
            .map(|ratio| ratio.value())
        else {
            return false;
        };
        if !ratio.is_finite() || !(0.01..=0.95).contains(&ratio) {
            return false;
        }
        self.strong_log_ratios.push_back(ratio.ln());
        while self.strong_log_ratios.len() > PUPIL_SIZE_RATIO_WINDOW {
            self.strong_log_ratios.pop_front();
        }
        self.last_strong_observation = Some(now);
        let scale_index = support.scale_bucket.index();
        self.scale_log_ratios[scale_index].push_back(ratio.ln());
        while self.scale_log_ratios[scale_index].len() > PUPIL_SIZE_RATIO_WINDOW {
            self.scale_log_ratios[scale_index].pop_front();
        }
        self.scale_last_strong_observation[scale_index] = Some(now);
        true
    }
}

fn projected_pupil_major_radius_px(boundary: &raw_iris_focus::InnerIrisBoundary) -> Option<f64> {
    let ellipse_radius = boundary.major_radius.max(boundary.minor_radius);
    if ellipse_radius.is_finite() && ellipse_radius > 0.0 {
        Some(ellipse_radius)
    } else if boundary.radius.is_finite() && boundary.radius > 0.0 {
        Some(boundary.radius)
    } else {
        None
    }
}

/// Radius of the equal-area pupil circle after undoing the affine
/// foreshortening measured from the selected limbus.
///
/// If the projected pupil ellipse has semi-axes `a_p`, `b_p` and the limbus
/// projection has `q = b_l / a_l`, inverse rectification multiplies area by
/// `1 / q`. Therefore `r = sqrt(a_p * b_p / q)`. This remains meaningful when
/// partial occlusion makes the fitted pupil axes depart slightly from the
/// limbus aspect ratio, whereas taking only the pupil major axis does not.
fn fronto_parallel_area_equivalent_pupil_radius_px(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
) -> Option<FrontoParallelCircleRadiusPx> {
    let support = support?;
    let major = boundary.major_radius.max(boundary.minor_radius);
    let minor = boundary.major_radius.min(boundary.minor_radius);
    let projected = ProjectedAreaEquivalentRadiusPx::from_ellipse_axes(major, minor)?;
    let foreshortening =
        AffineForeshortening::from_minor_to_major(support.projection_minor_to_major)?;
    FrontoParallelCircleRadiusPx::from_projected_area(projected, foreshortening)
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct PupilDiameterArcEvidence {
    total_points: usize,
    coherent_points: usize,
    strong_alternative_points: usize,
    opposed_coherent_points: usize,
    longest_contiguous_arc_points: usize,
    radius_tolerance_px: f64,
    median_absolute_radius_residual_px: f64,
    median_coherent_transition: f64,
}

impl PupilDiameterArcEvidence {
    fn qualified(self) -> bool {
        self.coherent_points >= PUPIL_DIAMETER_MIN_COHERENT_POINTS
            && self.opposed_coherent_points >= PUPIL_DIAMETER_MIN_OPPOSED_POINTS
            && self.longest_contiguous_arc_points >= PUPIL_DIAMETER_MIN_CONTIGUOUS_ARC_POINTS
    }
}

/// Convert one selected image-space radial point back into the same
/// area-equivalent radius coordinate used by the 21-ray solver.  The pupil
/// ellipse axes encode the limbus-owned affine projection, so the normalized
/// elliptical radius is exactly the selected-radius / fitted-radius ratio.
fn pupil_point_area_equivalent_radius_px(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    point: &raw_iris_focus::InnerIrisPoint,
) -> Option<f64> {
    if !boundary.center.0.is_finite()
        || !boundary.center.1.is_finite()
        || !boundary.radius.is_finite()
        || !boundary.major_radius.is_finite()
        || !boundary.minor_radius.is_finite()
        || !boundary.angle.is_finite()
        || boundary.radius <= 0.0
        || boundary.major_radius <= 0.0
        || boundary.minor_radius <= 0.0
        || !point.x.is_finite()
        || !point.y.is_finite()
    {
        return None;
    }
    let dx = point.x - boundary.center.0;
    let dy = point.y - boundary.center.1;
    let (sine, cosine) = boundary.angle.sin_cos();
    let local_x = cosine * dx + sine * dy;
    let local_y = -sine * dx + cosine * dy;
    let normalized_radius = ((local_x / boundary.major_radius).powi(2)
        + (local_y / boundary.minor_radius).powi(2))
    .sqrt();
    let radius = boundary.radius * normalized_radius;
    (radius.is_finite() && radius > 0.0).then_some(radius)
}

/// Audit whether independent current-frame RAW edges actually support the
/// displayed diameter.  A strong edge at a different radius is retained as a
/// competing-edge diagnostic, never silently counted as support for the
/// robust median.  Contiguous and opposing requirements prevent one lid,
/// fibre, or reflection fragment from training physical pupil-size state.
fn pupil_diameter_arc_evidence(
    boundary: &raw_iris_focus::InnerIrisBoundary,
) -> PupilDiameterArcEvidence {
    let radius_tolerance_px = if boundary.radius.is_finite() && boundary.radius > 0.0 {
        (boundary.radius * PUPIL_DIAMETER_RADIUS_TOLERANCE_FRACTION).clamp(
            PUPIL_DIAMETER_MIN_RADIUS_TOLERANCE_PX,
            PUPIL_DIAMETER_MAX_RADIUS_TOLERANCE_PX,
        )
    } else {
        PUPIL_DIAMETER_MIN_RADIUS_TOLERANCE_PX
    };
    let mut coherent_candidates = Vec::with_capacity(boundary.points.len());
    let mut absolute_residuals = Vec::with_capacity(boundary.points.len());
    let mut strong_alternative_points = 0usize;
    for point in &boundary.points {
        let Some(radius) = pupil_point_area_equivalent_radius_px(boundary, point) else {
            continue;
        };
        let residual = (radius - boundary.radius).abs();
        absolute_residuals.push(residual);
        if !point.score.is_finite() || point.score < PUPIL_DIAMETER_MIN_RAW_TRANSITION {
            continue;
        }
        if residual > radius_tolerance_px {
            strong_alternative_points += 1;
            continue;
        }
        let vector = (point.x - boundary.center.0, point.y - boundary.center.1);
        let length = vector.0.hypot(vector.1);
        if !length.is_finite() || length <= 1.0 {
            continue;
        }
        coherent_candidates.push((
            vector.0 / length,
            vector.1 / length,
            vector.1.atan2(vector.0).rem_euclid(std::f64::consts::TAU),
            point.score,
        ));
    }

    // The production solver owns 21 distinct meridians. Quantizing here keeps
    // malformed or synthetic duplicate points from masquerading as angular
    // coverage while retaining the strongest observation in each sector.
    let mut coherent_sectors = [None; 21];
    for candidate in coherent_candidates {
        let sector = ((candidate.2 / std::f64::consts::TAU * 21.0).round() as usize) % 21;
        if coherent_sectors[sector]
            .is_none_or(|existing: (f64, f64, f64, f64)| candidate.3 > existing.3)
        {
            coherent_sectors[sector] = Some(candidate);
        }
    }
    let coherent = coherent_sectors.into_iter().flatten().collect::<Vec<_>>();
    let coherent_scores = coherent
        .iter()
        .map(|(_, _, _, score)| *score)
        .collect::<Vec<_>>();

    let opposed_coherent_points = coherent
        .iter()
        .filter(|left| {
            coherent
                .iter()
                .any(|right| left.0 * right.0 + left.1 * right.1 <= -0.50)
        })
        .count();
    let mut angles = coherent
        .iter()
        .map(|(_, _, angle, _)| *angle)
        .collect::<Vec<_>>();
    angles.sort_by(f64::total_cmp);
    let maximum_contiguous_gap = std::f64::consts::TAU / 21.0 * 1.60;
    let mut longest_contiguous_arc_points = usize::from(!angles.is_empty());
    for start in 0..angles.len() {
        let mut run = 1usize;
        for offset in 1..angles.len() {
            let previous_index = (start + offset - 1) % angles.len();
            let current_index = (start + offset) % angles.len();
            let previous_wraps = (start + offset - 1) / angles.len();
            let current_wraps = (start + offset) / angles.len();
            let previous = angles[previous_index] + previous_wraps as f64 * std::f64::consts::TAU;
            let current = angles[current_index] + current_wraps as f64 * std::f64::consts::TAU;
            if current - previous > maximum_contiguous_gap {
                break;
            }
            run += 1;
        }
        longest_contiguous_arc_points = longest_contiguous_arc_points.max(run);
    }

    PupilDiameterArcEvidence {
        total_points: boundary.points.len(),
        coherent_points: coherent.len(),
        strong_alternative_points,
        opposed_coherent_points,
        longest_contiguous_arc_points,
        radius_tolerance_px,
        median_absolute_radius_residual_px: pupil_size_median(absolute_residuals).unwrap_or(0.0),
        median_coherent_transition: pupil_size_median(coherent_scores).unwrap_or(0.0),
    }
}

fn pupil_boundary_confidence(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
) -> f64 {
    if boundary.points.len() < 12 {
        return 0.0;
    }
    let Some(major) = projected_pupil_major_radius_px(boundary) else {
        return 0.0;
    };
    let minor = boundary.major_radius.min(boundary.minor_radius);
    if !minor.is_finite() || minor <= 0.0 {
        return 0.0;
    }
    let diameter_evidence = pupil_diameter_arc_evidence(boundary);
    let support_fraction = (diameter_evidence.coherent_points as f64 / 21.0).clamp(0.0, 1.0);
    let score = diameter_evidence.median_coherent_transition.clamp(0.0, 1.0);
    let observed_projection_ratio = (minor / major).clamp(0.0, 1.0);
    // A correctly projected circular pupil is elliptical whenever the limbus
    // is elliptical. Reward agreement with that shared affine projection;
    // raw roundness would incorrectly reduce confidence as the eye turns.
    let shape_agreement = support
        .filter(|support| (0.20..=1.0).contains(&support.projection_minor_to_major))
        .map_or(observed_projection_ratio, |support| {
            let log_ratio_error = (observed_projection_ratio / support.projection_minor_to_major)
                .max(1.0e-6)
                .ln();
            (-0.5 * (log_ratio_error / 0.30).powi(2)).exp()
        });
    let confidence =
        (0.55 * support_fraction + 0.25 * score + 0.20 * shape_agreement).clamp(0.0, 1.0);
    // The affine-circle shape term is a physical plausibility constraint, not
    // an observation. It may never lift a mass/prior-completed ring across
    // the posterior-training threshold without coherent opposing RAW arcs at
    // the diameter actually being published.
    if !diameter_evidence.qualified() {
        confidence.min(0.24)
    } else {
        confidence
    }
}

fn pupil_boundary_normalized_limbus_geometry(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
) -> Option<(f64, f64)> {
    let support = support?;
    if boundary.points.is_empty()
        || !boundary.center.0.is_finite()
        || !boundary.center.1.is_finite()
        || !boundary.major_radius.is_finite()
        || !boundary.minor_radius.is_finite()
        || !boundary.angle.is_finite()
        || boundary.major_radius <= 0.0
        || boundary.minor_radius <= 0.0
        || !support.projection_center.0.is_finite()
        || !support.projection_center.1.is_finite()
    {
        return None;
    }
    let major_radius = support.reference_limbus_fronto_parallel_radius_px.value();
    let minor_radius = major_radius * support.projection_minor_to_major;
    if !major_radius.is_finite()
        || !minor_radius.is_finite()
        || major_radius <= 1.0
        || minor_radius <= 1.0
    {
        return None;
    }
    let delta = (
        boundary.center.0 - support.projection_center.0,
        boundary.center.1 - support.projection_center.1,
    );
    let (axis_sine, axis_cosine) = support.projection_angle.sin_cos();
    let along_major = axis_cosine * delta.0 + axis_sine * delta.1;
    let along_minor = -axis_sine * delta.0 + axis_cosine * delta.1;
    let normalized_offset = (along_major / major_radius).hypot(along_minor / minor_radius);
    let normalized_extent = (0..64)
        .map(|index| {
            let phase = std::f64::consts::TAU * index as f64 / 64.0;
            let (phase_sine, phase_cosine) = phase.sin_cos();
            let local_x = boundary.major_radius * phase_cosine;
            let local_y = boundary.minor_radius * phase_sine;
            let (pupil_sine, pupil_cosine) = boundary.angle.sin_cos();
            let x = boundary.center.0 + pupil_cosine * local_x - pupil_sine * local_y;
            let y = boundary.center.1 + pupil_sine * local_x + pupil_cosine * local_y;
            let delta_x = x - support.projection_center.0;
            let delta_y = y - support.projection_center.1;
            let outer_x = axis_cosine * delta_x + axis_sine * delta_y;
            let outer_y = -axis_sine * delta_x + axis_cosine * delta_y;
            (outer_x / major_radius).hypot(outer_y / minor_radius)
        })
        .fold(0.0_f64, f64::max);
    (normalized_offset.is_finite() && normalized_extent.is_finite())
        .then_some((normalized_offset, normalized_extent))
}

fn pupil_boundary_matches_limbus_geometry(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
) -> bool {
    pupil_boundary_normalized_limbus_geometry(boundary, support).is_some_and(
        |(normalized_offset, normalized_extent)| {
            normalized_offset <= PUPIL_CENTER_MAX_NORMALIZED_LIMBUS_OFFSET
                && normalized_extent <= PUPIL_BOUNDARY_MAX_NORMALIZED_LIMBUS_EXTENT
        },
    )
}

fn pupil_boundary_passes_current_frame_geometry(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
) -> bool {
    !boundary.points.is_empty()
        && fronto_parallel_area_equivalent_pupil_radius_px(boundary, support)
            .is_some_and(|radius| pupil_radius_within_bounds(radius.value(), support))
        && pupil_boundary_matches_limbus_geometry(boundary, support)
}

/// Largest uniform pupil-ellipse scale that remains nested inside the current
/// independently selected limbus projection. In limbus-normalized space each
/// sampled pupil direction is `c + s*v`; solving the quadratic intersection
/// with the containment circle gives a hard, gaze-dependent upper size bound
/// for the physiological rate limiter.
fn pupil_boundary_maximum_contained_scale(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
) -> Option<f64> {
    let support = support?;
    let outer_major = support.reference_limbus_fronto_parallel_radius_px.value();
    let outer_minor = outer_major * support.projection_minor_to_major;
    if boundary.points.is_empty()
        || !boundary.center.0.is_finite()
        || !boundary.center.1.is_finite()
        || !boundary.major_radius.is_finite()
        || !boundary.minor_radius.is_finite()
        || !boundary.angle.is_finite()
        || boundary.major_radius <= 0.0
        || boundary.minor_radius <= 0.0
        || !outer_major.is_finite()
        || !outer_minor.is_finite()
        || outer_major <= 1.0
        || outer_minor <= 1.0
    {
        return None;
    }
    let (outer_sine, outer_cosine) = support.projection_angle.sin_cos();
    let center_delta = (
        boundary.center.0 - support.projection_center.0,
        boundary.center.1 - support.projection_center.1,
    );
    let center = (
        (outer_cosine * center_delta.0 + outer_sine * center_delta.1) / outer_major,
        (-outer_sine * center_delta.0 + outer_cosine * center_delta.1) / outer_minor,
    );
    let limit_squared = PUPIL_BOUNDARY_MAX_NORMALIZED_LIMBUS_EXTENT.powi(2);
    let center_squared = center.0 * center.0 + center.1 * center.1;
    if !center_squared.is_finite() || center_squared >= limit_squared {
        return None;
    }
    let (pupil_sine, pupil_cosine) = boundary.angle.sin_cos();
    let mut maximum_scale = f64::INFINITY;
    for index in 0..64 {
        let phase = std::f64::consts::TAU * index as f64 / 64.0;
        let local = (
            boundary.major_radius * phase.cos(),
            boundary.minor_radius * phase.sin(),
        );
        let image_vector = (
            pupil_cosine * local.0 - pupil_sine * local.1,
            pupil_sine * local.0 + pupil_cosine * local.1,
        );
        let vector = (
            (outer_cosine * image_vector.0 + outer_sine * image_vector.1) / outer_major,
            (-outer_sine * image_vector.0 + outer_cosine * image_vector.1) / outer_minor,
        );
        let quadratic = vector.0 * vector.0 + vector.1 * vector.1;
        if quadratic <= 1.0e-12 {
            continue;
        }
        let linear = 2.0 * (center.0 * vector.0 + center.1 * vector.1);
        let constant = center_squared - limit_squared;
        let discriminant = linear * linear - 4.0 * quadratic * constant;
        if discriminant < 0.0 || !discriminant.is_finite() {
            return None;
        }
        let scale = (-linear + discriminant.sqrt()) / (2.0 * quadratic);
        if !scale.is_finite() || scale <= 0.0 {
            return None;
        }
        maximum_scale = maximum_scale.min(scale);
    }
    (maximum_scale.is_finite() && maximum_scale > 0.0).then_some(maximum_scale)
}

/// Stabilize the published physical pupil/limbus ratio before deciding
/// whether the same observation may train the temporal size posterior.
///
/// The broad operator thresholds are deliberately permissive. A false but
/// hard-bound-valid pupil fit can therefore still be far outside the
/// physiological trajectory. Previously that raw jump entered
/// `strong_log_ratios` before the rate limiter corrected the displayed
/// boundary, allowing one bad center/segmentation transition to bias later
/// searches. A limited observation remains available as a conservative
/// display/gaze result, but it cannot teach the posterior until directly
/// measured frames catch up with the admissible trajectory.
fn stabilize_and_observe_pupil_size(
    size_tracker: &mut PupilSizeTracker,
    radius_limiter: &mut RadiusRateLimiter,
    now: Instant,
    boundary: &mut raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
    confidence: f64,
    recompute: bool,
    evidence_condition: PupilEvidenceCondition,
) -> PupilSizeObservationAdmission {
    if boundary.points.is_empty() {
        return PupilSizeObservationAdmission::default();
    }

    // Evaluate resolvability against the directly fitted boundary before the
    // physiological rate limiter can resize it for conservative publication.
    let focus_size_qualified = evidence_condition.permits_posterior_training(boundary);
    // The selected affine limbus geometry is independent of Y, which owns
    // only the rough seed. A Y mechanism may still yield a candidate after
    // wandering onto a dark lid/hair feature, but that fit cannot teach
    // shared physical pupil-size state unless its complete projected ellipse
    // lies inside that independently supported limbus.
    let limbus_geometry_qualified = pupil_boundary_matches_limbus_geometry(boundary, support);
    let raw_diameter_qualified = pupil_diameter_arc_evidence(boundary).qualified();
    let persistent_state_qualified =
        focus_size_qualified && limbus_geometry_qualified && raw_diameter_qualified;
    // R, weak anatomy, blur, and under-resolution all make this observation
    // read-only with respect to persistent physical-size state. It may be
    // projected against an already admitted trajectory for conservative
    // display, but it cannot move that trajectory and thereby constrain a
    // later sharp measurement.
    let trajectory_qualified =
        recompute && persistent_state_qualified && confidence.is_finite() && confidence >= 0.25;
    let mut rate_limited = false;
    let mut trajectory_updated = false;
    if let (Some(measured_radius), Some(reference)) = (
        fronto_parallel_area_equivalent_pupil_radius_px(boundary, support),
        support
            .map(|value| value.reference_limbus_fronto_parallel_radius_px.value())
            .filter(|value| value.is_finite() && *value > 1.0),
    ) {
        // Rate-limit the scale-invariant pupil/limbus ratio rather than image
        // pixels so gross ROI/pose scale changes pass through unchanged.
        let measured_radius_px = measured_radius.value();
        let measured_ratio = measured_radius_px / reference;
        let hard_lower_ratio = support
            .map(|value| value.lower_fronto_parallel_radius_px / reference)
            .unwrap_or(0.01);
        let operator_hard_upper_ratio = support
            .map(|value| value.upper_fronto_parallel_radius_px / reference)
            .unwrap_or(0.95);
        let containment_hard_upper_ratio = limbus_geometry_qualified
            .then(|| pupil_boundary_maximum_contained_scale(boundary, support))
            .flatten()
            .map(|maximum_scale| measured_ratio * maximum_scale);
        let hard_upper_ratio = containment_hard_upper_ratio
            .map_or(operator_hard_upper_ratio, |contained| {
                operator_hard_upper_ratio.min(contained)
            })
            .max(hard_lower_ratio);
        let (stabilized_ratio, trajectory_limited) = if trajectory_qualified {
            trajectory_updated = true;
            radius_limiter.observe_with_hard_bounds(
                now,
                measured_ratio,
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
                hard_lower_ratio,
                hard_upper_ratio,
            )
        } else {
            trajectory_updated =
                radius_limiter.enforce_state_hard_bounds(now, hard_lower_ratio, hard_upper_ratio);
            radius_limiter.constrain_with_hard_bounds(
                now,
                measured_ratio,
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
                hard_lower_ratio,
                hard_upper_ratio,
            )
        };
        rate_limited = trajectory_limited;
        stabilize_inner_iris_from_measured_radius(
            boundary,
            measured_radius_px,
            stabilized_ratio * reference,
        );
    }

    let trained_posterior = !rate_limited
        && size_tracker.observe_strong_boundary(
            now,
            boundary,
            support,
            confidence,
            recompute,
            persistent_state_qualified,
        );
    PupilSizeObservationAdmission {
        rate_limited,
        focus_size_qualified,
        limbus_geometry_qualified,
        raw_diameter_qualified,
        trajectory_updated,
        trained_posterior,
    }
}

fn pupil_radius_within_bounds(radius: f64, bounds: Option<PupilSizeReticle>) -> bool {
    radius.is_finite()
        && radius > 0.0
        && bounds.is_some_and(|bounds| {
            radius >= bounds.lower_fronto_parallel_radius_px
                && radius <= bounds.upper_fronto_parallel_radius_px
        })
}

/// Keep the sizing guide useful after the common RAW solver refines a rough
/// center. This is presentation-only: search, admission, and temporal sizing
/// continue to use the original per-frame support and never consume the
/// recentered reticle.
fn pupil_size_reticle_for_publication(
    support: Option<PupilSizeReticle>,
    boundary: &raw_iris_focus::InnerIrisBoundary,
) -> Option<PupilSizeReticle> {
    support.map(|mut support| {
        if !boundary.points.is_empty()
            && boundary.center.0.is_finite()
            && boundary.center.1.is_finite()
        {
            support.center = boundary.center;
        }
        support
    })
}

fn iris_radius_reticle_for_publication(
    support: Option<raw_iris_focus::FrontoParallelLimbusRadiusPrior>,
    projection: Option<PupilProjectionReference>,
    mode: SizeReticleMode,
    roi_size: (usize, usize),
) -> Option<IrisRadiusReticle> {
    if !mode.enabled() || roi_size.0 == 0 || roi_size.1 == 0 {
        return None;
    }
    let center = match mode {
        SizeReticleMode::Off => return None,
        SizeReticleMode::StaticCentered => (
            roi_size.0.saturating_sub(1) as f64 * 0.5,
            roi_size.1.saturating_sub(1) as f64 * 0.5,
        ),
        SizeReticleMode::ProjectedFollow => projection?.center,
    };
    let (projection_minor_to_major, projection_angle) = projection
        .map(|projection| (projection.minor_to_major, projection.angle))
        .unwrap_or((1.0, 0.0));
    let (minimum_px, maximum_px, estimate_px, nominal_cold_start) = match support {
        Some(support)
            if support.minimum_px.is_finite()
                && support.maximum_px.is_finite()
                && support.estimate_px.is_finite()
                && support.minimum_px > 0.0
                && support.maximum_px > support.minimum_px
                && (support.minimum_px..=support.maximum_px).contains(&support.estimate_px) =>
        {
            (
                support.minimum_px,
                support.maximum_px,
                support.estimate_px,
                false,
            )
        }
        None if mode == SizeReticleMode::StaticCentered => {
            let estimate =
                roi_size.0.min(roi_size.1) as f64 * STATIC_IRIS_NOMINAL_ROI_SHORT_SIDE_FRACTION;
            (
                estimate * (1.0 - STATIC_IRIS_NOMINAL_HALF_WIDTH),
                estimate * (1.0 + STATIC_IRIS_NOMINAL_HALF_WIDTH),
                estimate,
                true,
            )
        }
        _ => return None,
    };
    Some(IrisRadiusReticle {
        center,
        minimum_fronto_parallel_radius_px: minimum_px,
        maximum_fronto_parallel_radius_px: maximum_px,
        estimated_fronto_parallel_radius_px: estimate_px,
        projection_minor_to_major,
        projection_angle,
        nominal_cold_start,
    })
}

fn pupil_size_reticle_for_mode(
    support: Option<PupilSizeReticle>,
    iris_reticle: Option<IrisRadiusReticle>,
    lower_limbus_fraction: f64,
    upper_limbus_fraction: f64,
    mode: SizeReticleMode,
    roi_size: (usize, usize),
) -> Option<PupilRadiusReticle> {
    if !mode.enabled() || roi_size.0 == 0 || roi_size.1 == 0 {
        return None;
    }
    let static_center = (
        roi_size.0.saturating_sub(1) as f64 * 0.5,
        roi_size.1.saturating_sub(1) as f64 * 0.5,
    );
    if let Some(support) = support {
        return Some(PupilRadiusReticle {
            center: if mode == SizeReticleMode::StaticCentered {
                static_center
            } else {
                support.center
            },
            lower_fronto_parallel_radius_px: support.lower_fronto_parallel_radius_px,
            upper_fronto_parallel_radius_px: support.upper_fronto_parallel_radius_px,
            estimated_fronto_parallel_radius_px: support.estimated_fronto_parallel_radius_px,
            projection_minor_to_major: support.projection_minor_to_major,
            projection_angle: support.projection_angle,
        });
    }
    if mode != SizeReticleMode::StaticCentered {
        return None;
    }

    // Static manual alignment needs size, not a predicted pupil center. When
    // the Y mechanism is unavailable, derive the two hard pupil circles from
    // the display iris reference (current G support, or the static cold-start
    // nominal) and the operator's pupil/limbus ratios. This object is
    // draw-only and never feeds the pupil solver.
    let iris_reticle = iris_reticle?;
    let reference_radius = iris_reticle.estimated_fronto_parallel_radius_px;
    let lower = reference_radius
        * lower_limbus_fraction.clamp(
            PUPIL_RADIUS_OPERATOR_MINIMUM_FRACTION,
            PUPIL_RADIUS_OPERATOR_MAXIMUM_FRACTION,
        );
    let upper = reference_radius
        * upper_limbus_fraction.clamp(
            PUPIL_RADIUS_OPERATOR_MINIMUM_FRACTION,
            PUPIL_RADIUS_OPERATOR_MAXIMUM_FRACTION,
        );
    if !lower.is_finite()
        || !upper.is_finite()
        || lower <= 0.0
        || upper <= lower
        || !reference_radius.is_finite()
    {
        return None;
    }
    Some(PupilRadiusReticle {
        center: static_center,
        lower_fronto_parallel_radius_px: lower,
        upper_fronto_parallel_radius_px: upper,
        estimated_fronto_parallel_radius_px: None,
        projection_minor_to_major: iris_reticle.projection_minor_to_major,
        projection_angle: iris_reticle.projection_angle,
    })
}

/// Convert the fronto-parallel pupil-size posterior into the projected,
/// area-equivalent radius used as a hypothesis inside the native radial
/// margin solver. The learned interval is never an admissibility bound: a
/// sparse current-frame arc outside it must remain observable so that a bad
/// carried radius can be disproved.
fn inner_radius_prior_from_support(
    support: Option<PupilSizeReticle>,
) -> Option<raw_iris_focus::InnerIrisRadiusPrior> {
    let scale = support
        .map(|value| value.reference_limbus_fronto_parallel_radius_px.value())
        .unwrap_or(PUPIL_EVIDENCE_SCALE_BASE_RADIUS_PX);
    inner_radius_prior_from_support_conditioned(
        support,
        PupilEvidenceCondition::fully_reliable(scale),
    )
}

fn inner_radius_envelope_from_support(
    support: Option<PupilSizeReticle>,
) -> Option<raw_iris_focus::InnerIrisRadiusEnvelope> {
    let support = support?;
    // This is a true admission envelope, so it contains only explicit
    // operator/physiological limits. The temporal preferred interval used to
    // replace these values after three observations, which prevented the RAW
    // scan from even seeing a real but smaller/larger pupil arc. History now
    // remains a soft proposal and the prior-free polar candidate bank always
    // spans the same broad current-frame support.
    let lower_fronto_parallel = support.lower_fronto_parallel_radius_px;
    let upper_fronto_parallel = support.upper_fronto_parallel_radius_px;
    // The RAW ray solver searches projected area-equivalent radii, whereas
    // the operator guides and temporal posterior use the de-affined
    // fronto-parallel circle radius. Under the same weak-perspective affine
    // projection, area-equivalent radius scales by sqrt(minor / major).
    let projection_scale = support
        .projection_minor_to_major
        .clamp(
            raw_iris_focus::PROVISIONAL_CENTRAL_CAMERA_LIMBUS_ENVELOPE
                .absolute_minimum_minor_to_major,
            1.0,
        )
        .sqrt();
    raw_iris_focus::InnerIrisRadiusEnvelope::new(
        lower_fronto_parallel * projection_scale,
        upper_fronto_parallel * projection_scale,
    )
}

fn inner_radius_prior_from_support_conditioned(
    support: Option<PupilSizeReticle>,
    evidence_condition: PupilEvidenceCondition,
) -> Option<raw_iris_focus::InnerIrisRadiusPrior> {
    let support = support?;
    if support.support_source != PupilSizeSupportSource::TemporalPupilRatio
        || support.temporal_observations < PUPIL_SIZE_TEMPORAL_MIN_OBSERVATIONS
    {
        return None;
    }
    let estimate = support.estimated_fronto_parallel_radius_px?;
    let preferred_lower = support.preferred_lower_fronto_parallel_radius_px?;
    let preferred_upper = support.preferred_upper_fronto_parallel_radius_px?;
    let projection_scale = support
        .projection_minor_to_major
        .clamp(
            raw_iris_focus::PROVISIONAL_CENTRAL_CAMERA_LIMBUS_ENVELOPE
                .absolute_minimum_minor_to_major,
            1.0,
        )
        .sqrt();
    let observation_confidence =
        (support.temporal_observations as f64 / PUPIL_SIZE_RATIO_WINDOW as f64).clamp(0.0, 1.0);
    let precision_confidence = support
        .temporal_fractional_half_width
        .map_or(0.0, |half_width| {
            (1.0 - (half_width - PUPIL_SIZE_MIN_TEMPORAL_HALF_WIDTH)
                / (PUPIL_SIZE_MAX_TEMPORAL_HALF_WIDTH - PUPIL_SIZE_MIN_TEMPORAL_HALF_WIDTH))
                .clamp(0.0, 1.0)
        });
    let base_confidence =
        (0.15 + 0.45 * observation_confidence + 0.40 * precision_confidence).clamp(0.0, 1.0);
    // When the current edge/color detail is soft or under-resolved, let the
    // already learned temporal interval break more ties. This remains a soft
    // reward inside the RAW solver; it never becomes an admission bound and
    // cannot suppress a strong current-frame dilation.
    let confidence =
        (base_confidence + 0.20 * (1.0 - evidence_condition.cue_reliability)).clamp(0.0, 1.0);
    raw_iris_focus::InnerIrisRadiusPrior::new(
        estimate * projection_scale,
        preferred_lower * projection_scale,
        preferred_upper * projection_scale,
        confidence,
    )
}

fn select_rough_pupil_center(
    mode: RoughPupilCenterMode,
    selected_outer: &raw_iris_focus::OuterIrisBoundary,
    raw_pupil_center: Option<(f64, f64)>,
    sam_pupil_center: Option<(f64, f64)>,
    roi_size: (usize, usize),
    driving_pupil: Option<(f64, f64)>,
) -> Option<(f64, f64)> {
    let center = match mode {
        RoughPupilCenterMode::IrisGuided => {
            (!selected_outer.points.is_empty()).then_some(selected_outer.center)
        }
        RoughPupilCenterMode::RawFocus => raw_pupil_center,
        RoughPupilCenterMode::Sam31 => sam_pupil_center,
        RoughPupilCenterMode::MediaPipeAcquire | RoughPupilCenterMode::MediaPipeContinuous => {
            Some((
                roi_size.0.saturating_sub(1) as f64 * 0.5,
                roi_size.1.saturating_sub(1) as f64 * 0.5,
            ))
        }
        RoughPupilCenterMode::DrivingTopology => driving_pupil,
    }?;
    (center.0.is_finite() && center.1.is_finite()).then_some(center)
}

fn select_pupil_projection_reference(
    selected_outer: &raw_iris_focus::OuterIrisBoundary,
    censored_limbus: Option<raw_iris_focus::RoiTruncatedLimbusObservation>,
    raw_focus: &raw_iris_focus::BorderFocus,
    raw_eye_anatomy_confirmed: bool,
) -> Option<PupilProjectionReference> {
    PupilProjectionReference::from_outer(selected_outer, PupilProjectionSource::SelectedIris)
        .or_else(|| {
            raw_eye_anatomy_confirmed
                .then(|| censored_limbus.and_then(PupilProjectionReference::from_censored))
                .flatten()
        })
        .or_else(|| {
            raw_eye_anatomy_confirmed
                .then(|| PupilProjectionReference::from_raw_focus(raw_focus))
                .flatten()
        })
}

fn pupil_projection_focus(
    raw_focus: &raw_iris_focus::BorderFocus,
    projection: PupilProjectionReference,
) -> raw_iris_focus::BorderFocus {
    let mut search = raw_focus.clone();
    // This BorderFocus is the G-owned affine/search frame. Keep its center on
    // the independently selected limbus; the Y-owned rough pupil center is a
    // separate argument to the full-resolution boundary solver below.
    search.center = projection.center;
    search.radius = projection.equivalent_limbus_radius_px;
    search.axis_ratio = 1.0 / projection.minor_to_major.max(0.01);
    search.axis_angle = projection.angle;
    // Y has already selected the sole rough-center product. BorderFocus also
    // carries a private hint from the always-on native acquisition heuristic;
    // retaining it here silently lets that unselected producer pull SAM,
    // MediaPipe, Driving, and iris-guided modes inside the common RAW center
    // refinement. Strip the foreign proposal and let only the explicitly
    // supplied rough center plus untouched full-resolution RAW evidence
    // determine the refined pupil.
    search.pupil_hint = None;
    search.pupil_hint_radius = 0.0;
    search.pupil_hint_score = 0.0;
    search
}

/// Preserve the prior-free radial maxima even when the legacy complete-ring
/// contract fails. Empty `points` keeps every existing publication/gaze gate
/// closed; the sparse temporal co-solver alone consumes `radial_candidates`.
fn sparse_only_inner_boundary(
    mut boundary: raw_iris_focus::InnerIrisBoundary,
) -> raw_iris_focus::InnerIrisBoundary {
    boundary.radius = 0.0;
    boundary.major_radius = 0.0;
    boundary.minor_radius = 0.0;
    boundary.angle = 0.0;
    boundary.points.clear();
    boundary
}

fn richer_sparse_inner_boundary(
    left: &raw_iris_focus::InnerIrisBoundary,
    right: &raw_iris_focus::InnerIrisBoundary,
) -> raw_iris_focus::InnerIrisBoundary {
    let quality = |boundary: &raw_iris_focus::InnerIrisBoundary| {
        boundary
            .radial_candidates
            .iter()
            .filter(|candidate| candidate.raw_score.is_finite())
            .map(|candidate| candidate.raw_score.max(0.0))
            .sum::<f64>()
    };
    if quality(right) > quality(left) {
        sparse_only_inner_boundary(right.clone())
    } else {
        sparse_only_inner_boundary(left.clone())
    }
}

#[allow(clippy::too_many_arguments)]
fn solve_pupil_boundary_from_rough_center(
    raw: &[u16],
    width: usize,
    height: usize,
    sensor_x: u32,
    sensor_y: u32,
    raw_focus: &raw_iris_focus::BorderFocus,
    projection: PupilProjectionReference,
    rough_center: (f64, f64),
    support: Option<PupilSizeReticle>,
    radius_prior: Option<raw_iris_focus::InnerIrisRadiusPrior>,
    evidence_condition: raw_iris_focus::InnerIrisEvidenceCondition,
) -> raw_iris_focus::InnerIrisBoundary {
    let search = pupil_projection_focus(raw_focus, projection);
    let solve = |center| {
        raw_iris_focus::detect_inner_iris_boundary_conditioned_at_center(
            raw,
            width,
            height,
            sensor_x,
            sensor_y,
            &search,
            center,
            inner_radius_envelope_from_support(support),
            radius_prior,
            evidence_condition,
        )
    };
    let primary = solve(rough_center);
    if pupil_boundary_passes_current_frame_geometry(&primary, support) {
        return primary;
    }
    // The primary rough coordinate remains authoritative whenever it forms a
    // feasible ring. Only after that hypothesis is disproved may the
    // independently fitted limbus center act as a conservative frontal-eye
    // fallback. Keeping the ray origin fixed here is important: a second
    // open-ended dark search can reacquire the same upper-lid shadow which
    // invalidated the primary center.
    if (rough_center.0 - projection.center.0).hypot(rough_center.1 - projection.center.1) > 2.0 {
        let fallback = solve(projection.center);
        if pupil_boundary_passes_current_frame_geometry(&fallback, support) {
            return fallback;
        }
        return richer_sparse_inner_boundary(&primary, &fallback);
    }
    sparse_only_inner_boundary(primary)
}

fn pupil_boundary_is_usable_center_measurement(
    boundary: &raw_iris_focus::InnerIrisBoundary,
    support: Option<PupilSizeReticle>,
) -> bool {
    boundary.points.len() >= 8
        && boundary.radius.is_finite()
        && boundary.radius > 4.0
        && support.map_or(true, |_| {
            pupil_boundary_passes_current_frame_geometry(boundary, support)
        })
}

/// Shared temporal center authority used by every `Y` rough-center mode.
///
/// The selected producer supplies only a frame-local acquisition proposal.
/// Once a pupil is established, the state is transported by the finalized
/// limbus affine frame. The untouched native RAW ring may make a small
/// fixation correction; a remote result is held until coherent pupil/iris
/// kinematics or a second agreeing frame supports a saccade. Specular points
/// never enter this state transition.
#[allow(clippy::too_many_arguments)]
fn solve_pupil_boundary_from_temporal_state(
    tracker: &mut PupilCenterStateTracker,
    now: Instant,
    sensor_origin: (u32, u32),
    raw: &[u16],
    width: usize,
    height: usize,
    raw_focus: &raw_iris_focus::BorderFocus,
    projection: PupilProjectionReference,
    prediction: PupilCenterPrediction,
    frame_proposal: Option<(f64, f64)>,
    motion: &raw_motion_octrees::MotionOctreeOverlay,
    support: Option<PupilSizeReticle>,
    radius_prior: Option<raw_iris_focus::InnerIrisRadiusPrior>,
    evidence_condition: raw_iris_focus::InnerIrisEvidenceCondition,
) -> raw_iris_focus::InnerIrisBoundary {
    let search = pupil_projection_focus(raw_focus, projection);
    let solve = |center| {
        raw_iris_focus::detect_inner_iris_boundary_conditioned_at_center(
            raw,
            width,
            height,
            sensor_origin.0,
            sensor_origin.1,
            &search,
            center,
            inner_radius_envelope_from_support(support),
            radius_prior,
            evidence_condition,
        )
    };
    let primary = solve(prediction.center);
    let saccade_motion = pupil_center_saccade_motion_supported(motion);
    let broad_saccade_search = saccade_motion || pupil_center_saccade_search_warranted(motion);
    // A displaced frame-local proposal is still worth measuring when the
    // transported center no longer forms a usable RAW ring.  It must not be
    // *published* merely because it exists: `assimilate` independently
    // requires coherent non-specular saccade motion or a second agreeing RAW
    // ring.  Suppressing this measurement here made the latter confirmation
    // path impossible during the first frame of an unclassified saccade.
    // In the optically clocked fixation capture, re-solving at the independent
    // rough basin increased current-frame RAW boundary availability and
    // reduced held-out target-motion residual.  A coherent primary ring is
    // therefore not proof that its *center* is the pupil: iris texture can
    // form one too.  Probe the independent rough center whenever it is
    // materially displaced, but keep the probe inside the finalized limbus'
    // canonical pupil corridor.  This is one additional native-RAW radial
    // solve; no image copy, resize, pyramid, or screen-clock input is involved.
    let proposal_boundary = frame_proposal
        .filter(|proposal| {
            (proposal.0 - prediction.center.0).hypot(proposal.1 - prediction.center.1)
                > (projection.fronto_parallel_limbus_radius_px.value() * 0.018).clamp(2.0, 4.0)
        })
        .filter(|proposal| {
            pupil_projection_canonical_point(projection, *proposal).is_some_and(|canonical| {
                canonical.0.hypot(canonical.1) <= PUPIL_CENTER_MAX_NORMALIZED_LIMBUS_OFFSET + 0.06
            })
        })
        .map(solve);
    let proposal_preferred = proposal_boundary.as_ref().is_some_and(|proposal| {
        if !pupil_boundary_is_usable_center_measurement(proposal, support) {
            return false;
        }
        let proposal_quality = pupil_boundary_confidence(proposal, support);
        let proposal_diameter = pupil_diameter_arc_evidence(proposal).qualified();
        let primary_quality = pupil_boundary_confidence(&primary, support);
        let primary_diameter = pupil_diameter_arc_evidence(&primary).qualified();
        !pupil_boundary_is_usable_center_measurement(&primary, support)
            || (proposal_diameter && !primary_diameter)
            || (proposal_diameter
                && proposal_quality >= primary_quality + 0.055
                && proposal_quality >= 0.28)
    });
    let sparse_fallback = proposal_boundary.as_ref().map_or_else(
        || sparse_only_inner_boundary(primary.clone()),
        |proposal| richer_sparse_inner_boundary(&primary, proposal),
    );
    let equivalent_radius = if proposal_preferred {
        proposal_boundary.as_ref().map(|boundary| boundary.radius)
    } else if pupil_boundary_is_usable_center_measurement(&primary, support) {
        Some(primary.radius)
    } else {
        proposal_boundary
            .as_ref()
            .filter(|boundary| pupil_boundary_is_usable_center_measurement(boundary, support))
            .map(|boundary| boundary.radius)
    };
    let measurement = equivalent_radius.and_then(|equivalent_radius| {
        let seed = if proposal_preferred {
            proposal_boundary
                .as_ref()
                .map_or(prediction.center, |boundary| boundary.center)
        } else {
            frame_proposal.unwrap_or(prediction.center)
        };
        if !prediction.transported_track {
            // Most rough-center producers are already within a few pixels on
            // a frontal eye. Cold acquisition therefore refines locally
            // around that independent coordinate instead of allowing an
            // unrelated iris-texture ring to win a whole-limbus sweep.
            let refinement =
                (projection.fronto_parallel_limbus_radius_px.value() * 0.055).clamp(4.0, 8.0);
            raw_iris_focus::select_pupil_center_near_strong_prior_at_fixed_radius(
                raw,
                width,
                height,
                sensor_origin.0,
                sensor_origin.1,
                &search,
                seed,
                seed,
                equivalent_radius,
                refinement,
                0.10,
            )
        } else if proposal_preferred || !broad_saccade_search {
            raw_iris_focus::select_pupil_center_near_strong_prior_at_fixed_radius(
                raw,
                width,
                height,
                sensor_origin.0,
                sensor_origin.1,
                &search,
                seed,
                if proposal_preferred {
                    seed
                } else {
                    prediction.center
                },
                equivalent_radius,
                if proposal_preferred { 5.5 } else { 3.5 },
                if proposal_preferred { 0.16 } else { 0.10 },
            )
        } else {
            raw_iris_focus::optimize_pupil_center_orbitally_at_fixed_radius(
                raw,
                width,
                height,
                sensor_origin.0,
                sensor_origin.1,
                &search,
                seed,
                equivalent_radius,
                prediction
                    .transported_track
                    .then_some((prediction.center, 4.0)),
            )
        }
    });
    let Some(center) = tracker.assimilate(
        now,
        sensor_origin,
        Some(projection),
        prediction,
        frame_proposal,
        measurement,
        motion,
    ) else {
        return sparse_fallback;
    };
    let boundary = if (primary.center.0 - center.0).hypot(primary.center.1 - center.1) <= 0.05 {
        primary
    } else if proposal_boundary.as_ref().is_some_and(|proposal| {
        (proposal.center.0 - center.0).hypot(proposal.center.1 - center.1) <= 0.05
    }) {
        proposal_boundary.unwrap_or_default()
    } else {
        solve(center)
    };
    if pupil_boundary_is_usable_center_measurement(&boundary, support) {
        boundary
    } else if boundary.radial_candidates.is_empty() {
        sparse_fallback
    } else {
        sparse_only_inner_boundary(boundary)
    }
}

fn select_high_confidence_limbus_points(
    boundary: &raw_iris_focus::OuterIrisBoundary,
    limit: usize,
) -> Vec<(f64, f64)> {
    if limit == 0 {
        return Vec::new();
    }
    let mut candidates = boundary
        .evidence_points
        .iter()
        .filter(|point| point.x.is_finite() && point.y.is_finite() && point.contrast.is_finite())
        .copied()
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        right
            .contrast
            .partial_cmp(&left.contrast)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    if candidates.len() <= limit {
        return candidates
            .into_iter()
            .map(|point| (point.x, point.y))
            .collect();
    }
    let angle_of = |point: raw_iris_focus::OuterIrisPoint| {
        (point.y - boundary.center.1).atan2(point.x - boundary.center.0)
    };
    let high_density_side_arc = |angle: f64| {
        let degrees = angle.to_degrees().rem_euclid(360.0);
        degrees <= 30.0 || (120.0..=210.0).contains(&degrees) || degrees >= 330.0
    };
    let turn_distance = |left: f64, right: f64| {
        (left - right + std::f64::consts::PI).rem_euclid(2.0 * std::f64::consts::PI)
            - std::f64::consts::PI
    };
    for separation_scale in [0.72, 0.54, 0.36, 0.18, 0.0] {
        let minimum_separation = separation_scale * 2.0 * std::f64::consts::PI / limit as f64;
        let mut selected = Vec::<raw_iris_focus::OuterIrisPoint>::with_capacity(limit);
        for candidate in &candidates {
            let angle = angle_of(*candidate);
            if selected.iter().all(|existing| {
                let existing_angle = angle_of(*existing);
                let density =
                    if high_density_side_arc(angle) && high_density_side_arc(existing_angle) {
                        3.0
                    } else {
                        1.0
                    };
                turn_distance(angle, existing_angle).abs() >= minimum_separation / density
            }) {
                selected.push(*candidate);
                if selected.len() == limit {
                    return selected
                        .into_iter()
                        .map(|point| (point.x, point.y))
                        .collect();
                }
            }
        }
    }
    candidates
        .into_iter()
        .take(limit)
        .map(|point| (point.x, point.y))
        .collect()
}

fn stabilize_inner_iris_fronto_parallel_radius(
    boundary: &mut raw_iris_focus::InnerIrisBoundary,
    stabilized_fronto_parallel_radius: f64,
) {
    let Some(measured_fronto_parallel_radius) = projected_pupil_major_radius_px(boundary) else {
        return;
    };
    stabilize_inner_iris_from_measured_radius(
        boundary,
        measured_fronto_parallel_radius,
        stabilized_fronto_parallel_radius,
    );
}

fn stabilize_inner_iris_from_measured_radius(
    boundary: &mut raw_iris_focus::InnerIrisBoundary,
    measured_fronto_parallel_radius: f64,
    stabilized_fronto_parallel_radius: f64,
) {
    if !measured_fronto_parallel_radius.is_finite() || measured_fronto_parallel_radius <= 0.0 {
        return;
    }
    if !stabilized_fronto_parallel_radius.is_finite() || stabilized_fronto_parallel_radius <= 0.0 {
        return;
    }
    let scale = stabilized_fronto_parallel_radius / measured_fronto_parallel_radius;
    boundary.radius *= scale;
    boundary.major_radius *= scale;
    boundary.minor_radius *= scale;
    for point in &mut boundary.points {
        point.x = boundary.center.0 + (point.x - boundary.center.0) * scale;
        point.y = boundary.center.1 + (point.y - boundary.center.1) * scale;
    }
}

fn sam31_result_belongs_to_selection(
    source_timestamp_ns: u64,
    selection_started_ns: Option<u64>,
) -> bool {
    selection_started_ns.is_some_and(|started| source_timestamp_ns >= started)
}

fn sam31_registered_ellipse_for_frame(
    result: &sam31_outer::OuterResult,
    mut ellipse: sam31_outer::Ellipse,
    timestamp_ns: u64,
    sensor_x: u32,
    sensor_y: u32,
    current_registration_anchor: Option<(f64, f64)>,
) -> Option<sam31_outer::Ellipse> {
    // A completed inference is sensor-registered, so ROI steering does not
    // invalidate it.  Do not, however, keep projecting an old expression or
    // gaze pose indefinitely when the worker is starved.
    if timestamp_ns.abs_diff(result.source_timestamp_ns) > SAM31_RESULT_MAX_AGE_NS {
        return None;
    }
    if let (Some(source), Some(current)) = (
        result.source_registration_anchor_sensor,
        current_registration_anchor
            .map(|center| (center.0 + sensor_x as f64, center.1 + sensor_y as f64)),
    ) {
        let delta = (current.0 - source.0, current.1 - source.1);
        let distance = delta.0.hypot(delta.1);
        if distance <= result.sensor_outer_ellipse.major_radius * 0.42 {
            ellipse.center.0 += delta.0;
            ellipse.center.1 += delta.1;
        }
    }
    ellipse.center.0 -= sensor_x as f64;
    ellipse.center.1 -= sensor_y as f64;
    if !ellipse.center.0.is_finite()
        || !ellipse.center.1.is_finite()
        || ellipse.center.0 < -ellipse.major_radius * 0.5
        || ellipse.center.1 < -ellipse.major_radius * 0.5
        || ellipse.center.0 > sam31_outer::FRAME_WIDTH as f64 + ellipse.major_radius * 0.5
        || ellipse.center.1 > sam31_outer::FRAME_HEIGHT as f64 + ellipse.major_radius * 0.5
    {
        return None;
    }
    Some(ellipse)
}

fn sam31_outer_boundary_for_frame(
    result: &sam31_outer::OuterResult,
    timestamp_ns: u64,
    sensor_x: u32,
    sensor_y: u32,
    current_registration_anchor: Option<(f64, f64)>,
) -> Option<raw_iris_focus::OuterIrisBoundary> {
    let ellipse = sam31_registered_ellipse_for_frame(
        result,
        result.sensor_outer_ellipse,
        timestamp_ns,
        sensor_x,
        sensor_y,
        current_registration_anchor,
    )?;
    let dense = ellipse.dense_points(96);
    let points = dense
        .iter()
        .map(|&(x, y)| raw_iris_focus::OuterIrisPoint {
            x,
            y,
            contrast: result.quality,
        })
        .collect::<Vec<_>>();
    let evidence_points = (0..21)
        .map(|index| {
            let point = dense[index * dense.len() / 21];
            raw_iris_focus::OuterIrisPoint {
                x: point.0,
                y: point.1,
                contrast: result.quality,
            }
        })
        .collect();
    Some(raw_iris_focus::OuterIrisBoundary {
        center: ellipse.center,
        major_radius: ellipse.major_radius,
        minor_radius: ellipse.minor_radius,
        angle: ellipse.angle,
        evidence_points,
        occluded_points: Vec::new(),
        veto_sweep_endpoints: Vec::new(),
        points,
    })
}

fn sam31_pupil_center_for_frame(
    result: &sam31_outer::OuterResult,
    timestamp_ns: u64,
    sensor_x: u32,
    sensor_y: u32,
    current_registration_anchor: Option<(f64, f64)>,
) -> Option<(f64, f64)> {
    let sensor_pupil_ellipse = result.sensor_pupil_ellipse?;
    let ellipse = sam31_registered_ellipse_for_frame(
        result,
        sensor_pupil_ellipse,
        timestamp_ns,
        sensor_x,
        sensor_y,
        current_registration_anchor,
    )?;
    // Y's SAM center is self-contained: its private outer product may reject
    // an implausible pupil component, but the G-selected published iris is
    // deliberately absent from this API. Changing G therefore cannot change
    // the same registered SAM center. The private guide is discarded here;
    // only `ellipse.center` reaches the common native RAW pupil solver.
    let private_outer = sam31_registered_ellipse_for_frame(
        result,
        result.sensor_outer_ellipse,
        timestamp_ns,
        sensor_x,
        sensor_y,
        current_registration_anchor,
    )?;
    let outer_scale = (private_outer.major_radius * private_outer.minor_radius)
        .sqrt()
        .max(1.0);
    let pupil_scale = (ellipse.major_radius * ellipse.minor_radius).sqrt();
    let center_distance = (ellipse.center.0 - private_outer.center.0)
        .hypot(ellipse.center.1 - private_outer.center.1);
    if !pupil_scale.is_finite()
        || pupil_scale < 5.0
        || pupil_scale > outer_scale * 0.72
        || center_distance > outer_scale * 0.58
    {
        return None;
    }
    Some(ellipse.center)
}

fn outer_iris_boundaries_agree(
    first: &raw_iris_focus::OuterIrisBoundary,
    second: &raw_iris_focus::OuterIrisBoundary,
) -> bool {
    if first.points.is_empty() || second.points.is_empty() {
        return false;
    }
    let reference = (first.major_radius * first.minor_radius)
        .sqrt()
        .min((second.major_radius * second.minor_radius).sqrt())
        .max(1.0);
    let center_error =
        (first.center.0 - second.center.0).hypot(first.center.1 - second.center.1) / reference;
    let major_error = (first.major_radius / second.major_radius.max(1.0))
        .ln()
        .abs();
    let minor_error = (first.minor_radius / second.minor_radius.max(1.0))
        .ln()
        .abs();
    center_error <= 0.32 && major_error <= 1.35f64.ln() && minor_error <= 1.40f64.ln()
}

fn roi_truncated_limbus_points(
    observation: raw_iris_focus::RoiTruncatedLimbusObservation,
    samples: usize,
) -> Vec<(f64, f64)> {
    let samples = samples.max(16);
    let axis_cosine = observation.angle.cos();
    let axis_sine = observation.angle.sin();
    (0..samples)
        .map(|sample| {
            let phase = std::f64::consts::TAU * sample as f64 / samples as f64;
            let local_x = observation.major_radius * phase.cos();
            let local_y = observation.minor_radius * phase.sin();
            (
                observation.center.0 + axis_cosine * local_x - axis_sine * local_y,
                observation.center.1 + axis_sine * local_x + axis_cosine * local_y,
            )
        })
        .collect()
}

/// Turn a censored conic into a seed-only Driving boundary. Only the samples
/// that are actually present in the lossless RAW ROI are attached as support;
/// the ellipse parameters still describe the projected circle so Driving can
/// search through the missing side. This boundary must remain behind the
/// independent temporal iris-texture gate and must never be published on its
/// own as completed eye anatomy.
fn roi_truncated_limbus_driving_seed(
    observation: raw_iris_focus::RoiTruncatedLimbusObservation,
    width: usize,
    height: usize,
) -> Option<raw_iris_focus::OuterIrisBoundary> {
    if !roi_truncated_limbus_recovery_ready(observation) {
        return None;
    }
    let contrast = (observation.confidence * 255.0).clamp(1.0, 255.0);
    let points = roi_truncated_limbus_points(observation, 64)
        .into_iter()
        .filter(|&(x, y)| (0.0..width as f64).contains(&x) && (0.0..height as f64).contains(&y))
        .map(|(x, y)| raw_iris_focus::OuterIrisPoint { x, y, contrast })
        .collect::<Vec<_>>();
    if points.len() < 8 {
        return None;
    }
    Some(raw_iris_focus::OuterIrisBoundary {
        center: observation.center,
        major_radius: observation.major_radius,
        minor_radius: observation.minor_radius,
        angle: observation.angle,
        evidence_points: points.clone(),
        occluded_points: Vec::new(),
        veto_sweep_endpoints: Vec::new(),
        points,
    })
}

fn roi_truncated_limbus_recovery_ready(
    observation: raw_iris_focus::RoiTruncatedLimbusObservation,
) -> bool {
    observation.censored_edges != 0
        && observation.confidence >= 0.72
        && observation.visible_arc_fraction >= 0.58
        && observation.visible_arc_fraction < 0.995
        && observation.supported_probe_fraction >= 0.52
        && observation.center.0.is_finite()
        && observation.center.1.is_finite()
        && observation.major_radius.is_finite()
        && observation.minor_radius.is_finite()
        && observation.major_radius >= 20.0
        && observation.minor_radius >= 20.0
}

#[derive(Clone, Copy, Debug, Default)]
struct RoiTruncatedIrisTextureEvidence {
    interior_edges: usize,
    motion_shadow_edges: usize,
    radial_edges: usize,
    radial_sectors: usize,
    transverse_edges: usize,
    transverse_sectors: usize,
    mean_radial_alignment: f64,
    /// Signed second angular moment of the edge normals in the candidate's
    /// affine-polar frame. Positive means concentric-arc/radial-normal
    /// organization; negative means radial-fiber/transverse-normal
    /// organization. Isotropic skin/noise tends to zero.
    radial_orientation_bias: f64,
    polar_orientation_anisotropy: f64,
    provisional_features: usize,
    persistent_features: usize,
}

impl RoiTruncatedIrisTextureEvidence {
    fn authorizes_bounded_topology_probe(self) -> bool {
        let (organized_edges, organized_sectors) = if self.radial_orientation_bias >= 0.0 {
            (self.radial_edges, self.radial_sectors)
        } else {
            (self.transverse_edges, self.transverse_sectors)
        };
        self.interior_edges >= 24
            && organized_edges >= 8
            && organized_sectors >= 4
            && self.polar_orientation_anisotropy >= 0.075
            // A single textured frame is proposal evidence, not identity.
            // Requiring promoted native-resolution patches prevents a new
            // forehead crop from authorizing its own false eye hypothesis.
            && self.persistent_features >= 3
    }

    fn authorizes_cold_partial_topology_probe(self) -> bool {
        // A transported, previously admitted eye needs only enough current
        // texture to corroborate its known location.  A cold ROI-censored
        // proposal has no such identity authority: the reviewed curved-skin
        // failure promoted four or five coherent patches, while the real
        // clipped iris promoted ten.  Demand the stronger cohort only when a
        // partial conic is trying to bootstrap Driving from scratch.
        self.authorizes_bounded_topology_probe() && self.persistent_features >= 6
    }
}

fn driving_partial_frame_seed(
    observation: raw_iris_focus::RoiTruncatedLimbusObservation,
    texture: RoiTruncatedIrisTextureEvidence,
    width: usize,
    height: usize,
) -> Option<raw_iris_focus::OuterIrisBoundary> {
    texture
        .authorizes_bounded_topology_probe()
        .then(|| roi_truncated_limbus_driving_seed(observation, width, height))
        .flatten()
}

fn driving_complete_frame_seed_ready(
    native_boundary_ready: bool,
    native_fit_accepted: bool,
    independent_focus_anatomy: bool,
    texture: Option<RoiTruncatedIrisTextureEvidence>,
) -> bool {
    driving_full_topology_probe_ready(native_boundary_ready, native_fit_accepted)
        && (independent_focus_anatomy
            || texture.is_some_and(|evidence| evidence.authorizes_bounded_topology_probe()))
}

fn roi_truncated_iris_texture_evidence(
    observation: raw_iris_focus::RoiTruncatedLimbusObservation,
    overlay: &raw_motion_octrees::MotionOctreeOverlay,
) -> RoiTruncatedIrisTextureEvidence {
    if !roi_truncated_limbus_recovery_ready(observation) {
        return RoiTruncatedIrisTextureEvidence::default();
    }
    iris_texture_evidence(
        raw_motion_octrees::IrisEllipseSeed {
            center: observation.center,
            major_radius: observation.major_radius,
            minor_radius: observation.minor_radius,
            angle: observation.angle,
        },
        overlay,
    )
}

fn iris_texture_evidence(
    ellipse: raw_motion_octrees::IrisEllipseSeed,
    overlay: &raw_motion_octrees::MotionOctreeOverlay,
) -> RoiTruncatedIrisTextureEvidence {
    iris_texture_evidence_for_motion_layer(ellipse, overlay, raw_motion_octrees::PUPIL_LAYER)
}

fn iris_texture_evidence_for_motion_layer(
    ellipse: raw_motion_octrees::IrisEllipseSeed,
    overlay: &raw_motion_octrees::MotionOctreeOverlay,
    motion_layer: usize,
) -> RoiTruncatedIrisTextureEvidence {
    if !ellipse.center.0.is_finite()
        || !ellipse.center.1.is_finite()
        || !ellipse.major_radius.is_finite()
        || !ellipse.minor_radius.is_finite()
        || ellipse.major_radius < 12.0
        || ellipse.minor_radius < 8.0
    {
        return RoiTruncatedIrisTextureEvidence::default();
    }
    let axis_cosine = ellipse.angle.cos();
    let axis_sine = ellipse.angle.sin();
    let canonical = |x: f64, y: f64| {
        let dx = x - ellipse.center.0;
        let dy = y - ellipse.center.1;
        let local_x = axis_cosine * dx + axis_sine * dy;
        let local_y = -axis_sine * dx + axis_cosine * dy;
        (
            local_x / ellipse.major_radius.max(1.0),
            local_y / ellipse.minor_radius.max(1.0),
            dx,
            dy,
        )
    };
    // Work inside the visible iris rather than on the predicted limbus. Iris
    // striations are approximately radial curves, so their Canny normals are
    // mostly transverse to the center-to-sample direction. This rejects the
    // circular pupil/limbus edges while retaining native-resolution texture
    // which can move coherently with the proposed eye.
    let in_iris = |x: f64, y: f64| {
        let (canonical_x, canonical_y, _, _) = canonical(x, y);
        (0.38..=0.88).contains(&canonical_x.hypot(canonical_y))
    };
    let mut evidence = RoiTruncatedIrisTextureEvidence::default();
    let mut radial_sectors = [false; 16];
    let mut transverse_sectors = [false; 16];
    let mut alignment_weight = 0.0;
    let mut alignment_sum = 0.0;
    let mut alignment_squared_sum = 0.0;
    for edge in &overlay.edges {
        let (canonical_x, canonical_y, dx, dy) = canonical(edge.x as f64, edge.y as f64);
        let radius = canonical_x.hypot(canonical_y);
        if !(0.38..=0.88).contains(&radius) {
            continue;
        }
        // A strongly different upper-eye motion is explicit evidence against
        // this Canny sample belonging to iris texture. Keep it visible in the
        // diagnostic overlay, but do not let it satisfy integer topology
        // gates. Intermediate agreement remains an analog vote below.
        if edge.iris_motion_consistency < 0.45 {
            evidence.motion_shadow_edges += 1;
            continue;
        }
        evidence.interior_edges += 1;
        let image_radius = dx.hypot(dy).max(1.0e-9);
        let gradient_length = f64::from(edge.gradient_x)
            .hypot(f64::from(edge.gradient_y))
            .max(1.0e-9);
        let radial_alignment = ((dx * edge.gradient_x as f64 + dy * edge.gradient_y as f64)
            / (image_radius * gradient_length))
            .abs()
            .clamp(0.0, 1.0);
        let weight = f64::from(edge.strength).clamp(0.35, 2.5).sqrt()
            * f64::from(edge.iris_motion_consistency)
                .clamp(0.05, 1.0)
                .sqrt();
        alignment_weight += weight;
        alignment_sum += radial_alignment * weight;
        alignment_squared_sum += radial_alignment * radial_alignment * weight;
        let phase = canonical_y
            .atan2(canonical_x)
            .rem_euclid(std::f64::consts::TAU);
        let sector = (phase / std::f64::consts::TAU * radial_sectors.len() as f64).floor() as usize;
        let sector = sector.min(radial_sectors.len() - 1);
        if radial_alignment >= 0.86 {
            evidence.radial_edges += 1;
            radial_sectors[sector] = true;
        }
        if radial_alignment <= 0.34 {
            evidence.transverse_edges += 1;
            transverse_sectors[sector] = true;
        }
    }
    evidence.radial_sectors = radial_sectors.iter().filter(|present| **present).count();
    evidence.transverse_sectors = transverse_sectors
        .iter()
        .filter(|present| **present)
        .count();
    if alignment_weight > 1.0e-9 {
        evidence.mean_radial_alignment = alignment_sum / alignment_weight;
        // E[cos(2 theta)] is zero for isotropic gradients, +1 for concentric
        // iris arcs (radial normals), and -1 for radial iris fibers
        // (transverse normals). Its magnitude is the useful eye-specific cue;
        // either sign is valid iris texture.
        evidence.radial_orientation_bias = 2.0 * alignment_squared_sum / alignment_weight - 1.0;
        evidence.polar_orientation_anisotropy = evidence.radial_orientation_bias.abs();
    }
    evidence.provisional_features = overlay
        .provisional_features
        .iter()
        .filter(|point| in_iris(point.0 as f64, point.1 as f64))
        .count();
    evidence.persistent_features = overlay
        .trails
        .iter()
        .filter(|trail| trail.object == motion_layer && trail.layer_evidence)
        .filter_map(|trail| trail.points.last())
        .filter(|point| in_iris(point.x as f64, point.y as f64))
        .count();
    evidence
}

/// A recently admitted Driving road may keep the bounded Canny bank aimed
/// through a short clipped/occluded interval. The road is only a geometric
/// prediction: temporally promoted native RAW patches and organized
/// affine-polar edge structure must corroborate it again in the current
/// frame before it can seed another full topology lap.
fn driving_trusted_canny_continuation_seed(
    trusted: Option<raw_motion_octrees::IrisEllipseSeed>,
    texture: Option<RoiTruncatedIrisTextureEvidence>,
) -> Option<DrivingAffinePose> {
    let seed = trusted?;
    texture?
        .authorizes_bounded_topology_probe()
        .then_some(DrivingAffinePose {
            center: seed.center,
            major_radius: seed.major_radius,
            minor_radius: seed.minor_radius,
            angle: seed.angle,
        })
        .filter(|pose| driving_pose_has_plausible_limbus_projection(*pose))
}

/// Consume only the anatomy-corroborated projected-globe publication.  The
/// green-after-cyan fixed point is an independent 2-D motion diagnostic and
/// must never become a gaze origin merely because its algebraic solver locked.
fn published_projected_globe_projection(
    coupled: raw_motion_octrees::CoupledMotionStatus,
) -> (Option<(f64, f64)>, Option<(f64, f64)>) {
    let globe = coupled.projected_globe;
    if !globe.publishable {
        return (None, None);
    }
    let pivot = globe.projected_pivot.and_then(|point| {
        let point = (point[0] as f64, point[1] as f64);
        (point.0.is_finite() && point.1.is_finite()).then_some(point)
    });
    let pole = globe.projected_pole.and_then(|vector| {
        let vector = (vector[0] as f64, vector[1] as f64);
        (vector.0.is_finite() && vector.1.is_finite()).then_some(vector)
    });
    match (pivot, pole) {
        (Some(pivot), Some(pole)) => (Some(pivot), Some(pole)),
        _ => (None, None),
    }
}

#[derive(Clone)]
struct EyeFrame {
    eye_id: u32,
    sequence: u64,
    timestamp_ns: u64,
    segmentation_mode: SegmentationMode,
    sensor_x: u32,
    sensor_y: u32,
    /// Exact resident sensor window which produced this transmitted eye
    /// slice. Keeping it with the frame prevents a later ROI command from
    /// making the presentation minimap describe the wrong capture geometry.
    sensor_window: (u32, u32, u32, u32),
    width: usize,
    height: usize,
    quad_color: Arc<Vec<u32>>,
    raw_color: Arc<Vec<u32>>,
    quad_luma: Arc<Vec<u32>>,
    raw_luma: Arc<Vec<u32>>,
    canny: Arc<Vec<u32>>,
    specular_map: Arc<Vec<u32>>,
    cross_polarized: Arc<Vec<u32>>,
    diffuse: Arc<Vec<u32>>,
    specular_motion_compensated: bool,
    edge_map_variant: EdgeMapVariant,
    focus_score: f64,
    focus_points: usize,
    focus_eye_basin_valid: bool,
    focus_anatomy_valid: bool,
    /// Acquired semantic/local-reckoning identity for this exact presented
    /// frame. A geometrically self-consistent carried conic is not sufficient
    /// to draw a globe after the eye-presence lease has expired.
    eye_identity_present: bool,
    motion_score: f64,
    focus_center: Option<(f64, f64)>,
    projected_rotation_center: Option<(f64, f64)>,
    projected_rotation_center_z: Option<f64>,
    projected_gaze_pole: Option<(f64, f64)>,
    projected_sphere_radius: Option<f64>,
    /// UI-only geometry injected into a clone immediately before drawing.
    /// Receiver/tracker frames always keep this empty/false, so a held pivot
    /// cannot become fresh anatomical evidence.
    presentation_contact_boundary: Arc<Vec<(f64, f64)>>,
    presentation_pivot_direct: bool,
    presentation_pivot_held: bool,
    presentation_pivot_held_frames: u64,
    /// Presentation-only virtual beam.  It consumes admitted sphere geometry
    /// but never changes segmentation, tracking, or the projected gaze model.
    eye_laser_enabled: bool,
    detected_gaze_feature: Option<(f64, f64)>,
    surface_gaze: Option<SurfaceGazeSample>,
    /// Presentation-only surface solve. Unlike `surface_gaze`, this may use
    /// Driving's exact-current-frame perimeter refit while the full topology
    /// worker is between admissions. It never enters mouse, ray-origin,
    /// segmentation, or pupil state.
    virtual_contact_surface_gaze: Option<SurfaceGazeSample>,
    motion_octrees: Arc<raw_motion_octrees::MotionOctreeOverlay>,
    /// Exact-current-frame red-opponent Canny lines on bright scleral
    /// material. This overlay deliberately contains no iris/pupil geometry.
    sclera_red_canny: Arc<raw_sclera_red_canny::ScleraRedCannyOverlay>,
    inner_iris_points: Arc<Vec<(f64, f64)>>,
    /// Qualified nested-polar pupil hypothesis. Orange perimeter and green
    /// supporting fragment markers are presentation-only during rollout;
    /// the legacy complete-ring publication path remains independently gated.
    pupil_polar_points: Arc<Vec<(f64, f64)>>,
    pupil_polar_slice_points: Arc<Vec<(f64, f64)>>,
    /// Optional diagnostic-only concentric pupil-size guides. These are drawn
    /// over the lossless ROI and never feed tracking or segmentation.
    pupil_size_reticle: Option<PupilRadiusReticle>,
    /// Optional diagnostic-only iris/limbus radius support projected into the
    /// same lossless ROI. U publishes this together with the pupil guides.
    iris_radius_reticle: Option<IrisRadiusReticle>,
    size_reticle_mode: SizeReticleMode,
    /// A complete Driving road measured in this frame but held by the
    /// temporal trust gate. These points are presentation-only: they must not
    /// enter pupil/gaze geometry or train the radius posterior.
    driving_diagnostic_points: Arc<Vec<(f64, f64)>>,
    driving_diagnostic_pupil: Option<(f64, f64)>,
    /// Exact native-RAW perimeter rows used by the current Driving result.
    /// Green/orange points are direct measurements; pink points identify the
    /// conic-filled occlusion rows so they cannot be mistaken for image edges.
    driving_limbus_edge_points: Arc<Vec<DrivingLimbusEdgePoint>>,
    /// Sensor timestamp of the RAW allocation sampled for the points above.
    /// Rendering has a hard equality gate against `timestamp_ns`; this makes
    /// cross-frame evidence presentation impossible even if a future caller
    /// accidentally passes through an asynchronous result.
    driving_limbus_edge_source_timestamp_ns: Option<u64>,
    /// Dashed proposal for a directly observed limbus arc whose remaining
    /// conic is censored by the RAW ROI. Presentation/reframe only: these
    /// points never enter gaze, cursor, or radius-posterior geometry.
    roi_truncated_limbus_points: Arc<Vec<(f64, f64)>>,
    outer_iris_evidence_points: Arc<Vec<(f64, f64)>>,
    outer_iris_occluded_points: Arc<Vec<(f64, f64)>>,
    outer_iris_veto_points: Arc<Vec<(f64, f64)>>,
    outer_iris_points: Arc<Vec<(f64, f64)>>,
    upper_eyelid_points: Arc<Vec<(f64, f64)>>,
    lower_eyelid_points: Arc<Vec<(f64, f64)>>,
    upper_eyelid_fold_points: Arc<Vec<(f64, f64)>>,
    lower_eyelid_fold_points: Arc<Vec<(f64, f64)>>,
    upper_eyelash_points: Arc<Vec<(f64, f64)>>,
    lower_eyelash_points: Arc<Vec<(f64, f64)>>,
    upper_eyelid_status: raw_iris_focus::EyelidObservationStatus,
    lower_eyelid_status: raw_iris_focus::EyelidObservationStatus,
    upper_limbus_clearance_px: Option<f64>,
    lower_limbus_clearance_px: Option<f64>,
}

#[derive(Clone)]
struct RejectionCapture {
    sequence: u64,
    timestamp_ns: u64,
    sensor_x: u32,
    sensor_y: u32,
    width: usize,
    height: usize,
    pixels: Arc<Vec<u32>>,
    focus_score: f64,
    focus_points: usize,
    eye_basin_valid: bool,
    focus_center: Option<(f64, f64)>,
}

impl From<&EyeFrame> for RejectionCapture {
    fn from(frame: &EyeFrame) -> Self {
        Self {
            sequence: frame.sequence,
            timestamp_ns: frame.timestamp_ns,
            sensor_x: frame.sensor_x,
            sensor_y: frame.sensor_y,
            width: frame.width,
            height: frame.height,
            pixels: Arc::clone(&frame.quad_color),
            focus_score: frame.focus_score,
            focus_points: frame.focus_points,
            eye_basin_valid: frame.focus_eye_basin_valid,
            focus_center: frame.focus_center,
        }
    }
}

