fn auto_exposure_meter_raw10(raw: &[u16]) -> u16 {
    let mut histogram = [0u32; 1_024];
    let mut samples = 0u32;
    // A deterministic sparse histogram is ample for the very low-bandwidth
    // controller and avoids letting one specular pixel drive exposure.
    for &value in raw.iter().step_by(16) {
        histogram[value.min(1_023) as usize] += 1;
        samples += 1;
    }
    let threshold = samples.saturating_mul(9).div_ceil(10);
    let mut cumulative = 0u32;
    for (value, count) in histogram.into_iter().enumerate() {
        cumulative += count;
        if cumulative >= threshold {
            return value as u16;
        }
    }
    0
}

