    #[test]
    fn temporal_feature_center_gate_rejects_conic_teleport_against_its_own_layer() {
        let mut gate = TemporalFeatureLimbusCenterGate::default();
        let first = gate
            .observe_frame(
                100_000_000,
                (4_728, 1_714),
                (384, 256),
                Some(((250.33, 136.67), 114.33)),
                None,
                true,
            )
            .unwrap();
        assert!(!first.checked);
        assert!(first.admissible);

        let second = gate
            .observe_frame(
                200_000_000,
                (4_728, 1_714),
                (384, 256),
                Some(((194.93, 128.48), 117.95)),
                Some(reliable_feature_motion([9.75, 3.85])),
                true,
            )
            .unwrap();
        assert!(second.checked);
        assert!(!second.admissible);
        assert!(second.innovation_px > 60.0, "{second:?}");
        assert!(second.innovation_px > second.maximum_innovation_px);
        assert_eq!(gate.last_admitted.unwrap().timestamp_ns, 100_000_000);
    }

    #[test]
    fn temporal_feature_center_gate_carries_motion_without_learning_rejected_anatomy() {
        let mut gate = TemporalFeatureLimbusCenterGate::default();
        gate.observe_frame(
            100_000_000,
            (4_000, 1_700),
            (384, 256),
            Some(((100.0, 100.0), 90.0)),
            None,
            true,
        );
        let rejected_semantics = gate
            .observe_frame(
                200_000_000,
                (4_000, 1_700),
                (384, 256),
                Some(((125.0, 100.0), 90.0)),
                Some(reliable_feature_motion([0.0, 0.0])),
                false,
            )
            .unwrap();
        assert!(rejected_semantics.checked);
        assert!(rejected_semantics.admissible);
        assert_eq!(gate.last_admitted.unwrap().timestamp_ns, 100_000_000);

        let next = gate
            .observe_frame(
                300_000_000,
                (4_000, 1_700),
                (384, 256),
                Some(((160.0, 100.0), 90.0)),
                Some(reliable_feature_motion([0.0, 0.0])),
                true,
            )
            .unwrap();
        assert!(
            next.checked,
            "the motion prediction must survive a rejected conic"
        );
        assert!(!next.admissible, "rejected anatomy must not drag the prior");
        assert!(next.innovation_px > next.maximum_innovation_px);
        assert_eq!(gate.last_admitted.unwrap().timestamp_ns, 100_000_000);
    }

