    #[test]
    fn native_material_gate_requires_an_observable_bilateral_current_frame_road() {
        // Reviewed true low-certainty frame 906 is intentionally just above
        // all three weak floors.
        assert!(!native_material_topology_cues_decisive_veto(
            0.109, 0.073, 0.077, 0.099,
        ));
        // Reviewed off-eye frame 6143 found one very bright skin side but no
        // opposite sclera; frame 4933 found no limbus step at all.
        assert!(native_material_topology_cues_decisive_veto(
            0.179, 0.240, 0.883, 0.057,
        ));
        assert!(native_material_topology_cues_decisive_veto(
            0.195, 0.000, 0.123, 0.656,
        ));
        assert!(!native_material_topology_cues_decisive_veto(
            0.24, 0.31, 0.36, 0.39,
        ));
        assert!(native_material_topology_cues_decisive_veto(
            0.16, 0.17, 0.05, 0.58,
        ));

        assert!(!native_material_topology_admissible(None, None));
        let valid = semantic_test_material_probe(0.109, 0.073, 0.077, 0.099);
        assert!(native_material_topology_admissible(Some(valid), None));
        let reversed_horizon = DrivingPupilHorizonEvaluation {
            score: 0.34,
            left_transition: -0.103,
            right_transition: 0.277,
            left_observed: true,
            right_observed: true,
            pupil_canonical: (0.29, -0.21),
        };
        assert!(!native_material_topology_admissible(
            Some(semantic_test_material_probe(0.288, 0.093, 0.326, 0.260)),
            Some(reversed_horizon),
        ));
    }

    #[test]
    fn native_specular_gate_separates_reviewed_external_and_censored_failures() {
        let evidence = |contained_z, contained_contrast, external_z, external_contrast| {
            Some(NativeSpecularContainmentEvidence {
                contained_z,
                contained_contrast,
                external_z,
                external_contrast,
            })
        };
        // Reviewed frame 823: its lateral horizon is censored and no cohesive
        // highlight belongs to the proposed affine disk.
        assert!(!native_specular_containment_admissible(
            evidence(2.78, 40.0, 3.31, 43.0),
            false,
        ));
        // Reviewed frame 1946 is likewise horizon-censored, but its current
        // RAW frame independently contains a cohesive corneal highlight.
        assert!(native_specular_containment_admissible(
            evidence(3.97, 183.0, 3.55, 52.0),
            false,
        ));
        // Reviewed frame 5405 places the dominant cohesive highlight outside
        // its proposed skin ellipse.
        assert!(!native_specular_containment_admissible(
            evidence(3.18, 60.0, 4.69, 303.0),
            true,
        ));
        // A lid/sclera peak may have a higher standardized z score without
        // being the dominant glint. The much stronger contained contrast in
        // reviewed frame 1042 preserves the real iris.
        assert!(native_specular_containment_admissible(
            evidence(4.17, 165.0, 6.53, 74.0),
            true,
        ));
    }

