    #[test]
    fn temporal_feature_semantics_reject_same_scale_wrong_projected_conic_shape() {
        let mut candidate = semantic_test_feature_candidate();
        candidate.major_radius = 100.0;
        candidate.minor_radius = 70.0;
        candidate.radius = (candidate.major_radius * candidate.minor_radius).sqrt();
        candidate.angle = 0.0;
        let seed = raw_motion_octrees::IrisEllipseSeed {
            center: candidate.center,
            major_radius: 95.0,
            minor_radius: 95.0,
            // A circle's angle is undefined; the tensor comparison must not
            // turn that harmless parameter into orientation evidence.
            angle: 1.1,
        };
        let assessment = temporal_feature_limbus_semantic_assessment(
            Some(&candidate),
            Some(seed),
            None,
            Some(semantic_test_texture(TEMPORAL_FEATURE_MIN_ANNULAR_TRACKS)),
            Some(semantic_test_material_probe(0.35, 0.20, 0.18, 0.22)),
            None,
            false,
            false,
            None,
            TEMPORAL_FEATURE_MIN_LAYER_TRACKS,
        );
        assert!(assessment.seed_radius_log_error < TEMPORAL_FEATURE_MAX_SEED_RADIUS_LOG_ERROR);
        assert!(
            assessment.seed_area_radius_log_error < TEMPORAL_FEATURE_MAX_SEED_AREA_RADIUS_LOG_ERROR
        );
        assert!(
            assessment.seed_normalized_shape_disagreement
                > TEMPORAL_FEATURE_MAX_SEED_NORMALIZED_SHAPE_DISAGREEMENT
        );
        assert!(!assessment.admissible, "{assessment:?}");
        assert_eq!(assessment.reason, "seed-projected-shape-disagreement");
    }

