    #[test]
    fn driving_limbus_edge_evidence_preserves_selected_raw_rows_and_roi_translation() {
        let mut strip = raw_iris_focus::LimbusPerimeterStrip {
            samples: vec![
                raw_iris_focus::LimbusPerimeterDriveSample {
                    driven_point: (12.125, 23.625),
                    transition_score: 0.20,
                    ..raw_iris_focus::LimbusPerimeterDriveSample::default()
                },
                raw_iris_focus::LimbusPerimeterDriveSample {
                    driven_point: (18.375, 29.125),
                    transition_score: -0.10,
                    ..raw_iris_focus::LimbusPerimeterDriveSample::default()
                },
                raw_iris_focus::LimbusPerimeterDriveSample {
                    driven_point: (30.0, 31.0),
                    transition_score: 0.30,
                    inferred_occlusion: true,
                    ..raw_iris_focus::LimbusPerimeterDriveSample::default()
                },
            ],
            conic_projected_rows: vec![false, false, true],
            ..raw_iris_focus::LimbusPerimeterStrip::default()
        };
        // The explicit strip selection owns model/direct identity even if a
        // sample's fallback flag disagrees.
        strip.samples[2].inferred_occlusion = false;
        let evidence = DrivingLimbusEdgeEvidence::from_strip(&strip);
        let points = evidence.points().collect::<Vec<_>>();
        assert_eq!(points.len(), 3);
        assert_eq!(points[0].kind, DrivingLimbusEdgeKind::DirectSupport);
        assert_eq!(points[1].kind, DrivingLimbusEdgeKind::DirectCounterEvidence);
        assert_eq!(points[2].kind, DrivingLimbusEdgeKind::ProjectedConic);
        assert!((points[0].x - 12.125).abs() <= 0.125);
        assert!((points[0].y - 23.625).abs() <= 0.125);

        let translated = evidence
            .translated((-4.5, 2.25))
            .points()
            .collect::<Vec<_>>();
        assert!((translated[0].x - (points[0].x - 4.5)).abs() < 1.0e-12);
        assert!((translated[0].y - (points[0].y + 2.25)).abs() < 1.0e-12);
        assert_eq!(translated[0].kind, points[0].kind);
    }

