    fn synthetic_context(shift: (i32, i32)) -> ContextFrame {
        let width = CONTEXT_WIDTH as usize;
        let height = CONTEXT_HEIGHT as usize;
        let scale = (
            SENSOR_WIDTH as i32 / CONTEXT_WIDTH as i32,
            FINE_SENSOR_WINDOW_HEIGHT as i32 / CONTEXT_HEIGHT as i32,
        );
        let centers = [(85i32, 16i32), (315i32, 16i32)];
        let mut pixels = vec![0u16; width * height];
        for y in 0..height as i32 {
            for x in 0..width as i32 {
                let source_x = x - shift.0;
                let source_y = y - shift.1;
                let in_eye = centers.iter().any(|center| {
                    (source_x - center.0).abs() <= 14 && (source_y - center.1).abs() <= 14
                });
                if in_eye {
                    let pattern = ((source_x * 37 + source_y * 19 + source_x * source_y * 3)
                        .rem_euclid(700)
                        + 120) as u16;
                    pixels[y as usize * width + x as usize] = pattern;
                }
            }
        }
        ContextFrame {
            origin: (0, 2000),
            width,
            height,
            scale,
            eye_size: (384, 256),
            anchors: [(1168, 2128), (4848, 2128)],
            pixels,
        }
    }

    fn synthetic_tracker() -> RawRoiTracker {
        let config = Config {
            camera: String::new(),
            vcm: String::new(),
            control: PathBuf::new(),
            model_streams: Vec::new(),
            origin: (0, 2000),
            eyes: [(1168, 2128), (4848, 2128)],
            eye_size: (384, 256),
            window_size: (SENSOR_WIDTH, FINE_SENSOR_WINDOW_HEIGHT),
            record: None,
            tracking: None,
            autofocus_armed: false,
            focus_eye: 0,
            focus_eye_auto: true,
            segmentation: SegmentationMode::Native,
            rough_pupil_center: RoughPupilCenterMode::IrisGuided,
            driving_submode: DrivingSubmode::Normal,
            global_capture_format: GlobalCaptureFormat::Raw10,
            sam31_model: PathBuf::new(),
        };
        let mut tracker = RawRoiTracker::new(&config);
        let mut anchor = synthetic_context((0, 0));
        anchor.pixels = normalize_context_pixels(anchor.pixels);
        tracker.context_anchor = Some(anchor.clone());
        tracker.context_previous = Some(anchor);
        tracker.context_bootstrap = false;
        tracker.context_failures = 0;
        tracker.context_lock = true;
        tracker.context_identity_present = [true; 2];
        tracker
    }

