    #[test]
    fn partial_limbus_gap_is_measured_on_the_clipped_image_side() {
        use raw_iris_focus::EyelidObservationStatus::{Observed, RoiClipped};

        let pose = DrivingAffinePose {
            center: (192.0, 128.0),
            major_radius: 70.0,
            minor_radius: 55.0,
            angle: 0.0,
        };
        let proposal = DrivingMultibankLimbusProposal {
            pose,
            evidence: DrivingMultibankLimbusEvidence::default(),
        };
        let mut material = DrivingLimbusMaterialEvidence::default();
        for sector in 0..24 {
            material.sector_visible_samples[sector] = 1;
            material.sector_persistent_mean[sector] = 0.5;
        }
        for sector in [4usize, 5, 6, 7, 8] {
            material.sector_persistent_mean[sector] = 0.1;
        }
        for sector in [16usize, 17, 18, 19, 20] {
            material.sector_persistent_mean[sector] = 0.9;
        }
        let mut scene = raw_iris_focus::EyelidNautilusScene::default();
        scene.upper_status = Observed;
        scene.lower_status = RoiClipped;
        let lower_gap = driving_partial_limbus_rank_features(
            proposal,
            material,
            pose,
            Some(pose.center),
            (0, 0),
            Some((&scene, (0, 0))),
        );
        assert!((lower_gap.expected_lid_gap - 0.9).abs() < 1.0e-9);

        scene.upper_status = RoiClipped;
        scene.lower_status = Observed;
        let upper_gap = driving_partial_limbus_rank_features(
            proposal,
            material,
            pose,
            Some(pose.center),
            (0, 0),
            Some((&scene, (0, 0))),
        );
        assert!((upper_gap.expected_lid_gap - 0.1).abs() < 1.0e-9);
    }

    #[test]
    fn clipped_lid_tightens_centering_without_biasing_past_center() {
        let mut tracker = synthetic_tracker();
        tracker.last_command = Instant::now();
        let before = tracker.absolute;
        for timestamp_ns in 1..=5 {
            tracker
                .observe_verified_fine_center(
                    0,
                    timestamp_ns,
                    (before[0].0 as u32, before[0].1 as u32),
                    (384, 256),
                    (192.0, 140.0),
                    true,
                )
                .unwrap();
        }

        assert_eq!(tracker.absolute[0], (before[0].0, before[0].1 + 12));
        assert_eq!(tracker.absolute[1], before[1]);
        assert!(tracker.positions_dirty);

        let centered = tracker.absolute;
        tracker.positions_dirty = false;
        for timestamp_ns in 6..=10 {
            tracker
                .observe_verified_fine_center(
                    0,
                    timestamp_ns,
                    (centered[0].0 as u32, centered[0].1 as u32),
                    (384, 256),
                    (192.0, 128.0),
                    true,
                )
                .unwrap();
            assert_eq!(tracker.absolute, centered);
        }
    }

