    #[test]
    fn roi_censored_recovery_does_not_integrate_a_repeating_local_texture_circle() {
        let mut tracker = synthetic_tracker();
        tracker.context_identity_present = [false; 2];
        tracker.valid_seen = [false; 2];
        tracker.last_command = Instant::now();
        let initial = tracker.absolute;
        for timestamp_ns in 1..=ROI_CENSORED_CENTER_MIN_SAMPLES as u64 {
            tracker
                .observe_roi_censored_limbus(
                    0,
                    timestamp_ns,
                    (initial[0].0 as u32, initial[0].1 as u32),
                    (384, 256),
                    reviewed_partial_observation(),
                )
                .unwrap();
        }
        let first_move = tracker.absolute;
        assert_ne!(first_move, initial);

        // Model the camera accepting that first move, then expose the same
        // crop-local false circle again. A real stationary eye would have
        // moved closer to the ROI center by the applied correction; unchanged
        // local offset is evidence that the detector is following texture.
        tracker.positions_dirty = false;
        for timestamp_ns in 5..=4 + ROI_CENSORED_CENTER_MIN_SAMPLES as u64 {
            tracker
                .observe_roi_censored_limbus(
                    0,
                    timestamp_ns,
                    (first_move[0].0 as u32, first_move[0].1 as u32),
                    (384, 256),
                    reviewed_partial_observation(),
                )
                .unwrap();
        }
        assert_eq!(tracker.absolute, first_move);
        assert!(!tracker.positions_dirty);
    }

