    #[test]
    fn distinct_driving_results_recenter_only_the_camera_side_slice() {
        let mut tracker = synthetic_tracker();
        tracker.context_identity_present = [false; 2];
        tracker.valid_seen = [false; 2];
        tracker.invalid_frames[0] = 12;
        // Keep the unit test below the command debounce so it exercises the
        // absolute-coordinate decision without opening the synthetic VCM
        // address.  Production applies the same dirty position after 250 ms.
        tracker.last_command = Instant::now();
        let before = tracker.absolute;
        for timestamp_ns in 1..=4 {
            assert!(tracker
                .observe_verified_fine_center(
                    0,
                    timestamp_ns,
                    (before[0].0 as u32, before[0].1 as u32),
                    (384, 256),
                    (250.0, 180.0),
                    false,
                )
                .unwrap()
                .is_none());
            assert_eq!(tracker.absolute, before);
        }
        assert!(tracker.valid_seen[0]);
        assert_eq!(tracker.invalid_frames[0], 0);
        tracker
            .observe_verified_fine_center(
                0,
                5,
                (before[0].0 as u32, before[0].1 as u32),
                (384, 256),
                (250.0, 180.0),
                false,
            )
            .unwrap();
        assert_eq!(tracker.absolute[0], (before[0].0 + 60, before[0].1 + 52));
        assert_eq!(tracker.absolute[1], before[1]);
        assert_eq!(tracker.origin, (0, 2000));
        assert!(tracker.positions_dirty);
    }

