    #[test]
    fn rolling_verified_sensor_center_requires_a_new_basin_majority() {
        let mut tracker = synthetic_tracker();
        tracker.last_command = Instant::now();
        let before = tracker.absolute;
        for timestamp_ns in 1..=5 {
            tracker
                .observe_verified_fine_center(
                    0,
                    timestamp_ns,
                    (before[0].0 as u32, before[0].1 as u32),
                    (384, 256),
                    (250.0, 180.0),
                    false,
                )
                .unwrap();
        }
        let centered = tracker.absolute;
        assert_eq!(tracker.verified_center_history[0].len(), 5);

        // Model completion of the debounced ROI command. The verified values
        // remain absolute sensor coordinates across that camera-side move.
        tracker.positions_dirty = false;
        for timestamp_ns in 6..=9 {
            tracker
                .observe_verified_fine_center(
                    0,
                    timestamp_ns,
                    (centered[0].0 as u32, centered[0].1 as u32),
                    (384, 256),
                    (270.0, 128.0),
                    false,
                )
                .unwrap();
            assert_eq!(tracker.absolute, centered);
        }
        tracker
            .observe_verified_fine_center(
                0,
                10,
                (centered[0].0 as u32, centered[0].1 as u32),
                (384, 256),
                (270.0, 128.0),
                false,
            )
            .unwrap();
        assert_eq!(tracker.absolute[0].0, centered[0].0 + 80);
    }

