    #[test]
    fn autofocus_requires_context_and_the_selected_eye_lock() {
        let config = Config {
            camera: String::new(),
            vcm: String::new(),
            control: PathBuf::new(),
            model_streams: Vec::new(),
            origin: (0, 2000),
            eyes: [(1100, 2064), (1668, 2064)],
            eye_size: (384, 256),
            window_size: (8000, 384),
            record: None,
            tracking: None,
            autofocus_armed: false,
            focus_eye: 1,
            focus_eye_auto: false,
            segmentation: SegmentationMode::Native,
            rough_pupil_center: RoughPupilCenterMode::IrisGuided,
            driving_submode: DrivingSubmode::Normal,
            global_capture_format: GlobalCaptureFormat::Raw10,
            sam31_model: PathBuf::new(),
        };
        let mut tracker = RawRoiTracker::new(&config);
        tracker.valid_seen = [false, true];
        tracker.centered_frames = [0, AUTOFOCUS_CENTER_LOCK_FRAMES];
        assert!(!tracker.ready_for_autofocus(1));

        tracker.context_lock = true;
        tracker.context_identity_present = [true; 2];
        assert!(tracker.ready_for_autofocus(1));
        assert!(!tracker.ready_for_autofocus(0));

        tracker.centered_frames[1] -= 1;
        assert!(!tracker.ready_for_autofocus(1));

        tracker.invalid_frames[1] = 5;
        tracker.centered_frames[1] += 1;
        assert!(!tracker.ready_for_autofocus(1));
    }

