    #[test]
    fn driving_misses_do_not_renew_the_wall_clock_presence_lease() {
        let acquired_at = Instant::now();
        let hypothesis = semantic_test_material_probe(0.72, 0.62, 0.65, 0.64);
        let mut tracker = DrivingSegmentationTracker {
            pose: Some(hypothesis.pose),
            last_sensor_origin: Some((3_900, 3_076)),
            last_observed: Some(acquired_at),
            admission_streak: DRIVING_ADMISSION_FRAMES,
            last_scored: Some(hypothesis),
            ..DrivingSegmentationTracker::default()
        };

        // This deliberately exceeds the relocation-probe frame threshold.
        // High FPS may schedule more recovery attempts but must not shorten or
        // renew the acquired identity's wall-clock lifetime.
        for miss in 1..=DRIVING_RELOCATION_PROBE_AFTER_MISSES + 4 {
            assert!(tracker.hold_proven_road_after_miss(
                acquired_at + Duration::from_millis(20 * miss as u64),
                (3_900, 3_076),
            ));
            assert_eq!(tracker.last_observed, Some(acquired_at));
        }
        assert!(!tracker.hold_proven_road_after_miss(
            acquired_at + INVALID_EYE_GEOMETRY_PRESENCE_LEASE,
            (3_900, 3_076),
        ));
        assert!(tracker.pose.is_none());
        assert!(tracker.last_scored.is_none());
    }

