    #[test]
    fn pupil_center_health_has_one_calibration_grace_then_a_hard_1250ms_deadline() {
        let start = Instant::now();
        assert!(!session_focus_health_ready(
            true,
            false,
            start + ROUGH_FOCUS_SESSION_TIMEOUT - Duration::from_nanos(1),
            start + ROUGH_FOCUS_SESSION_TIMEOUT,
        ));
        assert!(session_focus_health_ready(
            true,
            false,
            start + ROUGH_FOCUS_SESSION_TIMEOUT,
            start + ROUGH_FOCUS_SESSION_TIMEOUT,
        ));
        assert!(!session_focus_health_ready(
            false,
            false,
            start + ROUGH_FOCUS_SESSION_TIMEOUT,
            start + ROUGH_FOCUS_SESSION_TIMEOUT,
        ));
        assert!(!session_focus_health_ready(
            true,
            true,
            start + ROUGH_FOCUS_SESSION_TIMEOUT,
            start + ROUGH_FOCUS_SESSION_TIMEOUT,
        ));
        let mut health = PupilCenterHealth::default();
        health
            .observe(start + Duration::from_secs(10), false, false)
            .unwrap();
        assert!(!health.armed());

        health.observe(start, true, false).unwrap();
        assert!(health.armed());
        health
            .observe(start + PUPIL_CENTER_HEALTH_TIMEOUT, true, false)
            .unwrap();
        assert_eq!(
            health
                .observe(
                    start + PUPIL_CENTER_HEALTH_TIMEOUT + Duration::from_nanos(1),
                    true,
                    false,
                )
                .unwrap_err(),
            PUPIL_CENTER_HEALTH_TIMEOUT + Duration::from_nanos(1),
        );

        health
            .observe(start + Duration::from_secs(2), true, true)
            .unwrap();
        health
            .observe(
                start + Duration::from_secs(2) + PUPIL_CENTER_HEALTH_TIMEOUT,
                true,
                false,
            )
            .unwrap();
        assert!(health.confirmed_within(
            start + Duration::from_secs(2) + PUPIL_CENTER_SEMANTIC_HOLD,
            PUPIL_CENTER_SEMANTIC_HOLD,
        ));
        assert!(!health.confirmed_within(
            start + Duration::from_secs(2) + PUPIL_CENTER_SEMANTIC_HOLD + Duration::from_nanos(1),
            PUPIL_CENTER_SEMANTIC_HOLD,
        ));
    }

    #[test]
    fn pupil_center_health_deadline_restarts_after_camera_automation_handoff() {
        let start = Instant::now();
        let mut health = PupilCenterHealth::default();
        health.observe(start, true, true).unwrap();
        let tracking_resumed = start + Duration::from_secs(4);
        health.defer_until_tracking(tracking_resumed);
        assert!(health.armed());
        assert!(!health.confirmed_within(tracking_resumed, Duration::from_secs(1)));
        health
            .observe(tracking_resumed + PUPIL_CENTER_HEALTH_TIMEOUT, true, false)
            .unwrap();
        assert!(health
            .observe(
                tracking_resumed + PUPIL_CENTER_HEALTH_TIMEOUT + Duration::from_nanos(1),
                true,
                false,
            )
            .is_err());
    }

