        for _ in 0..CONTEXT_FAILURE_FRAMES * 2 {
            tracker
                .observe_context(
                    (0, 2000),
                    (CONTEXT_WIDTH as usize, CONTEXT_HEIGHT as usize),
                    blank.clone(),
                    false,
                    false,
                    0,
                )
                .unwrap();
        }
