    #[test]
    fn coarse_focus_requires_falloff_beyond_an_interior_peak() {
        let bracketed = vec![
            (384, 70.0),
            (416, 88.0),
            (448, 115.0),
            (480, 92.0),
            (512, 72.0),
        ];
        assert!(focus_curve_bracketed(&bracketed, (448, 115.0)));

        let boundary_peak = vec![(384, 70.0), (416, 88.0), (448, 115.0)];
        assert!(!focus_curve_bracketed(&boundary_peak, (448, 115.0)));

        let no_right_falloff = vec![(384, 70.0), (416, 115.0), (448, 114.0)];
        assert!(!focus_curve_bracketed(&no_right_falloff, (416, 115.0)));

        let rising_right = vec![
            (500, 103.0),
            (564, 101.0),
            (628, 114.0),
            (692, 140.0),
            (756, 151.0),
        ];
        assert_eq!(
            next_unbracketed_focus_position(&rising_right, (756, 151.0), 64),
            Some(820),
        );
        let at_limit = vec![(864, 110.0), (928, 130.0), (992, 150.0)];
        assert_eq!(
            next_unbracketed_focus_position(&at_limit, (992, 150.0), 64),
            None,
        );
    }

