    #[test]
    fn fast_local_focus_selects_only_a_clear_directional_gain() {
        let (baseline, spread) = stable_focus_baseline(&[99.0, 100.0, 101.0]).unwrap();
        let lower =
            choose_fast_local_focus(512, baseline, spread, &[(504, 132.0), (520, 82.0)]).unwrap();
        assert_eq!(lower.position, 504);
        assert_eq!(lower.direction, "lower-dac");

        // Probe order is intentionally irrelevant because live cycles
        // alternate it to avoid a systematic early/late bias.
        let higher =
            choose_fast_local_focus(512, baseline, spread, &[(520, 128.0), (504, 78.0)]).unwrap();
        assert_eq!(higher.position, 520);
        assert_eq!(higher.direction, "higher-dac");

        let flat =
            choose_fast_local_focus(512, baseline, spread, &[(504, 101.0), (520, 99.0)]).unwrap();
        assert_eq!(flat.position, 512);
        assert_eq!(flat.direction, "hold");
    }

