    #[test]
    fn duplicate_reacquisition_waits_for_fine_validation_handoff() {
        let started_at = Instant::now();
        let retry_at = started_at + MEDIAPIPE_FINE_SETTLE_AFTER_RELOCATION;

        assert!(camera_automation_self_interrupt(0, started_at, retry_at));
        assert!(!camera_automation_self_interrupt(1, started_at, retry_at));
        assert!(!camera_automation_self_interrupt(0, retry_at, retry_at));

        let mut wait = None;
        assert!(queue_camera_automation_wait(
            &mut wait,
            started_at,
            retry_at,
            "first coarse request",
        ));
        assert!(!queue_camera_automation_wait(
            &mut wait,
            started_at + Duration::from_millis(100),
            retry_at + Duration::from_secs(30),
            "tracker requested another coarse scan",
        ));
        assert_eq!(wait.as_ref().unwrap().release_at, retry_at);
        assert_eq!(wait.as_ref().unwrap().requests, 2);
        assert_eq!(
            poll_camera_automation_wait(&mut wait, retry_at - Duration::from_millis(1)),
            CameraAutomationWaitPoll::Waiting,
        );
        assert!(wait.is_some());
        assert_eq!(
            poll_camera_automation_wait(&mut wait, retry_at),
            CameraAutomationWaitPoll::Reacquire(
                "tracker requested another coarse scan".to_string()
            ),
        );
        assert!(wait.is_none());
        assert_eq!(
            poll_camera_automation_wait(&mut wait, retry_at),
            CameraAutomationWaitPoll::Idle,
        );
    }

    #[test]
    fn rejection_capture_persists_exact_unique_frame_and_reason() {
        let directory = std::env::temp_dir().join(format!(
            "buttercup-rejection-test-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos(),
        ));
        fs::create_dir_all(&directory).unwrap();
        let capture = RejectionCapture {
            sequence: 42,
            timestamp_ns: 99,
            sensor_x: 100,
            sensor_y: 200,
            width: 2,
            height: 1,
            pixels: Arc::new(vec![0x0011_2233, 0x0044_5566]),
            focus_score: 12.5,
            focus_points: 7,
            eye_basin_valid: true,
            focus_center: Some((0.25, 0.75)),
        };
        let mut keys = [None, None];
        let mut count = 0;
        let path = save_rejection_capture(
            &directory,
            1,
            &capture,
            "selected eye lost",
            &mut keys,
            &mut count,
        )
        .unwrap()
        .unwrap();

        assert!(path.is_file());
        let metadata = fs::read_to_string(path.with_extension("json")).unwrap();
        assert!(metadata.contains("selected eye lost"));
        assert!(metadata.contains("\"sequence\": 42"));
        assert!(save_rejection_capture(
            &directory,
            1,
            &capture,
            "duplicate",
            &mut keys,
            &mut count,
        )
        .unwrap()
        .is_none());
        assert_eq!(count, 1);
        fs::remove_dir_all(directory).unwrap();
    }

