    #[test]
    fn raw_packet_queue_covers_the_bounded_semantic_reacquisition_budget() {
        // Each shared exposure contributes two eye packets plus occasional
        // context/telemetry packets. Keep enough bounded headroom for the
        // measured 2.52-second semantic result without permitting an
        // indefinitely slow tracking consumer.
        assert!(RawPacketReader::QUEUE_PACKETS >= 42 * 2 * 3);
        assert!(RawPacketReader::QUEUE_PACKETS <= 512);
    }

    #[test]
    fn repeated_manual_camera_steps_are_bounded_and_idempotent_at_endpoints() {
        assert_eq!(
            manual_exposure_step_target(AUTO_EXPOSURE_MIN_LINES, -64),
            None
        );
        assert_eq!(
            manual_exposure_step_target(MANUAL_EXPOSURE_MAX_LINES, 64),
            None
        );
        assert_eq!(
            manual_exposure_step_target(1_000, i32::MIN),
            Some(AUTO_EXPOSURE_MIN_LINES)
        );
        assert_eq!(
            manual_exposure_step_target(1_000, i32::MAX),
            Some(MANUAL_EXPOSURE_MAX_LINES)
        );

        assert_eq!(bounded_manual_focus_step(VCM_MIN_POSITION, -64), None);
        assert_eq!(bounded_manual_focus_step(VCM_MAX_POSITION, 64), None);
        assert_eq!(
            bounded_manual_focus_step(VCM_MIN_POSITION + 10, i16::MIN),
            Some(-10)
        );
        assert_eq!(
            bounded_manual_focus_step(VCM_MAX_POSITION - 10, i16::MAX),
            Some(10)
        );
    }

