    #[test]
    fn published_pupil_reticle_follows_the_common_raw_boundary_not_the_rough_seed() {
        let support = PupilSizeReticle {
            center: (40.0, 45.0),
            projection_center: (50.0, 50.0),
            lower_fronto_parallel_radius_px: 10.0,
            upper_fronto_parallel_radius_px: 20.0,
            preferred_lower_fronto_parallel_radius_px: None,
            preferred_upper_fronto_parallel_radius_px: None,
            estimated_fronto_parallel_radius_px: None,
            reference_limbus_fronto_parallel_radius_px:
                FrontoParallelCircleRadiusPx::from_projected_circular_limbus_axes(40.0, 40.0)
                    .unwrap(),
            projection_minor_to_major: 0.7,
            projection_angle: 0.1,
            projection_source: PupilProjectionSource::SelectedIris,
            support_source: PupilSizeSupportSource::LimbusFractionThresholds,
            scale_bucket: FrontoParallelScaleBucket::from_radius(40.0).unwrap(),
            temporal_scale_matched: false,
            temporal_observations: 0,
            temporal_fractional_half_width: None,
            recomputed_this_frame: true,
            frozen: false,
        };
        let missing = raw_iris_focus::InnerIrisBoundary {
            center: (55.0, 60.0),
            ..raw_iris_focus::InnerIrisBoundary::default()
        };
        assert_eq!(
            pupil_size_reticle_for_publication(Some(support), &missing)
                .unwrap()
                .center,
            support.center,
        );

        let accepted = raw_iris_focus::InnerIrisBoundary {
            center: (55.0, 60.0),
            points: vec![raw_iris_focus::InnerIrisPoint {
                x: 55.0,
                y: 60.0,
                score: 1.0,
            }],
            ..raw_iris_focus::InnerIrisBoundary::default()
        };
        let published = pupil_size_reticle_for_publication(Some(support), &accepted).unwrap();
        assert_eq!(published.center, accepted.center);
        // Y may move the published/search center after the common RAW solve,
        // but the G-owned limbus geometry remains anchored to its own fit.
        assert_eq!(published.projection_center, support.projection_center);
        assert_eq!(
            published.lower_fronto_parallel_radius_px,
            support.lower_fronto_parallel_radius_px
        );
        assert_eq!(
            published.upper_fronto_parallel_radius_px,
            support.upper_fronto_parallel_radius_px
        );
    }

