    #[test]
    fn iris_radius_reticle_preserves_frontoparallel_support_and_uses_limbus_projection() {
        let support = raw_iris_focus::FrontoParallelLimbusRadiusPrior::from_hard_support(
            45.0,
            40.0,
            50.0,
            raw_iris_focus::FrontoParallelLimbusRadiusPriorSource::OperatorHardLimits,
        )
        .unwrap();
        let projection = PupilProjectionReference::from_axes(
            (62.0, 48.0),
            45.0,
            27.0,
            0.25,
            PupilProjectionSource::SelectedIris,
        )
        .unwrap();
        let reticle = iris_radius_reticle_for_publication(
            Some(support),
            Some(projection),
            SizeReticleMode::ProjectedFollow,
            (128, 96),
        )
        .unwrap();
        assert_eq!(reticle.center, projection.center);
        assert_eq!(reticle.minimum_fronto_parallel_radius_px, 40.0);
        assert_eq!(reticle.maximum_fronto_parallel_radius_px, 50.0);
        assert_eq!(reticle.estimated_fronto_parallel_radius_px, 45.0);
        assert!((reticle.projection_minor_to_major - 0.6).abs() < 1.0e-12);
        assert_eq!(reticle.projection_angle, 0.25);
        assert!(!reticle.nominal_cold_start);

        let centered = iris_radius_reticle_for_publication(
            Some(support),
            Some(projection),
            SizeReticleMode::StaticCentered,
            (128, 96),
        )
        .unwrap();
        assert_eq!(centered.center, (63.5, 47.5));
        assert!((centered.projection_minor_to_major - 0.6).abs() < 1.0e-12);
        assert!(!centered.nominal_cold_start);
    }

