    #[test]
    fn static_reticles_have_a_nominal_cold_start_without_predictions() {
        let iris_reticle = iris_radius_reticle_for_publication(
            None,
            None,
            SizeReticleMode::StaticCentered,
            (384, 256),
        )
        .unwrap();
        assert_eq!(iris_reticle.center, (191.5, 127.5));
        assert!(iris_reticle.nominal_cold_start);
        assert!((iris_reticle.estimated_fronto_parallel_radius_px - 96.0).abs() < 1.0e-12);
        assert!((iris_reticle.minimum_fronto_parallel_radius_px - 76.8).abs() < 1.0e-12);
        assert!((iris_reticle.maximum_fronto_parallel_radius_px - 115.2).abs() < 1.0e-12);

        let pupil_reticle = pupil_size_reticle_for_mode(
            None,
            Some(iris_reticle),
            0.06,
            0.72,
            SizeReticleMode::StaticCentered,
            (384, 256),
        )
        .unwrap();
        assert_eq!(pupil_reticle.center, iris_reticle.center);
        assert!((pupil_reticle.lower_fronto_parallel_radius_px - 5.76).abs() < 1.0e-12);
        assert!((pupil_reticle.upper_fronto_parallel_radius_px - 69.12).abs() < 1.0e-12);

        assert!(iris_radius_reticle_for_publication(
            None,
            None,
            SizeReticleMode::ProjectedFollow,
            (384, 256),
        )
        .is_none());
    }

