    fn test_affine_pupil_boundary_with_raw_classes(
        coherent_rays: &[usize],
        alternative_rays: &[usize],
    ) -> raw_iris_focus::InnerIrisBoundary {
        let center = (100.0, 80.0);
        let radius = 20.0;
        let minor_to_major: f64 = 0.80;
        let ratio_root = (1.0 / minor_to_major).sqrt();
        let major_radius = radius * ratio_root;
        let minor_radius = radius / ratio_root;
        let angle: f64 = 0.23;
        let (axis_sine, axis_cosine) = angle.sin_cos();
        let points = (0..21)
            .map(|ray| {
                let image_angle = std::f64::consts::TAU * ray as f64 / 21.0;
                let (direction_y, direction_x) = image_angle.sin_cos();
                let local_x = axis_cosine * direction_x + axis_sine * direction_y;
                let local_y = -axis_sine * direction_x + axis_cosine * direction_y;
                let unit_image_radius = 1.0
                    / ((local_x / major_radius).powi(2) + (local_y / minor_radius).powi(2)).sqrt();
                let is_coherent = coherent_rays.contains(&ray);
                let is_alternative = alternative_rays.contains(&ray);
                let radius_scale = if is_alternative { 0.65 } else { 1.0 };
                raw_iris_focus::InnerIrisPoint {
                    x: center.0 + direction_x * unit_image_radius * radius_scale,
                    y: center.1 + direction_y * unit_image_radius * radius_scale,
                    score: if is_coherent || is_alternative {
                        0.80
                    } else {
                        0.05
                    },
                }
            })
            .collect();
        raw_iris_focus::InnerIrisBoundary {
            center,
            radius,
            major_radius,
            minor_radius,
            angle,
            points,
            radial_candidates: Vec::new(),
        }
    }

    /// A geometrically self-consistent projected circular pupil for tests
    /// which exercise physical size state. `fronto_parallel_radius` is the
    /// de-affined circle radius; the image ellipse shares the supplied limbus
    /// foreshortening and every point occupies a distinct RAW meridian.
    fn test_supported_affine_pupil_boundary(
        center: (f64, f64),
        fronto_parallel_radius: f64,
        projection_minor_to_major: f64,
        angle: f64,
    ) -> raw_iris_focus::InnerIrisBoundary {
        let major_radius = fronto_parallel_radius;
        let minor_radius = fronto_parallel_radius * projection_minor_to_major;
        let projected_area_radius = (major_radius * minor_radius).sqrt();
        let (axis_sine, axis_cosine) = angle.sin_cos();
        let points = (0..21)
            .map(|step| {
                // The production pupil solver owns image-space meridians,
                // not equally spaced ellipse parameter angles. Intersect a
                // uniformly spaced image ray with the projected ellipse so
                // the fixture cannot collapse into duplicate angular bins.
                let image_angle = std::f64::consts::TAU * step as f64 / 21.0;
                let (direction_y, direction_x) = image_angle.sin_cos();
                let local_direction_x = axis_cosine * direction_x + axis_sine * direction_y;
                let local_direction_y = -axis_sine * direction_x + axis_cosine * direction_y;
                let image_radius = 1.0
                    / ((local_direction_x / major_radius).powi(2)
                        + (local_direction_y / minor_radius).powi(2))
                    .sqrt();
                raw_iris_focus::InnerIrisPoint {
                    x: center.0 + direction_x * image_radius,
                    y: center.1 + direction_y * image_radius,
                    score: 1.0,
                }
            })
            .collect();
        raw_iris_focus::InnerIrisBoundary {
            center,
            radius: projected_area_radius,
            major_radius,
            minor_radius,
            angle,
            points,
            radial_candidates: Vec::new(),
        }
    }

