    #[test]
    fn gaze_affine_maps_calibrated_features_to_screen_corners() {
        let features = [(-0.8, -0.6), (0.7, -0.5), (0.8, 0.9), (-0.7, 0.8)];
        let targets = [(0.04, 0.04), (0.96, 0.04), (0.96, 0.96), (0.04, 0.96)];
        let transform = fit_gaze_affine(features, targets).unwrap();

        for (feature, target) in features.into_iter().zip(targets) {
            let actual = transform.map(feature);
            assert!((actual.0 - target.0).abs() < 0.08, "{actual:?} {target:?}");
            assert!((actual.1 - target.1).abs() < 0.08, "{actual:?} {target:?}");
        }
    }

