    #[test]
    fn rectified_ellipse_area_is_invariant_to_disk_foreshortening() {
        let front_facing = rectified_ellipse_area_px2(50.0, 50.0).unwrap();
        let tilted = rectified_ellipse_area_px2(50.0, 35.0).unwrap();

        assert!((front_facing - std::f64::consts::PI * 2_500.0).abs() < 1.0e-9);
        assert!((tilted - front_facing).abs() < 1.0e-9);
        let (_, representative) = bucket_surface_area(tilted).unwrap();
        assert!((representative / tilted).ln().abs() <= GAZE_SURFACE_AREA_BUCKET_RATIO.ln());
        assert!(rectified_ellipse_area_px2(50.0, 15.0).is_none());
    }

    #[test]
    fn surface_gaze_tracks_the_conspicuously_close_sign_across_angle_flips() {
        let now = Instant::now();
        let inner = raw_iris_focus::InnerIrisBoundary {
            center: (100.0, 103.0),
            radius: 18.0,
            major_radius: 18.0,
            minor_radius: 17.0,
            angle: 0.0,
            points: vec![raw_iris_focus::InnerIrisPoint::default(); 8],
            radial_candidates: Vec::new(),
        };
        let mut outer = test_outer_boundary((100.0, 100.0), 50.0, 40.0);
        outer.points = vec![raw_iris_focus::OuterIrisPoint::default(); 8];
        let gaze_anchor = detected_gaze_feature(&inner, &outer);
        let mut tracker = SurfaceGazeTracker::default();
        let first = tracker
            .observe(now, (3_000, 1_500), gaze_anchor, &outer)
            .unwrap();

        // The same ellipse is commonly published with an equivalent angle
        // separated by PI. The two candidate near points swap names, but the
        // conspicuously closer point must remain on the same physical side.
        outer.angle += std::f64::consts::PI;
        let second = tracker
            .observe(
                now + Duration::from_millis(100),
                (3_000, 1_500),
                gaze_anchor,
                &outer,
            )
            .unwrap();

        assert_eq!(first.area_bucket, second.area_bucket);
        assert!(first.feature.1 > 0.55);
        assert!(second.feature.1 > 0.55);
        assert!(second.camera_near_point_sensor.1 > 1_600.0);
    }

