    #[test]
    fn driving_pupil_presentation_hold_never_rewrites_measured_evidence() {
        let started = Instant::now();
        let make = |pose: DrivingAffinePose, center: (f64, f64)| {
            let mut hypothesis = semantic_test_material_probe(0.86, 0.82, 0.80, 0.81);
            hypothesis.pose = pose;
            hypothesis.seed_pose = pose;
            hypothesis.pupil_score = 0.90;
            hypothesis.pupil_enclosure = 0.90;
            hypothesis.pupil_margin = 0.80;
            hypothesis.pupil_horizon = 0.50;
            hypothesis.pupil_projected_area_radius_px = Some(18.0);
            hypothesis.pupil_canonical = driving_canonical_point(pose, center).unwrap();
            hypothesis.pupil_boundary_canonical = None;
            hypothesis
        };
        let first_pose = DrivingAffinePose {
            center: (240.0, 110.0),
            major_radius: 95.0,
            minor_radius: 82.0,
            angle: -2.75,
        };
        let first_radius = driving_fronto_parallel_radius_px(first_pose).unwrap();
        let first_center = (
            first_pose.center.0 - 0.12 * first_radius,
            first_pose.center.1 - 0.16 * first_radius,
        );
        let first = make(first_pose, first_center);
        let next_pose = DrivingAffinePose {
            center: (247.0, 106.0),
            angle: first_pose.angle + std::f64::consts::FRAC_PI_2,
            ..first_pose
        };
        let next_radius = driving_fronto_parallel_radius_px(next_pose).unwrap();
        let remote_center = (
            next_pose.center.0 + 0.15 * next_radius,
            next_pose.center.1 + 0.12 * next_radius,
        );
        let remote = make(next_pose, remote_center);
        let rough = raw_iris_focus::BorderFocus {
            pupil_hint: Some(remote_center),
            pupil_hint_score: 0.90,
            ..raw_iris_focus::BorderFocus::default()
        };

        let mut held = DrivingSegmentationTracker::default();
        assert_eq!(
            held.stabilize_published_pupil_center_on_current_outer_limbus(
                started, None, first, false,
            ),
            first
        );
        held.last_scored = Some(remote);
        let presentation = held.stabilize_published_pupil_center_on_current_outer_limbus(
            started + Duration::from_millis(10),
            Some(&rough),
            remote,
            false,
        );
        let transported = (
            next_pose.center.0 - 0.12 * next_radius,
            next_pose.center.1 - 0.16 * next_radius,
        );
        let shown = presentation.pupil_boundary_center();
        assert!((shown.0 - transported.0).abs() < 1.0e-9, "{shown:?}");
        assert!((shown.1 - transported.1).abs() < 1.0e-9, "{shown:?}");
        assert_eq!(
            held.last_scored,
            Some(remote),
            "presentation-only imputation must not mutate measured tracker evidence"
        );
        assert!(held.last_pupil_center_temporally_imputed);

        let mut saccade = DrivingSegmentationTracker::default();
        let _ = saccade
            .stabilize_published_pupil_center_on_current_outer_limbus(started, None, first, false);
        let moved = saccade.stabilize_published_pupil_center_on_current_outer_limbus(
            started + Duration::from_millis(10),
            Some(&rough),
            remote,
            true,
        );
        let accepted = moved.pupil_boundary_center();
        assert!(
            (accepted.0 - remote_center.0).abs() < 1.0e-9,
            "{accepted:?}"
        );
        assert!(
            (accepted.1 - remote_center.1).abs() < 1.0e-9,
            "{accepted:?}"
        );
        assert!(!saccade.last_pupil_center_temporally_imputed);
        let accepted_relative = saccade.stabilized_pupil_outer_relative.unwrap();
        assert!((accepted_relative.0 - 0.15).abs() < 1.0e-12);
        assert!((accepted_relative.1 - 0.12).abs() < 1.0e-12);
    }

    #[test]
    fn driving_cold_start_bank_preserves_eye_votes_across_an_interleaved_alias() {
        let started = Instant::now();
        let origin = (4_148, 3_934);
        let make = |center: (f64, f64), radius: f64| {
            let mut hypothesis = semantic_test_material_probe(0.82, 0.80, 0.78, 0.79);
            hypothesis.pose = DrivingAffinePose {
                center,
                major_radius: radius,
                minor_radius: radius * 0.86,
                angle: -2.70,
            };
            hypothesis.seed_pose = hypothesis.pose;
            hypothesis.pupil_canonical = (0.05, -0.10);
            hypothesis.pupil_boundary_canonical = None;
            hypothesis
        };
        let eye_first = make((248.0, 103.0), 95.0);
        let eye_second = make((286.0, 101.0), 94.0);
        let lid_alias = make((107.0, 124.0), 98.0);
        // Each adjacent 38 px translation is feasible for this ~95 px eye,
        // while the complete 76 px displacement deliberately exceeds the
        // frozen-anchor position gate used by the regressed implementation.
        let eye_third = make((324.0, 106.0), 99.0);
        let mut tracker = DrivingSegmentationTracker::default();

        assert!(tracker.observe_cold_start_hypothesis_bank(started, origin, eye_first, 0.90, None,));
        assert_eq!(tracker.admission_streak, 1);
        assert!(tracker.observe_cold_start_hypothesis_bank(
            started + Duration::from_millis(40),
            origin,
            eye_second,
            0.91,
            None,
        ));
        assert_eq!(tracker.admission_streak, 2);

        assert!(tracker.observe_cold_start_hypothesis_bank(
            started + Duration::from_millis(80),
            origin,
            lid_alias,
            0.88,
            None,
        ));
        assert_eq!(tracker.admission_streak, 1);
        assert_eq!(tracker.cold_start_hypothesis_banks.len(), 2);

        assert!(tracker.observe_cold_start_hypothesis_bank(
            started + Duration::from_millis(800),
            origin,
            eye_third,
            0.93,
            None,
        ));
        assert_eq!(tracker.admission_streak, DRIVING_ADMISSION_FRAMES);
        assert_eq!(
            tracker.cold_start_radius_votes.len(),
            DRIVING_ADMISSION_FRAMES
        );
        assert_eq!(tracker.last_scored, Some(eye_third));
        assert_eq!(tracker.pose, None, "a bank consensus is not publication");
    }

    #[test]
    fn driving_provisional_vote_survives_two_missing_raw_frames_without_becoming_a_pose() {
        let started = Instant::now();
        let pose = DrivingAffinePose {
            center: (100.0, 80.0),
            major_radius: 62.0,
            minor_radius: 50.0,
            angle: 0.10,
        };
        let hypothesis = DrivingHypothesis {
            pose,
            seed_pose: pose,
            limbus_edge_evidence: DrivingLimbusEdgeEvidence::default(),
            score: 0.72,
            normal_score: 0.72,
            submode: DrivingSubmode::Normal,
            white_score: 0.65,
            far_sclera_score: 0.66,
            limbus_score: 0.62,
            pupil_score: 0.90,
            pupil_enclosure: 0.88,
            pupil_margin: 0.78,
            pupil_projected_area_radius_px: None,
            pupil_horizon: 0.34,
            through_eye_score: 0.55,
            broad_through_eye_score: 0.55,
            double_sclera_10_deg_score: 0.55,
            double_sclera_10_deg_phase: 0.0,
            double_sclera_10_deg_support: 1.0,
            bilateral_limbus_order: 0.62,
            lower_limbus_direct_visibility: 0.0,
            light_cohesion: 0.82,
            affine_departure_fraction: 0.06,
            affine_departure_ratio: 0.50,
            affine_repair_fraction: 0.70,
            affine_reinforced: false,
            pupil_canonical: (0.05, -0.02),
            pupil_boundary_canonical: None,
            iterations: 4,
            refinement_laps: 2,
        };
        let original_origin = (3_200, 1_600);
        let mut tracker = DrivingSegmentationTracker {
            pose: None,
            last_sensor_origin: Some(original_origin),
            last_observed: Some(started),
            admission_streak: 1,
            last_scored: Some(hypothesis),
            ..DrivingSegmentationTracker::default()
        };
        assert!(tracker.replace_cold_start_radius_vote(hypothesis, 0.90));

        for miss in 1..=DRIVING_MAX_PROVISIONAL_MISSES {
            assert!(tracker.hold_proven_road_after_miss(
                started + Duration::from_millis(miss as u64 * 100),
                (3_240, 1_620),
            ));
            assert_eq!(tracker.pose, None, "a provisional vote must not publish");
            assert_eq!(tracker.last_sensor_origin, Some(original_origin));
            assert_eq!(tracker.last_scored, Some(hypothesis));
            assert_eq!(tracker.admission_streak, 1);
            assert_eq!(tracker.cold_start_radius_votes.len(), 1);
        }
        assert!(!tracker
            .hold_proven_road_after_miss(started + Duration::from_millis(300), (3_240, 1_620),));
        assert_eq!(tracker.pose, None);
        assert_eq!(tracker.last_scored, None);
        assert_eq!(tracker.admission_streak, 0);
        assert!(tracker.cold_start_radius_votes.is_empty());
    }

    #[test]
    fn driving_three_consistent_topology_votes_establish_temporal_limbus_radius_together() {
        let started = Instant::now();
        let base_pose = DrivingAffinePose {
            center: (100.0, 80.0),
            major_radius: 62.0,
            minor_radius: 50.0,
            angle: 0.10,
        };
        let base = DrivingHypothesis {
            pose: base_pose,
            seed_pose: base_pose,
            limbus_edge_evidence: DrivingLimbusEdgeEvidence::default(),
            score: 0.78,
            normal_score: 0.78,
            submode: DrivingSubmode::Normal,
            white_score: 0.70,
            far_sclera_score: 0.71,
            limbus_score: 0.72,
            pupil_score: 0.90,
            pupil_enclosure: 0.88,
            pupil_margin: 0.82,
            pupil_projected_area_radius_px: None,
            pupil_horizon: 0.70,
            through_eye_score: 0.65,
            broad_through_eye_score: 0.65,
            double_sclera_10_deg_score: 0.60,
            double_sclera_10_deg_phase: 0.0,
            double_sclera_10_deg_support: 1.0,
            bilateral_limbus_order: 0.72,
            lower_limbus_direct_visibility: 0.0,
            light_cohesion: 0.82,
            affine_departure_fraction: 0.03,
            affine_departure_ratio: 0.30,
            affine_repair_fraction: 0.82,
            affine_reinforced: true,
            pupil_canonical: (0.05, -0.02),
            pupil_boundary_canonical: None,
            iterations: 4,
            refinement_laps: 2,
        };
        let mut tracker = DrivingSegmentationTracker::default();
        assert_eq!(
            tracker
                .limbus_radius
                .lock()
                .unwrap()
                .begin_frame(started, None),
            None
        );
        assert!(tracker.replace_cold_start_radius_vote(base, 0.90));
        assert!(tracker.push_cold_start_radius_vote(
            DrivingHypothesis {
                pose: DrivingAffinePose {
                    major_radius: 63.0,
                    ..base_pose
                },
                ..base
            },
            0.92,
        ));
        assert!(tracker.push_cold_start_radius_vote(
            DrivingHypothesis {
                pose: DrivingAffinePose {
                    major_radius: 61.0,
                    ..base_pose
                },
                ..base
            },
            0.91,
        ));
        assert!(tracker.establish_limbus_radius_from_cold_start_votes(started));
        let prior = tracker
            .limbus_radius
            .lock()
            .unwrap()
            .begin_frame(started + Duration::from_millis(10), None)
            .expect("three topology-gated votes should establish temporal scale");
        assert_eq!(
            prior.source,
            raw_iris_focus::FrontoParallelLimbusRadiusPriorSource::TemporalRobustMedian
        );
        assert!((prior.estimate_px - 62.0).abs() < 1.0e-9, "{prior:?}");
    }

    #[test]
    fn driving_pairwise_cold_radius_drift_does_not_claim_three_vote_consensus() {
        let started = Instant::now();
        let make_hypothesis = |radius: f64| {
            let mut hypothesis = semantic_test_material_probe(0.82, 0.80, 0.78, 0.79);
            hypothesis.pose.major_radius = radius;
            hypothesis.pose.minor_radius = radius * 0.82;
            hypothesis.seed_pose = hypothesis.pose;
            hypothesis
        };
        let low = make_hypothesis(82.0);
        let middle = make_hypothesis(89.0);
        let high = make_hypothesis(97.0);
        assert!(driving_cold_start_roads_are_consistent(
            low,
            (4_728, 1_714),
            middle,
            (4_728, 1_714),
            None,
        ));
        assert!(driving_cold_start_roads_are_consistent(
            middle,
            (4_728, 1_714),
            high,
            (4_728, 1_714),
            None,
        ));

        let mut tracker = DrivingSegmentationTracker::default();
        assert_eq!(
            tracker
                .limbus_radius
                .lock()
                .unwrap()
                .begin_frame(started, None),
            None
        );
        assert!(tracker.replace_cold_start_radius_vote(low, 0.90));
        assert!(tracker.push_cold_start_radius_vote(middle, 0.92));
        assert!(tracker.push_cold_start_radius_vote(high, 0.91));
        assert!(
            !tracker.establish_limbus_radius_from_cold_start_votes(started),
            "pairwise overlap is not a common three-road physical scale"
        );
        assert_eq!(
            tracker
                .limbus_radius
                .lock()
                .unwrap()
                .established_dynamic_radius_px(),
            None
        );
    }

