    #[test]
    fn local_driving_reckoning_retains_only_a_previously_acquired_eye() {
        let trusted = semantic_test_material_probe(0.90, 0.82, 0.78, 0.76);
        assert!(driving_hypothesis_admissible(trusted));
        let texture = RoiTruncatedIrisTextureEvidence {
            interior_edges: 120,
            radial_edges: 18,
            radial_sectors: 8,
            radial_orientation_bias: 0.12,
            polar_orientation_anisotropy: 0.12,
            persistent_features: 6,
            ..RoiTruncatedIrisTextureEvidence::default()
        };
        let evidence = DrivingLimbusEdgeEvidence {
            count: DRIVING_LIMBUS_EDGE_SAMPLE_COUNT as u8,
            direct_mask: (1u128 << 80) - 1,
            positive_transition_mask: (1u128 << 56) - 1,
            ..DrivingLimbusEdgeEvidence::default()
        };
        let probe = DrivingFrameLocalEdgeProbe {
            pose: trusted.pose,
            evidence,
            elapsed_us: 100,
        };
        let retains = |identity, primary, road, texture, probe| {
            driving_local_reckoning_retains_acquired_eye(
                identity, primary, road, texture, probe, None,
            )
        };

        assert!(retains(
            true,
            false,
            Some(trusted),
            Some(texture),
            Some(probe),
        ));
        assert!(!retains(
            false,
            false,
            Some(trusted),
            Some(texture),
            Some(probe),
        ));
        assert!(!retains(
            true,
            true,
            Some(trusted),
            Some(texture),
            Some(probe),
        ));
        assert!(!retains(true, false, None, Some(texture), Some(probe)));
        assert!(!retains(true, false, Some(trusted), None, Some(probe)));

        let mut self_authorizing_edge = probe;
        self_authorizing_edge.evidence.direct_mask = (1u128 << 96) - 1;
        self_authorizing_edge.evidence.positive_transition_mask = (1u128 << 80) - 1;
        assert!(retains(
            true,
            false,
            Some(trusted),
            None,
            Some(self_authorizing_edge),
        ));

        let mut weak_edge = probe;
        weak_edge.evidence.positive_transition_mask =
            (1u128 << (DRIVING_LOCAL_PRESENCE_MIN_POSITIVE_ROWS - 1)) - 1;
        assert!(!retains(
            true,
            false,
            Some(trusted),
            Some(texture),
            Some(weak_edge),
        ));

        let mut reviewed_no_eye_edge = probe;
        reviewed_no_eye_edge.evidence.direct_mask = (1u128 << 60) - 1;
        reviewed_no_eye_edge.evidence.positive_transition_mask = (1u128 << 50) - 1;
        assert!(!retains(
            true,
            false,
            Some(trusted),
            Some(texture),
            Some(reviewed_no_eye_edge),
        ));

        let mut unrelated_edge = probe;
        unrelated_edge.pose.center.0 += trusted.pose.major_radius * 0.70;
        assert!(!retains(
            true,
            false,
            Some(trusted),
            Some(texture),
            Some(unrelated_edge),
        ));
    }

