    #[test]
    fn e_lock_averages_true_xyz_and_remains_sensor_absolute() {
        let outer_prediction = vec![
            (20.0, 40.0),
            (26.0, 26.0),
            (40.0, 20.0),
            (54.0, 26.0),
            (60.0, 40.0),
            (54.0, 54.0),
            (40.0, 60.0),
            (26.0, 54.0),
        ];
        let mut captured = control_eye_frame(1);
        captured.width = 96;
        captured.height = 96;
        captured.projected_rotation_center = Some((30.0, 50.0));
        captured.projected_gaze_pole = Some((0.0, -10.0));
        captured.outer_iris_points = Arc::new(outer_prediction.clone());

        let mut lock = ray_origin_lock_from_frame(0, &captured).expect("rendered 3D origin");
        assert_eq!(lock.eye, 0);
        assert!((lock.sensor_xyz.0 - 3030.0).abs() < 1.0e-9);
        assert!((lock.sensor_xyz.1 - 2450.0).abs() < 1.0e-9);
        assert!(lock.sensor_xyz.2 < -20.0, "z={}", lock.sensor_xyz.2);
        assert!(
            (lock.sensor_xyz.2.abs() - lock.sphere_radius).abs() > 1.0,
            "Z must not be the globe radius"
        );
        assert_eq!(lock.samples, 1);

        let initial_z = lock.sensor_xyz.2;
        let mut next_frame = captured.clone();
        next_frame.timestamp_ns += 1;
        next_frame.projected_rotation_center = Some((40.0, 60.0));
        assert!(update_ray_origin_running_average(&mut lock, &next_frame));
        assert_eq!(lock.samples, 2);
        assert!((lock.sensor_xyz.0 - 3035.0).abs() < 1.0e-9);
        assert!((lock.sensor_xyz.1 - 2455.0).abs() < 1.0e-9);
        assert!((lock.sensor_xyz.2 - initial_z).abs() < 1.0e-9);
        assert!(!update_ray_origin_running_average(&mut lock, &next_frame));
        assert_eq!(lock.samples, 2, "one frame must contribute only once");

        let mut moved_roi = captured.clone();
        moved_roi.sensor_x += 10;
        moved_roi.sensor_y -= 5;
        moved_roi.projected_rotation_center = Some((80.0, 80.0));
        moved_roi.projected_rotation_center_z = None;
        moved_roi.projected_sphere_radius = None;
        apply_ray_origin_lock(0, &mut moved_roi, lock);

        assert_eq!(moved_roi.projected_rotation_center, Some((25.0, 60.0)));
        assert_eq!(
            moved_roi.projected_rotation_center_z,
            Some(lock.sensor_xyz.2)
        );
        assert_eq!(moved_roi.projected_sphere_radius, Some(lock.sphere_radius));
        let restored_sensor_xyz = (
            moved_roi.sensor_x as f64 + moved_roi.projected_rotation_center.unwrap().0,
            moved_roi.sensor_y as f64 + moved_roi.projected_rotation_center.unwrap().1,
            moved_roi.projected_rotation_center_z.unwrap(),
        );
        assert_eq!(restored_sensor_xyz, lock.sensor_xyz);
    }

    #[test]
    fn published_pivot_is_removed_from_presentation_on_a_weak_frame() {
        let outer_prediction = vec![
            (20.0, 40.0),
            (26.0, 26.0),
            (40.0, 20.0),
            (54.0, 26.0),
            (60.0, 40.0),
            (54.0, 54.0),
            (40.0, 60.0),
            (26.0, 54.0),
        ];
        let mut trusted = control_eye_frame(1);
        trusted.width = 96;
        trusted.height = 96;
        trusted.projected_rotation_center = Some((30.0, 50.0));
        trusted.projected_gaze_pole = Some((0.0, -10.0));
        trusted.outer_iris_points = Arc::new(outer_prediction);
        let mut trusted_motion = raw_motion_octrees::MotionOctreeOverlay::default();
        trusted_motion.coupled_motion.projected_globe.publishable = true;
        trusted_motion
            .coupled_motion
            .projected_globe
            .anatomy_authorized = true;
        trusted.motion_octrees = Arc::new(trusted_motion);

        let mut contact = None;
        assert!(update_presentation_pivot_contact(&mut contact, 0, &trusted));
        let direct = contact.expect("published pivot seeds presentation memory");
        assert_eq!(direct.held_frames, 0);
        assert_eq!(direct.source_timestamp_ns, trusted.timestamp_ns);
        assert!(direct.directly_published);

        let mut weak = trusted.clone();
        weak.timestamp_ns += 1;
        weak.eye_identity_present = false;
        weak.projected_rotation_center = None;
        weak.projected_gaze_pole = None;
        weak.outer_iris_points = Arc::new(Vec::new());
        let mut motion = raw_motion_octrees::MotionOctreeOverlay::default();
        motion.motions[raw_motion_octrees::GENERAL_LAYER] = raw_motion_octrees::SimilarityMotion {
            translation: [3.0, -2.0],
            rotation: 0.0,
            scale_delta: 0.0,
            residual: 1.0,
            support: 4,
        };
        motion.layers[raw_motion_octrees::GENERAL_LAYER].persistent_tracks = 3;
        motion.layers[raw_motion_octrees::GENERAL_LAYER].stable_frames = 2;
        motion.layers[raw_motion_octrees::GENERAL_LAYER].coherence = 0.5;
        weak.motion_octrees = Arc::new(motion);
        assert!(update_presentation_pivot_contact(&mut contact, 0, &weak));
        assert!(
            contact.is_none(),
            "a weak frame must remove the stale presentation-only pivot"
        );
    }

