    #[test]
    fn moving_ring_history_resolves_projected_internal_rotation_center() {
        let expected = (100.0, 80.0);
        let major_radius = 20.0;
        let depth_to_ring_radius = 1.83;
        let started = Instant::now();
        let mut observations = VecDeque::new();
        for index in 0..16 {
            let phi = -0.45 + index as f64 * 0.06;
            let tilt = 0.18 + (index % 5) as f64 * 0.035;
            let normal = (phi.cos(), phi.sin());
            let offset = depth_to_ring_radius * major_radius * tilt;
            observations.push_back(RingPoseObservation {
                captured_at: started + Duration::from_millis(index as u64 * 50),
                center: (
                    expected.0 - offset * normal.0,
                    expected.1 - offset * normal.1,
                ),
                major_radius,
                minor_radius: major_radius * (1.0 - tilt * tilt).sqrt(),
                angle: phi - std::f64::consts::FRAC_PI_2,
            });
        }

        let actual = infer_projected_rotation_center(&observations).unwrap();
        assert!((actual.0 - expected.0).abs() < 0.25, "x={}", actual.0);
        assert!((actual.1 - expected.1).abs() < 0.25, "y={}", actual.1);
    }

