    #[test]
    fn stable_ring_firms_and_holds_an_established_center_and_pole() {
        let now = Instant::now();
        let ring = RingPoseObservation {
            captured_at: now,
            center: (78.0, 57.0),
            major_radius: 20.0,
            minor_radius: 18.0,
            angle: 0.4,
        };
        let expected = ProjectedVisionPose {
            center: (70.0, 60.0),
            pole: (8.0, -3.0),
        };
        let mut history = RotationCenterHistory {
            observations: VecDeque::new(),
            estimate: Some(expected),
            previous_ring: Some(ring),
            stable_frames: ROTATION_POSE_FIRM_START_FRAMES,
        };

        let actual = history
            .observe(
                now + Duration::from_millis(25),
                ring.center,
                ring.major_radius,
                ring.minor_radius,
                ring.angle,
                12.0,
                true,
            )
            .unwrap();

        assert_eq!(actual.center, expected.center);
        assert_eq!(actual.pole, expected.pole);
        assert!(history.stable_frames > ROTATION_POSE_FIRM_START_FRAMES);
    }

    #[test]
    fn temporal_pose_penalty_charges_center_motion_and_pole_rotation() {
        let prior = ProjectedVisionPose {
            center: (70.0, 60.0),
            pole: (8.0, 0.0),
        };
        let unchanged = projected_pose_temporal_penalty(prior, prior, 20.0);
        let translated = projected_pose_temporal_penalty(
            prior,
            ProjectedVisionPose {
                center: (74.0, 60.0),
                pole: (8.0, 0.0),
            },
            20.0,
        );
        let rotated = projected_pose_temporal_penalty(
            prior,
            ProjectedVisionPose {
                center: prior.center,
                pole: (0.0, 8.0),
            },
            20.0,
        );

        assert_eq!(unchanged, 0.0);
        assert!(translated > unchanged);
        assert!(rotated > translated);
    }

    #[test]
    fn outer_iris_radius_changes_at_no_more_than_twenty_percent_per_second() {
        let started = Instant::now();
        let mut contraction = RadiusRateLimiter::default();
        assert_eq!(
            contraction.observe(
                started,
                50.0,
                OUTER_IRIS_MAX_CONTRACTION_PER_SECOND,
                OUTER_IRIS_MAX_EXPANSION_PER_SECOND,
            ),
            50.0
        );
        let contracted = contraction.observe(
            started + Duration::from_millis(25),
            30.0,
            OUTER_IRIS_MAX_CONTRACTION_PER_SECOND,
            OUTER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        assert!((contracted - 49.75).abs() < 1.0e-6, "{contracted}");

        let mut expansion = RadiusRateLimiter::default();
        expansion.observe(
            started,
            50.0,
            OUTER_IRIS_MAX_CONTRACTION_PER_SECOND,
            OUTER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        let expanded = expansion.observe(
            started + Duration::from_millis(25),
            70.0,
            OUTER_IRIS_MAX_CONTRACTION_PER_SECOND,
            OUTER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        assert!((expanded - 50.25).abs() < 1.0e-6, "{expanded}");
    }

    #[test]
    fn inner_iris_radius_limits_contraction_and_expansion() {
        let started = Instant::now();
        let mut contraction = RadiusRateLimiter::default();
        contraction.observe(
            started,
            20.0,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        let contracted = contraction.observe(
            started + Duration::from_millis(100),
            10.0,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        assert!((contracted - 19.81).abs() < 1.0e-6, "{contracted}");
        assert!(
            1.0 - (contracted / 20.0).powi(2) < 0.02,
            "reconstructed area changed too far: {contracted}",
        );

        let mut expansion = RadiusRateLimiter::default();
        expansion.observe(
            started,
            20.0,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        let expanded = expansion.observe(
            started + Duration::from_millis(100),
            30.0,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        assert!((expanded - 20.19).abs() < 1.0e-6, "{expanded}");
        assert!(
            (expanded / 20.0).powi(2) - 1.0 < 0.02,
            "reconstructed area changed too far: {expanded}",
        );
    }

    #[test]
    fn pupil_search_support_is_the_same_interval_as_publication_rate_limiting() {
        let started = Instant::now();
        let mut trajectory = RadiusRateLimiter::default();
        trajectory.observe(
            started,
            0.30,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        let now = started + Duration::from_millis(100);
        let support = trajectory
            .kinematic_support(
                now,
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
            )
            .unwrap();
        assert!((support.estimate - 0.30).abs() < 1.0e-12);
        assert!((support.minimum - 0.29715).abs() < 1.0e-12);
        assert!((support.maximum - 0.30285).abs() < 1.0e-12);
        assert_eq!(
            trajectory.constrain(
                now,
                0.50,
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
            ),
            support.maximum,
        );
        let delayed = trajectory
            .kinematic_support(
                started + Duration::from_millis(500),
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
            )
            .unwrap();
        assert_eq!(
            delayed, support,
            "a missing frame cannot widen one publication step"
        );
        assert!(trajectory
            .kinematic_support(
                started + Duration::from_millis(1_001),
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
            )
            .is_none());
    }

    #[test]
    fn half_pixel_pupil_probe_cannot_escape_the_post_affine_area_support() {
        let pose = DrivingAffinePose {
            center: (240.0, 150.0),
            major_radius: 120.0,
            minor_radius: 90.0,
            angle: 0.37,
        };
        let projected_limbus_radius = (pose.major_radius * pose.minor_radius).sqrt();
        let support = RadiusKinematicSupport {
            estimate: 0.18,
            minimum: 0.1785,
            maximum: 0.1815,
        };
        let oversized_probe = projected_limbus_radius * 0.19;
        let constrained =
            constrain_driving_pupil_radius_to_ratio_support(pose, oversized_probe, support)
                .unwrap();
        assert!((constrained / projected_limbus_radius - support.maximum).abs() < 1.0e-12);
        let reconstructed_area_ratio = (constrained / projected_limbus_radius).powi(2);
        assert!((reconstructed_area_ratio - support.maximum.powi(2)).abs() < 1.0e-12);
    }

    #[test]
    fn published_pupil_history_learns_only_the_reachable_native_measurement() {
        let started = Instant::now();
        let mut tracker = DrivingSegmentationTracker {
            pupil_ratio_proven: true,
            last_pupil_margin_native_measurement_ratio: Some(0.50),
            ..DrivingSegmentationTracker::default()
        };
        tracker.pupil_ratio_trajectory.observe(
            started,
            0.30,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        let mut displayed = semantic_test_material_probe(0.90, 0.90, 0.90, 0.90);
        let limbus_radius = (displayed.pose.major_radius * displayed.pose.minor_radius).sqrt();
        displayed.pupil_projected_area_radius_px = Some(limbus_radius * 0.30);

        assert!(
            tracker.record_published_pupil_ratio(started + Duration::from_millis(100), displayed,)
        );
        let learned = tracker
            .pupil_ratio_published_log_history
            .back()
            .copied()
            .unwrap()
            .exp();
        assert!((learned - 0.30285).abs() < 1.0e-12, "{learned}");
        assert!((driving_pupil_to_limbus_radius_ratio(displayed).unwrap() - 0.30).abs() < 1.0e-12);
    }

    #[test]
    fn stale_provisional_pupil_branch_cannot_replace_published_ratio_history() {
        let started = Instant::now();
        let mut tracker = DrivingSegmentationTracker {
            pupil_ratio_proven: true,
            pupil_ratio_published_log_history: VecDeque::from([0.30f64.ln()]),
            pupil_ratio_last_published: Some(started),
            ..DrivingSegmentationTracker::default()
        };
        tracker.pupil_ratio_trajectory.observe(
            started,
            0.30,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );

        let stale = started + Duration::from_millis(1_100);
        tracker.begin_pupil_ratio_frame(stale);
        let support = tracker.active_pupil_ratio_support.unwrap();
        assert!((support.estimate - 0.30).abs() < 1.0e-12);
        assert!((support.minimum - 0.24).abs() < 1.0e-12);
        assert!((support.maximum - 0.36).abs() < 1.0e-12);

        // Even if a provisional path accidentally restarts the continuous
        // limiter on a tiny glint, the next frozen frame intersects it with
        // published history and returns to the physical support.
        tracker.pupil_ratio_trajectory.observe(
            stale,
            0.15,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        tracker.begin_pupil_ratio_frame(stale + Duration::from_millis(100));
        let recovered = tracker.active_pupil_ratio_support.unwrap();
        assert!((recovered.estimate - 0.30).abs() < 1.0e-12);
        assert_eq!(tracker.pupil_ratio_published_log_history.len(), 1);
    }

    #[test]
    fn provisional_pupil_bridge_keeps_nearby_scale_but_clamps_far_texture_rings() {
        let now = Instant::now();
        let make_tracker = || DrivingSegmentationTracker {
            pupil_ratio_proven: true,
            pupil_ratio_published_log_history: VecDeque::from([0.30f64.ln()]),
            pupil_ratio_last_published: Some(now),
            ..DrivingSegmentationTracker::default()
        };
        let make_hypothesis = |ratio: f64| {
            let mut hypothesis = semantic_test_material_probe(0.90, 0.90, 0.90, 0.90);
            hypothesis.pupil_projected_area_radius_px =
                Some(ratio * (hypothesis.pose.major_radius * hypothesis.pose.minor_radius).sqrt());
            hypothesis
        };

        let mut nearby = make_tracker();
        assert!(nearby.bridge_provisional_pupil_ratio_trajectory(now, make_hypothesis(0.33),));
        let nearby_support = nearby
            .pupil_ratio_trajectory
            .kinematic_support(
                now,
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
            )
            .unwrap();
        assert!((nearby_support.estimate - 0.33).abs() < 1.0e-12);

        let mut far = make_tracker();
        assert!(far.bridge_provisional_pupil_ratio_trajectory(now, make_hypothesis(0.42)));
        let far_support = far
            .pupil_ratio_trajectory
            .kinematic_support(
                now,
                INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
                INNER_IRIS_MAX_EXPANSION_PER_SECOND,
            )
            .unwrap();
        assert!((far_support.estimate - 0.30).abs() < 1.0e-12);
        assert_eq!(far.pupil_ratio_published_log_history.len(), 1);
    }

