    #[test]
    fn inner_pupil_rate_limit_is_invariant_to_apparent_image_scale() {
        let started = Instant::now();
        let mut ratio = RadiusRateLimiter::default();
        let first_reference = 50.0;
        let first_radius = 20.0;
        let first = ratio.observe(
            started,
            first_radius / first_reference,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        assert!((first * first_reference - first_radius).abs() < 1.0e-9);

        // A 20% gross scale change enlarges both projected circles. It is not
        // physiological dilation and therefore must pass through unchanged.
        let next_reference = 60.0;
        let next_radius = 24.0;
        let transported = ratio.observe(
            started + Duration::from_millis(20),
            next_radius / next_reference,
            INNER_IRIS_MAX_CONTRACTION_PER_SECOND,
            INNER_IRIS_MAX_EXPANSION_PER_SECOND,
        );
        assert!((transported * next_reference - next_radius).abs() < 1.0e-9);
    }

    #[test]
    fn pupil_size_uses_inverse_affine_area_not_only_the_fitted_major_axis() {
        let started = Instant::now();
        let mut tracker = PupilSizeTracker::default();
        let projection = PupilProjectionReference::from_axes(
            (100.0, 80.0),
            50.0,
            28.0,
            0.7,
            PupilProjectionSource::SelectedIris,
        )
        .unwrap();
        let support = tracker
            .begin_frame(
                started,
                Some((100.0, 80.0)),
                Some(projection),
                true,
                0.08,
                0.72,
            )
            .unwrap();
        let projected = raw_iris_focus::InnerIrisBoundary {
            center: (105.0, 78.0),
            major_radius: 24.0,
            minor_radius: 15.0,
            angle: -0.4,
            radius: (24.0f64 * 15.0).sqrt(),
            points: vec![raw_iris_focus::InnerIrisPoint::default(); 21],
            radial_candidates: Vec::new(),
        };

        let deprojected =
            fronto_parallel_area_equivalent_pupil_radius_px(&projected, Some(support))
                .unwrap()
                .value();
        let expected = (24.0f64 * 15.0 / 0.56).sqrt();
        assert!((deprojected - expected).abs() < 1.0e-12);
        assert_ne!(deprojected, projected.major_radius);
        assert!(
            (std::f64::consts::PI * deprojected * deprojected
                - std::f64::consts::PI * projected.major_radius * projected.minor_radius / 0.56)
                .abs()
                < 1.0e-9
        );
    }

    #[test]
    fn pupil_confidence_uses_limbus_affine_shape_not_image_roundness() {
        let mut tracker = PupilSizeTracker::default();
        let projection = PupilProjectionReference::from_axes(
            (100.0, 80.0),
            50.0,
            28.0,
            0.35,
            PupilProjectionSource::SelectedIris,
        )
        .unwrap();
        let support = tracker
            .begin_frame(
                Instant::now(),
                Some((100.0, 80.0)),
                Some(projection),
                true,
                0.08,
                0.72,
            )
            .unwrap();
        let matching_projection =
            test_supported_affine_pupil_boundary((100.0, 80.0), 24.0, 0.56, 0.35);
        let image_round = test_supported_affine_pupil_boundary(
            (100.0, 80.0),
            (24.0_f64 * 13.44).sqrt(),
            1.0,
            0.0,
        );

        let matching_confidence = pupil_boundary_confidence(&matching_projection, Some(support));
        let round_confidence = pupil_boundary_confidence(&image_round, Some(support));
        assert!(
            matching_confidence > round_confidence + 0.15,
            "matching={matching_confidence} round={round_confidence} support={support:?}"
        );
        assert!((matching_confidence - 1.0).abs() < 1.0e-12);

        let mut one_sided = matching_projection;
        for (index, point) in one_sided.points.iter_mut().enumerate() {
            point.score = if index < 5 { 1.0 } else { 0.0 };
        }
        let one_sided_confidence = pupil_boundary_confidence(&one_sided, Some(support));
        assert!(
            one_sided_confidence < 0.25,
            "a short one-sided RAW fragment became trainable: {one_sided_confidence}"
        );
        let mut outer = test_outer_boundary((100.0, 80.0), 50.0, 28.0);
        outer.points = vec![raw_iris_focus::OuterIrisPoint::default(); 8];
        assert!(detected_gaze_feature(&one_sided, &outer).is_some());
        assert_eq!(
            admitted_pupil_limbus_gaze_anchor(&one_sided, &outer, true, one_sided_confidence,),
            None,
            "a prior-supported pupil with insufficient RAW margin evidence reached gaze state"
        );
    }

    #[test]
    fn pupil_diameter_arc_evidence_distinguishes_fit_from_strong_competing_edges() {
        // Nine rays agree with the displayed diameter, while the remaining
        // twelve find a very strong edge at 65% of that radius. Counting
        // transition strength alone would incorrectly call this a complete
        // ring and teach the larger median to the temporal model.
        let ambiguous = test_affine_pupil_boundary_with_raw_classes(
            &[0, 1, 2, 3, 4, 10, 11, 12, 13],
            &[5, 6, 7, 8, 9, 14, 15, 16, 17, 18, 19, 20],
        );
        let ambiguous_evidence = pupil_diameter_arc_evidence(&ambiguous);
        assert_eq!(ambiguous_evidence.coherent_points, 9);
        assert_eq!(ambiguous_evidence.strong_alternative_points, 12);
        assert!(!ambiguous_evidence.qualified());
        assert!(pupil_boundary_confidence(&ambiguous, None) < 0.25);

        // Two opposing six-ray arcs are sufficient even when the other nine
        // meridians are weak/occluded. This preserves useful partial-framing
        // behavior without letting a single lid or iris-fibre arc qualify.
        let opposed_arcs = test_affine_pupil_boundary_with_raw_classes(
            &[0, 1, 2, 3, 4, 5, 10, 11, 12, 13, 14, 15],
            &[],
        );
        let opposed_evidence = pupil_diameter_arc_evidence(&opposed_arcs);
        assert_eq!(opposed_evidence.coherent_points, 12);
        assert_eq!(opposed_evidence.strong_alternative_points, 0);
        assert!(opposed_evidence.opposed_coherent_points >= 6);
        assert!(opposed_evidence.longest_contiguous_arc_points >= 6);
        assert!(opposed_evidence.qualified());
        assert!(pupil_boundary_confidence(&opposed_arcs, None) >= 0.25);
    }

    #[test]
    fn competing_pupil_edges_cannot_train_or_move_physical_size_state() {
        let started = Instant::now();
        let mut size_tracker = PupilSizeTracker::default();
        let mut radius_limiter = RadiusRateLimiter::default();
        let projection = PupilProjectionReference::from_axes(
            (100.0, 80.0),
            50.0,
            40.0,
            0.23,
            PupilProjectionSource::SelectedIris,
        )
        .unwrap();
        let support = size_tracker
            .begin_frame(
                started,
                Some((100.0, 80.0)),
                Some(projection),
                true,
                0.08,
                0.72,
            )
            .unwrap();
        let mut ambiguous = test_affine_pupil_boundary_with_raw_classes(
            &[0, 1, 2, 3, 4, 10, 11, 12, 13],
            &[5, 6, 7, 8, 9, 14, 15, 16, 17, 18, 19, 20],
        );
        // Pass an intentionally overconfident caller value: the admission
        // contract must independently enforce the RAW-arc qualification.
        let rejected = stabilize_and_observe_pupil_size(
            &mut size_tracker,
            &mut radius_limiter,
            started,
            &mut ambiguous,
            Some(support),
            1.0,
            true,
            PupilEvidenceCondition::fully_reliable(50.0),
        );
        assert!(!rejected.raw_diameter_qualified);
        assert!(!rejected.trajectory_updated);
        assert!(!rejected.trained_posterior);
        assert!(radius_limiter.state.is_none());

        let mut opposed_arcs = test_affine_pupil_boundary_with_raw_classes(
            &[0, 1, 2, 3, 4, 5, 10, 11, 12, 13, 14, 15],
            &[],
        );
        let admitted = stabilize_and_observe_pupil_size(
            &mut size_tracker,
            &mut radius_limiter,
            started + Duration::from_millis(20),
            &mut opposed_arcs,
            Some(support),
            1.0,
            true,
            PupilEvidenceCondition::fully_reliable(50.0),
        );
        assert!(admitted.raw_diameter_qualified);
        assert!(admitted.trajectory_updated);
        assert!(admitted.trained_posterior);
        assert!(radius_limiter.state.is_some());
    }

