    #[test]
    fn control_commands_select_only_the_right_eye_and_queue_absolute_focus() {
        let shared = Arc::new(Mutex::new(SharedState {
            focus_eye: 1,
            ..SharedState::default()
        }));
        let response = handle_control_command("FOCUS EYE RIGHT", &shared);
        assert!(response.contains("subject-right"));
        {
            let mut state = shared.lock().unwrap();
            assert_eq!(state.focus_eye, 0);
            assert!(matches!(
                state.focus_action.take(),
                Some(FocusAction::SelectEye(0))
            ));
        }

        let response = handle_control_command("FOCUS SET 525", &shared);
        assert!(response.contains("\"target\":525"));
        let mut state = shared.lock().unwrap();
        assert!(state.manual_focus);
        assert_eq!(state.focus_target, Some(525));
        assert_eq!(state.focus_settled, Some(false));
        assert!(matches!(
            state.focus_action.take(),
            Some(FocusAction::Set(525))
        ));
        drop(state);

        let response = handle_control_command("REACQUIRE", &shared);
        assert!(response.contains("mediapipe-reacquire"));
        assert_eq!(
            shared.lock().unwrap().reacquire_request.as_deref(),
            Some("local control socket")
        );

        let response = handle_control_command("LINEAR SNAPSHOT", &shared);
        assert!(response.contains("linear-snapshot"));
        assert!(shared.lock().unwrap().linear_snapshot_request);

        let response = handle_control_command("EXPORT PRESENTATION relative.ppm", &shared);
        assert!(response.contains("path must be absolute"));
        let response = handle_control_command(
            "EXPORT PRESENTATION /tmp/buttercup-presentation-test.ppm",
            &shared,
        );
        assert!(response.contains("presentation-export"));
        assert_eq!(
            shared
                .lock()
                .unwrap()
                .presentation_export_request
                .take()
                .as_deref(),
            Some(Path::new("/tmp/buttercup-presentation-test.ppm")),
        );

        let response = handle_control_command("ROI HOLD 4512 4090 5200 4100", &shared);
        assert!(response.contains("roi-hold"));
        let mut state = shared.lock().unwrap();
        assert_eq!(
            state.manual_roi_action.take(),
            Some(ManualRoiAction::Hold([(4512, 4090), (5200, 4100)])),
        );
        drop(state);

        let response = handle_control_command("ROI AUTO", &shared);
        assert!(response.contains("roi-auto"));
        assert_eq!(
            shared.lock().unwrap().manual_roi_action,
            Some(ManualRoiAction::Auto),
        );
    }

    #[test]
    fn r_toggle_freezes_and_resumes_roi_reacquisition_and_radius_state_together() {
        let mut state = SharedState {
            reacquire_request: Some("older request".to_string()),
            iris_radius_bounds_recompute: true,
            pupil_radius_bounds_recompute: true,
            ..SharedState::default()
        };

        assert!(!toggle_mediapipe_reacquisition(&mut state));
        assert!(state.mediapipe_reacquisition_disabled);
        assert!(!state.iris_radius_bounds_recompute);
        assert!(!state.pupil_radius_bounds_recompute);
        assert!(state.reacquire_request.is_none());
        assert!(state
            .reacquire_status
            .as_deref()
            .unwrap()
            .contains("FROZEN"));

        let shared = Arc::new(Mutex::new(state));
        let rejected = handle_control_command("REACQUIRE", &shared);
        assert!(rejected.contains("disabled by the R toggle"));
        let status: serde_json::Value =
            serde_json::from_str(&control_status_json(&shared.lock().unwrap())).unwrap();
        assert_eq!(status["mediapipe_reacquisition_enabled"], false);
        assert_eq!(status["pupil_reticle"]["enabled"], false);
        assert_eq!(status["iris_reticle"]["enabled"], false);

        let mut state = shared.lock().unwrap();
        assert!(toggle_mediapipe_reacquisition(&mut state));
        assert!(!state.mediapipe_reacquisition_disabled);
        assert!(state.iris_radius_bounds_recompute);
        assert!(state.pupil_radius_bounds_recompute);
        assert_eq!(
            state.reacquire_request.as_deref(),
            Some("R hotkey enabled MediaPipe"),
        );
        assert!(state
            .reacquire_status
            .as_deref()
            .unwrap()
            .contains("QUEUED"));
    }

    #[test]
    fn mediapipe_task_authorization_is_transactional_across_r_and_cadence_changes() {
        let now = Instant::now();
        let mut state = SharedState {
            segmentation_mode: SegmentationMode::Native,
            rough_pupil_center_mode: RoughPupilCenterMode::MediaPipeContinuous,
            mediapipe_reacquisition_generation: 41,
            pupil_radius_bounds_recompute: true,
            ..SharedState::default()
        };

        let first_periodic =
            authorize_mediapipe_task(&state, MediaPipeTaskKind::Periodic, now).unwrap();
        assert_eq!(
            first_periodic.reacquisition_generation,
            Some(state.mediapipe_reacquisition_generation)
        );
        assert!(validate_mediapipe_task_authorization(
            &state,
            MediaPipeTaskKind::Periodic,
            first_periodic,
            now,
        )
        .is_ok());

        // A quick off/on cycle must not resurrect a result that began under
        // the old R state, even though reacquisition is enabled again by the
        // time the worker finishes.
        assert!(!toggle_mediapipe_reacquisition(&mut state));
        assert_eq!(state.mediapipe_reacquisition_generation, 42);
        assert!(validate_mediapipe_task_authorization(
            &state,
            MediaPipeTaskKind::Periodic,
            first_periodic,
            now,
        )
        .unwrap_err()
        .contains("R changed"));
        assert!(toggle_mediapipe_reacquisition(&mut state));
        assert_eq!(state.mediapipe_reacquisition_generation, 43);
        assert!(validate_mediapipe_task_authorization(
            &state,
            MediaPipeTaskKind::Periodic,
            first_periodic,
            now,
        )
        .unwrap_err()
        .contains("R changed"));

        let current_periodic =
            authorize_mediapipe_task(&state, MediaPipeTaskKind::Periodic, now).unwrap();
        state.rough_pupil_center_mode = RoughPupilCenterMode::RawFocus;
        assert!(validate_mediapipe_task_authorization(
            &state,
            MediaPipeTaskKind::Periodic,
            current_periodic,
            now,
        )
        .unwrap_err()
        .contains("no longer permits continuous"));

        // Native + a Rust-only center still allows one global lost-lock
        // acquisition, but not a periodic refresh.
        let lost_lock = authorize_mediapipe_task(&state, MediaPipeTaskKind::LostLock, now).unwrap();
        assert!(validate_mediapipe_task_authorization(
            &state,
            MediaPipeTaskKind::LostLock,
            lost_lock,
            now,
        )
        .is_ok());

        state.checkerboard_active = true;
        assert!(
            authorize_mediapipe_task(&state, MediaPipeTaskKind::LostLock, now)
                .unwrap_err()
                .contains("checkerboard")
        );
        state.checkerboard_active = false;
        state.manual_roi_hold = true;
        assert!(
            authorize_mediapipe_task(&state, MediaPipeTaskKind::LostLock, now)
                .unwrap_err()
                .contains("manual ROI hold")
        );
        state.manual_roi_hold = false;
        state.control_lease = Some(ControlLease {
            token: 7,
            owner: "authorization-test".to_string(),
            expires_at: now + Duration::from_secs(1),
        });
        assert!(
            authorize_mediapipe_task(&state, MediaPipeTaskKind::LostLock, now)
                .unwrap_err()
                .contains("external camera transaction")
        );

        // Lossless linear snapshots are explicitly outside R/cadence
        // ownership; checkerboard capture uses this authorization class.
        let linear =
            authorize_mediapipe_task(&state, MediaPipeTaskKind::LinearSnapshot, now).unwrap();
        assert_eq!(linear.reacquisition_generation, None);
        assert!(validate_mediapipe_task_authorization(
            &state,
            MediaPipeTaskKind::LinearSnapshot,
            linear,
            now,
        )
        .is_ok());
    }

    #[test]
    fn rough_center_selection_cannot_override_or_leave_work_behind_the_r_freeze() {
        let mut state = SharedState {
            segmentation_mode: SegmentationMode::Native,
            rough_pupil_center_mode: RoughPupilCenterMode::RawFocus,
            mediapipe_reacquisition_disabled: true,
            mediapipe_reacquisition_generation: 9,
            pupil_radius_bounds_recompute: false,
            pupil_sizing_generation: 7,
            ..SharedState::default()
        };

        set_rough_pupil_center_mode(
            &mut state,
            RoughPupilCenterMode::MediaPipeContinuous,
            "test",
        )
        .unwrap();
        assert!(state.mediapipe_reacquisition_disabled);
        assert_eq!(state.mediapipe_reacquisition_generation, 9);
        assert!(!state.pupil_radius_bounds_recompute);
        assert_eq!(state.pupil_sizing_generation, 7);
        assert!(state.reacquire_request.is_none());
        assert!(state.segmentation_status.contains("HELD BY R"));

        assert!(toggle_mediapipe_reacquisition(&mut state));
        assert!(state.pupil_radius_bounds_recompute);
        assert_eq!(
            state.reacquire_request.as_deref(),
            Some("R hotkey enabled MediaPipe")
        );

        set_rough_pupil_center_mode(&mut state, RoughPupilCenterMode::MediaPipeAcquire, "test")
            .unwrap();
        assert!(state
            .reacquire_request
            .as_deref()
            .is_some_and(|request| request.contains("rough-center mode requires")));
        set_rough_pupil_center_mode(&mut state, RoughPupilCenterMode::RawFocus, "test").unwrap();
        assert!(state.reacquire_request.is_none());
    }

    #[test]
    fn control_transition_status_keeps_iris_center_r_and_sizing_owners_separate() {
        let mut initial = SharedState {
            segmentation_mode: SegmentationMode::Native,
            rough_pupil_center_mode: RoughPupilCenterMode::RawFocus,
            iris_radius_bounds_recompute: true,
            iris_radius_observed_px: Some(60.0),
            pupil_radius_bounds_recompute: true,
            pupil_radius_lower_fraction: DEFAULT_PUPIL_RADIUS_LOWER_FRACTION,
            pupil_radius_upper_fraction: DEFAULT_PUPIL_RADIUS_UPPER_FRACTION,
            ..SharedState::default()
        };
        assert!(!toggle_mediapipe_reacquisition(&mut initial));
        let shared = Arc::new(Mutex::new(initial));
        let json = |response: String| {
            serde_json::from_str::<serde_json::Value>(&response)
                .unwrap_or_else(|error| panic!("invalid control JSON {response}: {error}"))
        };

        // Y may request a MediaPipe center while R remains authoritative. The
        // selected mechanism changes, but it uses the held ROI center and
        // queues no semantic camera work until R is resumed.
        let selected = json(handle_control_command(
            "PUPIL CENTER MEDIAPIPE-CONTINUOUS",
            &shared,
        ));
        assert_eq!(selected["rough_center"], "mediapipe-continuous");
        assert_eq!(selected["rough_center_state"], "held-by-r");
        assert_eq!(selected["effective_mediapipe_cadence"], "disabled-by-r");
        assert_eq!(selected["r_freeze"], true);
        {
            let state = shared.lock().unwrap();
            assert!(state.reacquire_request.is_none());
            assert_eq!(state.iris_segmentation_generation, 1);
            assert_eq!(state.rough_pupil_center_generation, 1);
            assert_eq!(state.pupil_sizing_generation, 1);
        }

        for command in ["STATUS", "SEGMENTATION STATUS", "PUPIL STATUS"] {
            let status = json(handle_control_command(command, &shared));
            if command == "STATUS" {
                assert_eq!(status["r_freeze"], true);
                assert_eq!(status["mediapipe_effective_cadence"], "disabled-by-r");
                assert_eq!(status["segmentation"]["rough_center_state"], "held-by-r");
                assert_eq!(status["iris_radius_bounds"]["recompute"], false);
            } else {
                assert_eq!(status["r_freeze"], true);
                assert_eq!(status["rough_center_state"], "held-by-r");
                assert_eq!(status["effective_mediapipe_cadence"], "disabled-by-r");
            }
        }

        {
            let mut state = shared.lock().unwrap();
            assert!(toggle_mediapipe_reacquisition(&mut state));
            assert_eq!(
                state.reacquire_request.as_deref(),
                Some("R hotkey enabled MediaPipe")
            );
        }
        let resumed = json(handle_control_command("PUPIL STATUS", &shared));
        assert_eq!(resumed["rough_center_state"], "active");
        assert_eq!(resumed["effective_mediapipe_cadence"], "continuous");
        assert_eq!(resumed["r_freeze"], false);
        let resumed_iris = json(handle_control_command("IRIS STATUS", &shared));
        assert_eq!(resumed_iris["radius_bounds"]["recompute"], true);

        // A later Y transition owns its requested one-shot scan. Returning Y
        // to a Rust-only center clears that selector-owned work. G and the
        // sizing controls then advance only their own generations.
        let acquire = json(handle_control_command(
            "PUPIL CENTER MEDIAPIPE-ACQUIRE",
            &shared,
        ));
        assert_eq!(acquire["rough_center"], "mediapipe-acquire");
        assert!(shared
            .lock()
            .unwrap()
            .reacquire_request
            .as_deref()
            .is_some_and(|request| request.contains("rough-center mode requires")));
        let raw = json(handle_control_command("PUPIL CENTER RAW-FOCUS", &shared));
        assert_eq!(raw["rough_center"], "raw-focus");
        assert_eq!(raw["rough_center_state"], "active");
        assert!(shared.lock().unwrap().reacquire_request.is_none());
        let iris = json(handle_control_command("SEGMENTATION SAM31", &shared));
        assert_eq!(iris["mode"], "sam31");
        assert_eq!(iris["rough_pupil_center"], "raw-focus");
        assert!(
            json(handle_control_command("IRIS BOUNDS MINIMUM +", &shared))["ok"]
                .as_bool()
                .unwrap()
        );
        assert!(
            json(handle_control_command("PUPIL RETICLE ON", &shared))["ok"]
                .as_bool()
                .unwrap()
        );

        let state = shared.lock().unwrap();
        assert_eq!(state.iris_segmentation_generation, 4);
        assert_eq!(state.rough_pupil_center_generation, 3);
        assert_eq!(state.pupil_sizing_generation, 3);
        assert_eq!(state.segmentation_mode, SegmentationMode::Sam31);
        assert_eq!(
            state.rough_pupil_center_mode,
            RoughPupilCenterMode::RawFocus
        );
    }

    #[test]
    fn iris_range_controls_and_joint_size_reticles_have_separate_owners() {
        let shared = Arc::new(Mutex::new(SharedState {
            segmentation_mode: SegmentationMode::Driving,
            rough_pupil_center_mode: RoughPupilCenterMode::IrisGuided,
            iris_radius_bounds_recompute: true,
            iris_radius_observed_px: Some(60.0),
            pupil_radius_bounds_recompute: true,
            pupil_radius_lower_fraction: DEFAULT_PUPIL_RADIUS_LOWER_FRACTION,
            pupil_radius_upper_fraction: DEFAULT_PUPIL_RADIUS_UPPER_FRACTION,
            ..SharedState::default()
        }));
        let selected = handle_control_command("PUPIL CENTER DRIVING-TOPOLOGY", &shared);
        assert!(selected.contains("driving-topology"));
        assert_eq!(
            shared.lock().unwrap().rough_pupil_center_mode,
            RoughPupilCenterMode::DrivingTopology,
        );
        let incompatible = handle_control_command("SEGMENTATION NATIVE", &shared);
        assert!(incompatible.contains("incompatible"));

        let lower = handle_control_command("IRIS BOUNDS MINIMUM +", &shared);
        assert!(lower.contains("\"operator_minimum_fronto_parallel_radius_px\":49.000000"));
        let upper = handle_control_command("IRIS BOUNDS MAXIMUM -", &shared);
        assert!(upper.contains("\"operator_maximum_fronto_parallel_radius_px\":71.000000"));
        let iris_generation = {
            let mut state = shared.lock().unwrap();
            state.mediapipe_reacquisition_disabled = true;
            state.iris_segmentation_generation
        };
        let automatic = handle_control_command("IRIS BOUNDS AUTO", &shared);
        assert!(automatic.contains("\"mode\":\"auto\""));
        assert!(automatic.contains("\"r_freeze\":true"));
        {
            let state = shared.lock().unwrap();
            assert!(state.iris_radius_minimum_px.is_none());
            assert!(state.iris_radius_maximum_px.is_none());
            assert!(state.mediapipe_reacquisition_disabled);
            assert_eq!(state.iris_segmentation_generation, iris_generation + 1);
        }
        let iris_generation = shared.lock().unwrap().iris_segmentation_generation;
        let automatic_again = handle_control_command("IRIS BOUNDS AUTO", &shared);
        assert!(automatic_again.contains("\"mode\":\"auto\""));
        assert_eq!(
            shared.lock().unwrap().iris_segmentation_generation,
            iris_generation,
            "idempotent AUTO must not invalidate the same iris state twice"
        );
        let reticle: serde_json::Value =
            serde_json::from_str(&handle_control_command("PUPIL RETICLE ON", &shared)).unwrap();
        assert_eq!(reticle["reticle"], true);
        assert_eq!(reticle["pupil_reticle"], true);
        assert_eq!(reticle["iris_reticle"], true);
        assert_eq!(reticle["mode"], "projected-follow");
        shared.lock().unwrap().pupil_size_runtime = PupilSizeRuntimeStatus {
            rough_center_available: true,
            inner_boundary_locked: true,
            observed_fronto_parallel_radius_px: Some(18.0),
            observation_confidence: 0.75,
            observation_rate_limited: false,
            observation_focus_size_qualified: true,
            observation_limbus_geometry_qualified: true,
            observation_raw_diameter_qualified: true,
            observation_trajectory_updated: true,
            observation_trained_posterior: true,
            evidence_condition: PupilEvidenceCondition::fully_reliable(60.0),
            support: Some(PupilSizeReticle {
                center: (90.0, 70.0),
                projection_center: (90.0, 70.0),
                lower_fronto_parallel_radius_px: 6.0,
                upper_fronto_parallel_radius_px: 42.0,
                preferred_lower_fronto_parallel_radius_px: Some(16.0),
                preferred_upper_fronto_parallel_radius_px: Some(20.0),
                estimated_fronto_parallel_radius_px: Some(18.0),
                reference_limbus_fronto_parallel_radius_px:
                    FrontoParallelCircleRadiusPx::from_projected_circular_limbus_axes(60.0, 60.0)
                        .unwrap(),
                projection_minor_to_major: 0.75,
                projection_angle: 0.2,
                projection_source: PupilProjectionSource::SelectedIris,
                support_source: PupilSizeSupportSource::TemporalPupilRatio,
                scale_bucket: FrontoParallelScaleBucket::from_radius(60.0).unwrap(),
                temporal_scale_matched: true,
                temporal_observations: 5,
                temporal_fractional_half_width: Some(0.11),
                recomputed_this_frame: true,
                frozen: false,
            }),
        };
        let status = handle_control_command("PUPIL STATUS", &shared);
        assert!(status.contains("driving-topology"));
        assert!(status.contains("\"reticle\":true"));
        assert!(status.contains("\"radius_model\":\"fronto-parallel-tilted-circle\""));
        assert!(status.contains("\"rough_center_available\":true"));
        assert!(status.contains("\"observation_rate_limited\":false"));
        assert!(status.contains("\"hard_minimum_fronto_parallel_radius_px\":6.000000"));
        assert!(status.contains("\"preferred_minimum_fronto_parallel_radius_px\":16.000000"));
        assert!(status.contains("\"observation_trained_posterior\":true"));
        assert!(status.contains("\"observation_trajectory_updated\":true"));
        assert!(status.contains("\"observation_limbus_geometry_qualified\":true"));
        assert!(status.contains("\"observation_raw_diameter_qualified\":true"));
        assert!(status.contains("\"projection_center\":[90.000000,70.000000]"));
        let status_json: serde_json::Value =
            serde_json::from_str(&status).expect("pupil status must remain valid JSON");
        assert_eq!(
            status_json["runtime"]["radius_estimator"],
            "inverse-affine-area-equivalent"
        );
        assert_eq!(
            status_json["runtime"]["sample_lattice"],
            "native-raw-coordinates"
        );
        assert_eq!(status_json["runtime"]["source_buffer"], "borrowed-raw10");
        assert!(
            (status_json["runtime"]["observed_fronto_parallel_area_px2"]
                .as_f64()
                .unwrap()
                - std::f64::consts::PI * 18.0 * 18.0)
                .abs()
                < 1.0e-6
        );
        assert_eq!(
            status_json["runtime"]["evidence_condition"]["focus_class"],
            "sharp"
        );
        assert_eq!(
            status_json["runtime"]["evidence_condition"]["spatial_resolution"],
            1.0
        );
        assert_eq!(
            status_json["runtime"]["support"]["temporal_scale_matched"],
            true
        );
        let iris_status: serde_json::Value =
            serde_json::from_str(&handle_control_command("IRIS STATUS", &shared))
                .expect("iris status must remain valid JSON");
        assert_eq!(iris_status["radius_bounds"]["mode"], "auto");
        assert_eq!(iris_status["radius_bounds"]["r_freeze"], true);
        assert_eq!(iris_status["reticle"], true);
        assert_eq!(iris_status["reticle_mode"], "projected-follow");
        let toggled: serde_json::Value =
            serde_json::from_str(&handle_control_command("IRIS RETICLE TOGGLE", &shared)).unwrap();
        assert_eq!(toggled["pupil_reticle"], false);
        assert_eq!(toggled["iris_reticle"], false);
        assert_eq!(toggled["mode"], "off");
    }

