    #[test]
    fn timed_raw_recording_is_bounded_and_requires_an_absolute_path() {
        let shared = Arc::new(Mutex::new(SharedState::default()));
        let relative = handle_control_command("RECORD RAW BOTH 20 relative-recording.tar", &shared);
        assert!(relative.contains("must be absolute"));

        let queued = handle_control_command(
            "RECORD RAW BOTH 20 /tmp/buttercup-timed-recording-test.tar",
            &shared,
        );
        assert!(queued.contains("\"state\":\"queued\""));
        let state = shared.lock().unwrap();
        let request = state.timed_record_request.as_ref().unwrap();
        assert_eq!(request.duration, Duration::from_secs(20));
        assert_eq!(
            request.path,
            PathBuf::from("/tmp/buttercup-timed-recording-test.tar")
        );
        let result = state.timed_record_result.as_ref().unwrap();
        assert_eq!(result.state, "queued");
        assert_eq!(result.duration_ms, 20_000);
    }

    #[test]
    fn raw_bundle_index_preserves_sensor_and_host_clock_domains() {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let output = PathBuf::from(format!(
            "/tmp/buttercup-raw-host-clock-test-{}-{stamp}.tar",
            std::process::id()
        ));
        let config = Config {
            camera: String::new(),
            vcm: String::new(),
            control: PathBuf::new(),
            model_streams: Vec::new(),
            origin: (0, 1500),
            eyes: [(3000, 1600), (4700, 1600)],
            eye_size: (4, 1),
            window_size: (8000, 576),
            record: None,
            tracking: None,
            autofocus_armed: false,
            focus_eye: 0,
            focus_eye_auto: true,
            segmentation: SegmentationMode::Native,
            rough_pupil_center: RoughPupilCenterMode::IrisGuided,
            driving_submode: DrivingSubmode::Normal,
            global_capture_format: GlobalCaptureFormat::Raw10,
            sam31_model: PathBuf::new(),
        };
        let header = PacketHeader {
            kind: PacketKind::Eye(1),
            sequence: 44,
            timestamp_ns: 123_456_789,
            sensor_x: 3012,
            sensor_y: 1616,
            width: 4,
            height: 1,
            stride: 5,
            payload_bytes: 5,
        };
        let before = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64;
        let mut recorder = Recorder::new(&output, &config).unwrap();
        recorder.record(&header, &[1, 2, 3, 4, 5]).unwrap();
        let after = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64;
        recorder.finalize().unwrap();
        let extracted = Command::new("tar")
            .args(["-xOf"])
            .arg(&output)
            .arg("frames.jsonl")
            .output()
            .unwrap();
        assert!(extracted.status.success());
        let row: serde_json::Value = serde_json::from_slice(&extracted.stdout).unwrap();
        assert_eq!(row["timestamp_ns"].as_u64(), Some(header.timestamp_ns));
        let host = row["host_arrival_unix_ns"].as_u64().unwrap();
        assert!((before..=after).contains(&host));
        assert_ne!(host, header.timestamp_ns);
        fs::remove_file(output).unwrap();
    }

    #[test]
    fn no_anatomy_driving_continuation_requires_same_frame_temporal_iris_texture() {
        let native = raw_iris_focus::OuterIrisBoundary::default();
        let temporal = DrivingAffinePose {
            center: (180.0, 120.0),
            major_radius: 70.0,
            minor_radius: 56.0,
            angle: 0.12,
        };
        assert!(driving_texture_corroborated_continuation_seed(
            &native,
            Some(((182.0, 121.0), 68.0)),
            None,
        )
        .is_none());

        let nearby = driving_texture_corroborated_continuation_seed(
            &native,
            Some(((182.0, 121.0), 68.0)),
            Some(temporal),
        )
        .expect("texture corroborates a nearby current RAW seed");
        assert_eq!(nearby.center, (182.0, 121.0));

        let remote = driving_texture_corroborated_continuation_seed(
            &native,
            Some(((310.0, 210.0), 42.0)),
            Some(temporal),
        )
        .expect("the promoted temporal seed survives a remote contour");
        assert_eq!(remote, temporal);
    }
